import{a as n}from"./shared-CAKwAg2C.js";const i={"LEARN HOW THE INTERNET WORKS":"איך האינטרנט עובד","NOW LEARNING":"לומדים עכשיו","OSI LAYER":"שכבת OSI","LEARNING PROGRESS":"התקדמות בלמידה",COMPLETE:"הושלמו","IN PROGRESS":"בתהליך","{pct}% complete":"{pct}% הושלמו","DESIGNED BY":"עיצוב","Dilum Sanjaya on X":"Dilum Sanjaya ב־X","Layer {n}: {name}":"שכבה {n}: {name}",Physical:"השכבה הפיזית","Data Link":"שכבת קו הנתונים",Network:"שכבת הרשת",Transport:"שכבת התעבורה",Session:"שכבת השיחה",Presentation:"שכבת התצוגה",Application:"שכבת היישום","OVERVIEW · {n} STEPS":"סקירה · {n} שלבים","STEP {n}/{total} · {title}":"שלב {n}/{total} · {title}","LESSON COMPLETE":"השיעור הושלם",PROTOCOLS:"פרוטוקולים",Protocols:"פרוטוקולים",Language:"שפה",Theme:"ערכת נושא","Light mode":"מצב בהיר","Dark mode":"מצב כהה","INTERNET PROTOCOLS":"פרוטוקולי אינטרנט",More:"עוד","Close the protocol list":"סגירת רשימת הפרוטוקולים","Close (Esc)":"סגירה (Esc)",ALL:"הכול",CORE:"בסיס",APPLICATION:"יישומים",SECURITY:"אבטחה",NETWORK:"רשת",SEQUENCE:"רצף",View:"תצוגה","Switch view (V)":"החלפת תצוגה (V)","Network diagram":"תרשים רשת","Sequence diagram":"תרשים רצף","STEP {n}":"שלב {n}","PROTOCOL OVERVIEW":"סקירת הפרוטוקול","STEP DETAILS":"פרטי השלב","LESSON SUMMARY":"סיכום השיעור",OVERVIEW:"התחלה",ACTIVE:"פעיל","STEP {n} OF {total}":"שלב {n} מתוך {total}","PACKET {n} OF {total}":"חבילה {n} מתוך {total}","PACKETS {from}–{to} OF {total}":"חבילות {from}–{to} מתוך {total}","{n} LOST":"{n} אבדו","1 LOST":"אחת אבדה",ENCRYPTED:"מוצפן","LOST ON THE WAY":"אבדה בדרך","PACKET FLOW":"זרימת חבילות","Colour key":"מקרא צבעים","Playback speed":"מהירות הפעלה","Previous step (←)":"השלב הקודם (→)","Previous step":"השלב הקודם","Play / pause (Space)":"הפעלה / השהיה (רווח)",PLAY:"הפעלה",PAUSE:"השהיה",REPLAY:"שוב",STEP:"צעד","One packet at a time":"חבילה אחת בכל פעם",RESET:"איפוס",Reset:"איפוס","Back to the overview (Esc)":"חזרה לסקירה (Esc)","NO.":"מס׳",TIME:"זמן",SOURCE:"מקור",DESTINATION:"יעד",PROTOCOL:"פרוטוקול",INFO:"מידע",SIZE:"גודל","No packets on the wire yet.":"עדיין אין חבילות על הקו.",LOST:"אבדה","Packet inspector":"בודק חבילות","Previous packet":"החבילה הקודמת","Previous packet (←)":"החבילה הקודמת (→)","Next packet":"החבילה הבאה","Next packet (→)":"החבילה הבאה (←)",Close:"סגירה","E.G.":"לדוגמה","an example value: it differs in every real capture":"ערך לדוגמה: שונה בכל לכידה אמיתית","bytes the lesson can’t show: encrypted, random, or a file’s contents":"בתים שהשיעור לא יכול להציג: מוצפנים, אקראיים או תוכן של קובץ",BYTES:"בתים","{n} in this frame":"{n} במסגרת הזו","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"שורה זו מייצגת {n} מקטעי TCP שנושאים הודעה של {size} בתים; מוצג המקטע הראשון","This packet was lost on the way":"החבילה הזו אבדה בדרך",Padding:"ריפוד","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · חכירה ל־24 שעות","2 SEGMENTS":"2 מקטעים","3 SEGMENTS":"3 מקטעים","3 DATAGRAMS":"3 דאטגרמות","4 DATAGRAMS":"4 דאטגרמות","203.0.113.10 IS NOT LOCAL":"203.0.113.10 אינו מקומי","250 QUEUED":"250 בתור",ANSWER:"תשובה","APP COVERS THE 20 MS GAP":"היישום מכסה את הפער של 20 ms","APP DATA":"נתוני יישום","ARP REPLY":"תשובת ARP","ARP REQUEST":"בקשת ARP","ARRIVED WITH TTL 116":"הגיעה עם TTL 116","AUTH FAILURE":"AUTH נכשל","At QUIT":"ב־QUIT","CACHED · TTL 3600 S":"במטמון · TTL 3600 ש׳","CERTIFICATE VALID":"התעודה תקפה","CHAIN LEADS TO A TRUSTED ROOT":"השרשרת מובילה לשורש מהימן","CHANNEL OPEN":"פתיחת ערוץ",CONFIRMED:"אושר","DNS QUERY":"שאילתת DNS","DNS REPLY":"תשובת DNS","DUP ACK":"ACK כפול","EACH KEY IS ITS OWN PACKET":"כל מקש בחבילה משלו",ECHO:"הד","ECHO REPLY":"תשובת הד","ECHO REQUEST":"בקשת הד",ENTER:"Enter","FRAME 7 LOST · NOT RESENT":"מסגרת 7 אבדה · לא נשלחת שוב","HOP 2 · 198.51.100.1":"קפיצה 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"מפתח המארח תואם ל־known_hosts","IN BOB’S MAILBOX":"בתיבת הדואר של Bob","IP PACKET":"חבילת IP",MESSAGE:"הודעה","MESSAGE 1 DELETED":"הודעה 1 נמחקה","NEW MAIL ARRIVED":"הגיע דואר חדש","NO IP ADDRESS YET":"עדיין אין כתובת IP","NOT IN CACHE":"לא במטמון","OFFER KEY":"הצגת מפתח",OUTPUT:"פלט","PASSWORD IN PLAIN TEXT":"סיסמה בטקסט גלוי",REFERRAL:"הפניה",REPLY:"תשובה",RESEND:"שליחה חוזרת","SEGMENT 1 LOST":"מקטע 1 אבד","SFTP or FTPS":"SFTP או FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP, או FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"הסוד המשותף חושב",SIGNED:"חתום","STILL ON SERVER · \\SEEN":"עדיין בשרת · \\Seen",SUCCESS:"הצלחה","TIME EXCEEDED":"חריגת זמן","TIME=34MS TTL=52":"TIME=34MS TTL=52",UNREACHABLE:"לא ניתן להגיע",VERSION:"גרסה","VOICE 1":"קול 1","+OK or -ERR":"+OK או -ERR",".com Server":"שרת .com",Authoritative:"שרת מוסמך","Log In":"התחברות",Key:"מפתח",Why:"למה",End:"סוף","MACs, in":"MAC, נכנס",Internet:"אינטרנט",Router:"נתב","Router 192.168.1.1":"נתב 192.168.1.1","Router: 192.168.1.1":"נתב: 192.168.1.1",Routers:"נתבים",Hardware:"חומרה",Audio:"אודיו",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"מה גלוי",Tickets:"כרטיסים","4, 20 bytes":"4, 20 בתים","20–60 bytes":"20–60 בתים","20–60 bytes (IPv4)":"20–60 בתים (IPv4)","8 bytes (TCP: 20+)":"8 בתים (TCP: 20+)","32 bytes (Windows)":"32 בתים (Windows)","1,460 bytes (MSS)":"1,460 בתים (MSS)","78 bytes (seq 1–78)":"78 בתים (seq 1–78)","bytes 1461–2920":"בתים 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 בתים)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 בתים)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 בתים), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 בתים)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 בתים)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 בתים)',"32 bits (IPv4), 128 (IPv6)":"32 סיביות (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 ← 52 (12 נתבים)","52 (64 − 12 routers)":"52 (64 − 12 נתבים)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 בתים","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 בתים (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + שמע","One packet at a time (S)":"חבילה אחת בכל פעם (S)","KEYBOARD SHORTCUTS":"קיצורי מקלדת","Press {key} any time to see these again.":"לחצו על {key} בכל זמן כדי לראות אותם שוב.","Search protocols":"חיפוש פרוטוקולים","Search protocols and steps":"חיפוש פרוטוקולים ושלבים","Nothing matches.":"אין תוצאות.","to move":"למעבר","to open":"לפתיחה","Protocol list":"רשימת הפרוטוקולים","Diagram only":"רק התרשים",Fullscreen:"מסך מלא","Keyboard shortcuts":"קיצורי מקלדת",Playback:"הפעלה","Hide the protocol list (L)":"הסתרת רשימת הפרוטוקולים (L)","Diagram only (D)":"רק התרשים (D)","Fullscreen (F)":"מסך מלא (F)","Keyboard shortcuts (?)":"קיצורי מקלדת (?)","Show the protocol list (L)":"הצגת רשימת הפרוטוקולים (L)","Show all panels (D)":"הצגת כל החלוניות (D)","Exit fullscreen (F)":"יציאה ממסך מלא (F)","Play or pause":"הפעלה או השהיה","Next step":"השלב הבא","Go to step 1 to 9":"מעבר לשלבים 1 עד 9","Slower, faster":"לאט יותר, מהר יותר","Back to the overview":"חזרה לסקירה","Network or sequence view":"תצוגת רשת או רצף","Show or hide the protocol list":"הצגה או הסתרה של רשימת הפרוטוקולים","Light or dark theme":"ערכת נושא בהירה או כהה",Find:"חיפוש","Next or previous protocol":"הפרוטוקול הבא או הקודם","These shortcuts":"קיצורים אלה","Previous or next packet":"החבילה הקודמת או הבאה","Close it":"סגירה"},h={"Hypertext Transfer Protocol":"פרוטוקול העברת היפרטקסט","HTTP Secure":"HTTP מאובטח","Transmission Control Protocol":"פרוטוקול בקרת שידור","User Datagram Protocol":"פרוטוקול דאטגרמות משתמש","Internet Protocol":"פרוטוקול האינטרנט","Domain Name System":"מערכת שמות המתחם","Dynamic Host Configuration":"הגדרת מארח דינמית","Internet Control Message":"הודעות בקרה באינטרנט","Simple Mail Transfer Protocol":"פרוטוקול העברת דואר פשוט","Post Office Protocol v3":"פרוטוקול סניף הדואר v3","Internet Message Access":"גישה להודעות אינטרנט","File Transfer Protocol":"פרוטוקול העברת קבצים","Secure Shell":"מעטפת מאובטחת","Transport Layer Security":"אבטחת שכבת התעבורה",Internet:"אינטרנט",Client:"לקוח",Router:"נתב","DNS Resolver":"רזולבר DNS","Web Server":"שרת ווב","Root Server":"שרת שורש",".com TLD Server":"שרת .com (TLD)","Authoritative Server":"שרת מוסמך","Mail Server":"שרת דואר","Web Communication":"תקשורת ווב",Request:"בקשה",Response:"תגובה","Data ACKs not shown":"אישורי ACK לנתונים לא מוצגים","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP הוא הפרוטוקול של הרשת: לקוח מבקש משאב, למשל דף HTML, והשרת עונה עם קוד מצב, כותרות ובדרך כלל גוף. כל חילופי מסרים הם בקשה אחת ותגובה אחת, שנכתבות ב־HTTP/1.1 כטקסט קריא.",Layer:"שכבה","Application (Layer 7)":"יישום (שכבה 7)","Default Port":"פורט ברירת מחדל",Transport:"שכבת התעבורה","Data Format":"פורמט הנתונים","Text (headers + optional body)":"טקסט (כותרות + גוף אופציונלי)","Common Methods":"שיטות נפוצות","Defined In":"מוגדר ב־","Page delivered":"הדף נמסר","One request, one response":"בקשה אחת, תגובה אחת","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"בפחות מעשירית שנייה המחשב הנייד מצא כתובת, פתח חיבור TCP והחליף בקשת HTTP אחת ותגובה אחת, וכל זה היה קריא לכל מי שנמצא בדרך. לחצו על ״שוב״ כדי לצפות שוב.","Round trips":"סבבים הלוך ושוב","Total time":"זמן כולל","Page size":"גודל הדף","Sent as 9 TCP segments":"נשלח ב־9 מקטעי TCP","Client Request":"בקשת הלקוח","Browser prepares the request":"הדפדפן מכין את הבקשה","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"אתם פותחים את http://www.example.com. הדפדפן ישלח בקשת GET, אבל חבילות נשלחות לכתובות IP ולא לשמות, ולכן קודם הוא צריך את כתובת השרת. (כיום דפדפנים מנסים קודם https://; זו הגרסה הלא מוצפנת.)",Method:"שיטה","Next hop":"הקפיצה הבאה","Router 192.168.1.1":"נתב 192.168.1.1","DNS Resolution":"פענוח DNS","Finds the server’s IP address":"מוצא את כתובת ה־IP של השרת","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"המחשב הנייד שואל את שרת ה־DNS שקיבל מ־DHCP (8.8.8.8) מה הכתובת של www.example.com. השאילתה נשלחת ב־UDP לפורט 53, והתשובה היא רשומת A עם כתובת ה־IPv4. (ברשת עם IPv6 הוא היה מבקש גם רשומת AAAA.)",Resolver:"רזולבר","8.8.8.8 (had it cached)":"8.8.8.8 (היה במטמון)","UDP, port 53":"UDP, פורט 53",Answer:"תשובה","TCP Connection":"חיבור TCP","Establishes a reliable link":"יוצר חיבור אמין","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP פועל מעל TCP. לפני שנתוני הדף מתחילים לעבור, המחשב הנייד והשרת פותחים חיבור לפורט 80 בלחיצת יד משולשת: SYN, SYN-ACK, ACK.","Server port":"פורט השרת","Client port":"פורט הלקוח",Handshake:"לחיצת יד","HTTP Exchange":"חילופי HTTP","Request and response messages":"הודעות בקשה ותגובה","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"הדפדפן שולח בקשת GET עם כותרת Host. השרת עונה 200 OK עם ה־HTML בגוף: 12.2 KB, גדול מדי לחבילה אחת, ולכן TCP מחלק אותו ל־9 מקטעים של עד 1460 בתים (מצוירים כאן כאחד).",Status:"סטטוס",Body:"גוף","Sent as":"נשלח כ־","12.2 KB in 9 segments":"12.2 KB ב־9 מקטעים","Page Rendering":"הצגת הדף","Browser displays the content":"הדפדפן מציג את התוכן","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"הדפדפן מנתח את ה־HTML ומצייר את הדף. כל קובץ CSS, תמונה או סקריפט מקושרים יפתחו בקשות נוספות בדיוק כמו זו, וישתמשו שוב בחיבור הפתוח כשאפשר.",Document:"מסמך",Connection:"חיבור","Kept open for reuse":"נשאר פתוח לשימוש חוזר","Seen on the laptop’s home network":"כפי שנראה ברשת הביתית של המחשב הנייד",Destination:"יעד","The router: anything beyond the home network goes to it first.":"הנתב: כל מה שיוצא מהרשת הביתית עובר קודם דרכו.",Source:"מקור","The laptop’s network card.":"כרטיס הרשת של המחשב הנייד.",Type:"סוג","What the frame carries.":"מה המסגרת נושאת.","Version, header length":"גרסה, אורך כותרת","IPv4, with no options.":"IPv4, ללא אפשרויות.","Priority and congestion marks; 0 means ordinary traffic.":"סימוני עדיפות ועומס; 0 פירושו תעבורה רגילה.","Total length":"אורך כולל","This header and everything inside it.":"הכותרת הזו וכל מה שבתוכה.",Identification:"זיהוי","Lets the receiver reassemble the pieces if the packet gets split.":"מאפשר למקבל להרכיב מחדש את החלקים אם החבילה פוצלה.",Flags:"דגלים",none:"אין","Routers may split it if a link is too small.":"נתבים רשאים לפצל אותה אם קישור כלשהו קטן מדי.","Time to live":"זמן חיים","Windows starts at 128.":"Windows מתחיל ב־128.",Protocol:"פרוטוקול","Header checksum":"סכום ביקורת של הכותרת","Covers this header only; every router recomputes it after lowering the TTL.":"מכסה רק את הכותרת הזו; כל נתב מחשב אותו מחדש אחרי שהוא מוריד את ה־TTL.","Source port":"פורט מקור","Destination port":"פורט יעד",Length:"אורך","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"כותרת UDP ונתונים. זה כל UDP: בלי מספור ובלי אישורים.",Checksum:"סכום ביקורת","Covers the header, the data and the IP addresses.":"מכסה את הכותרת, הנתונים וכתובות ה־IP.","Transaction ID":"מזהה טרנזקציה","Picked at random; the answer must carry the same one.":"נבחר באקראי; התשובה חייבת לשאת את אותו מזהה.","0x0100: query, RD (recursion desired)":"0x0100: שאילתה, RD (רקורסיה רצויה)",Questions:"שאלות",Answers:"תשובות","Authority records":"רשומות סמכות","Additional records":"רשומות נוספות",Question:"שאלה","www.example.com, type A, class IN":"www.example.com, סוג A, מחלקה IN","The laptop.":"המחשב הנייד.","The router’s side facing the home network.":"הצד של הנתב הפונה לרשת הביתית.","Started at 128; 10 routers on the way each took 1.":"התחיל ב־128; כל אחד מ־10 הנתבים בדרך הוריד 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: תגובה, RD (רקורסיה רצויה), RA (רקורסיה זמינה)","DF (don’t fragment)":"DF (אסור לפצל)","Routers must not split it; if it’s too big they report back instead.":"אסור לנתבים לפצל אותה; אם היא גדולה מדי הם מדווחים על כך בחזרה.","Picked by the laptop’s system for this connection.":"נבחר על ידי המערכת של המחשב הנייד לחיבור הזה.","Sequence number":"מספר רצף","This side’s starting number. Shown as 0; the real one is random.":"המספר ההתחלתי של הצד הזה. מוצג כ־0; המספר האמיתי אקראי.","Real sequence number":"מספר רצף אמיתי",Acknowledgment:"מספר אישור","0 (not used yet)":"0 (עדיין לא בשימוש)","A first SYN has nothing to acknowledge.":"ל־SYN הראשון אין מה לאשר.","Header length":"אורך כותרת","20 bytes, plus 12 of options.":"20 בתים, ועוד 12 של אפשרויות.",Window:"חלון","How much more data this side can take right now.":"כמה נתונים נוספים הצד הזה יכול לקבל עכשיו.","Covers the header, the data and the IP addresses, so damage is caught.":"מכסה את הכותרת, הנתונים וכתובות ה־IP, כך שנזק מתגלה.","Urgent pointer":"מצביע דחיפות",Options:"אפשרויות","Maximum segment size":"גודל מקטע מרבי","The most data this side wants in one segment.":"הכמות המרבית של נתונים שהצד הזה רוצה במקטע אחד.","Spacing, so the next option lines up.":"ריווח, כדי שהאפשרות הבאה תתחיל במקום הנכון.","Window scale":"קנה מידה לחלון","Window values are multiplied by this, so windows can be larger than 64 KB.":"ערכי החלון מוכפלים בזה, כך שחלונות יכולים להיות גדולים מ־64 KB.","SACK permitted":"SACK מותר",yes:"כן","This side understands selective acknowledgements.":"הצד הזה מבין אישורים סלקטיביים.","Started at 64; 12 routers on the way each took 1.":"התחיל ב־64; כל אחד מ־12 הנתבים בדרך הוריד 1.","The next byte this side expects: everything before it has arrived.":"הבית הבא שהצד הזה מצפה לו: כל מה שלפניו הגיע.","Position of this segment’s first byte, counted from this side’s SYN.":"מיקום הבית הראשון של המקטע הזה, נספר מה־SYN של הצד הזה.",Padding:"ריפוד","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"מסגרות Ethernet הן לפחות 60 בתים (64 עם סכום הביקורת שהכרטיס מוסיף), ולכן מסגרות קצרות מרופדות.",Text:"טקסט","covers bytes not shown here":"כולל בתים שלא מוצגים כאן","12,500 bytes: the HTML page":"12,500 בתים: דף ה־HTML","The page itself; its contents are not part of the lesson.":"הדף עצמו; התוכן שלו אינו חלק מהשיעור.","Secure Web":"ווב מאובטח","TLS handshake":"לחיצת יד TLS","HTTP request":"בקשת HTTP","HTTP response":"תגובת HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS הוא HTTP שנשלח דרך חיבור TLS מוצפן. TLS מוכיח בעזרת תעודה שהשרת הוא מי שהוא טוען שהוא, מסכם על מפתחות הצפנה חדשים, ואז מגן על כל בקשה ותגובה מפני קריאה או שינוי בדרך.","Application (HTTP over TLS)":"יישום (HTTP מעל TLS)",Security:"אבטחה","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 עדיין נפוץ)",Proves:"מוכיח","Server identity (certificate)":"זהות השרת (תעודה)","Secure page delivered":"הדף המאובטח נמסר","Encrypted, except the lookup":"מוצפן, חוץ מהחיפוש","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"הדפדפן חיפש את הכתובת ב־DNS לא מוצפן, פתח חיבור TCP, בדק את תעודת השרת וסיכם על מפתחות בסבב אחד הלוך ושוב. כל בית של HTTP אחרי זה עבר מוצפן. לחצו על ״שוב״ כדי לצפות שוב.",Cipher:"צופן","Still visible":"עדיין גלוי","IPs, server name, sizes":"כתובות IP, שם השרת, גדלים","Secure Request":"בקשה מאובטחת","Browser asks for https://":"הדפדפן מבקש https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"אתם מקלידים https://www.example.com. ה־״s״ אומרת לדפדפן להגן על החיבור באמצעות TLS, כברירת מחדל בפורט 443. לפני שהוא יכול להתחבר בכלל, הוא עדיין צריך למצוא את כתובת ה־IP של השרת.",Port:"פורט","DNS Lookup":"חיפוש DNS","Same lookup as HTTP, not encrypted":"אותו חיפוש כמו ב־HTTP, לא מוצפן","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"החיפוש זהה בדיוק לזה של HTTP רגיל: שאילתה ל־8.8.8.8 ב־UDP לפורט 53. הוא לא מוצפן, ולכן כל מי שבדרך יכול לראות על איזה שם שאלתם, אלא אם הדפדפן משתמש ב־DNS over HTTPS.",Encrypted:"מוצפן","No (plain DNS)":"לא (DNS רגיל)","TCP Handshake":"לחיצת יד TCP","Opens a connection to port 443":"פותח חיבור לפורט 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS נוסע על גבי TCP, ולכן קודם מגיעה אותה לחיצת יד משולשת, הפעם לפורט 443. שום דבר עוד לא מוצפן.","TLS Handshake":"לחיצת יד TLS","Agrees on keys, checks the certificate":"מסכם על מפתחות, בודק את התעודה","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"הדפדפן מציע צפנים ושיתופי מפתח, כולל שיטה היברידית פוסט־קוונטית. השרת בוחר בה ושולח את השיתוף שלו, ואחריו את התעודה שלו, כבר מוצפנת. הדפדפן בודק אותה מול רשויות שהוא סומך עליהן.",Version:"גרסה","Key exchange":"החלפת מפתחות","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (היברידי)","Server name":"שם השרת","Sent in clear (SNI)":"נשלח גלוי (SNI)","key shares: hybrid + x25519":"שיתופי מפתח: היברידי + x25519","cipher: AES_128_GCM_SHA256":"צופן: AES_128_GCM_SHA256","then encrypted: cert, Finished":"אחר כך מוצפן: תעודה, Finished","handshake complete (encrypted)":"לחיצת היד הושלמה (מוצפן)","Encrypted Exchange":"חילופים מוצפנים","HTTP inside TLS records":"HTTP בתוך רשומות TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"ה־GET וה־200 OK הם אותן הודעות HTTP כמו קודם, חתומות בתוך רשומות TLS שנראות על הקו כמו ״נתוני יישום״ אקראיים. השרת גם מוסר שני כרטיסי סשן, כדי שביקור מאוחר יותר יוכל לדלג על חלק מלחיצת היד.",Inside:"בפנים","GET / and 200 OK":"GET / ו־200 OK",Tickets:"כרטיסים","2, for faster reconnects":"2, לחיבור מחדש מהיר יותר","inside: GET / HTTP/1.1":"בפנים: GET / HTTP/1.1","outside: encrypted bytes":"בחוץ: בתים מוצפנים","inside: HTTP/1.1 200 OK":"בפנים: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"בחוץ: 12.9 KB, 9 מקטעים","Browser shows the padlock":"הדפדפן מציג את המנעול","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"הדפדפן מפענח את התגובה, מצייר את הדף ומציג מנעול: החיבור פרטי והשרת הוכיח את זהותו. הכותרת Strict-Transport-Security אומרת לו להשתמש מעכשיו ב־HTTPS לאתר הזה.",Remembers:"זוכר","HTTPS only (HSTS), 1 year":"רק HTTPS (HSTS), שנה אחת","Server Hello + encrypted handshake, 3 segments":"Server Hello + לחיצת יד מוצפנת, 3 מקטעים","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (מוצפן)","Application Data (HTTP request)":"Application Data (בקשת HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (מוצפן)","Application Data (HTTP response), 9 segments":"Application Data (תגובת HTTP), 9 מקטעים",Record:"רשומה","Content type":"סוג תוכן","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"הרשומה של Client Hello מציינת TLS 1.0 כדי שהתקני ביניים ישנים יעבירו אותה; הגרסאות האמיתיות מוצעות בפנים.","Handshake type":"סוג לחיצת יד",Contents:"תוכן","Everything the browser supports. Browsers vary a few details from one connection to the next.":"כל מה שהדפדפן תומך בו. דפדפנים משנים כמה פרטים מחיבור לחיבור.","Server name (SNI)":"שם השרת (SNI)","Versions offered":"גרסאות מוצעות","Key shares":"שיתופי מפתח","App protocols (ALPN)":"פרוטוקולי יישום (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"רשומות TLS 1.3 מציינות 1.2 מבחוץ, לשם תאימות.","The server’s choices and its half of the hybrid key exchange.":"הבחירות של השרת והחצי שלו בהחלפת המפתחות ההיברידית.","Cipher suite":"חבילת הצפנה","Key share":"שיתוף מפתח","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"אין לו תפקיד ב־TLS 1.3; נשלח כדי שהתקני ביניים יראו לחיצת יד מוכרת.","Every encrypted record says Application Data on the outside; the real type is inside.":"כל רשומה מוצפנת מציינת Application Data מבחוץ; הסוג האמיתי נמצא בפנים.","Encrypted data":"נתונים מוצפנים","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"טקסט מוצפן, שמסתיים בתג של 16 בתים שחושף כל שינוי. רק שני הקצוות יכולים לקרוא אותו.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (השרשרת), Certificate Verify (החתימה), Finished","Finished: a check value over the whole handshake":"Finished: ערך ביקורת על כל לחיצת היד","The HTTP request":"בקשת ה־HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket: מאפשר לביקור מאוחר יותר לחדש את הסשן","The HTTP response, then the 12,500-byte page":"תגובת ה־HTTP, ואחריה הדף בן 12,500 הבתים","Reliable Delivery":"מסירה אמינה","Handshake and ACKs":"לחיצת יד ואישורי ACK","Data from laptop":"נתונים מהמחשב הנייד","Data from server":"נתונים מהשרת","Closing (FIN)":"סגירה (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP הופך את מסירת החבילות ״במאמץ הטוב ביותר״ של האינטרנט לזרם בתים אמין ומסודר. הוא ממספר כל בית, מאשר את מה שמגיע, שולח מחדש את מה שאובד, ומווסת את קצב השולח כדי לא להציף את הצד השני או את הרשת.","Transport (Layer 4)":"תעבורה (שכבה 4)","Three-way handshake":"לחיצת יד משולשת",Reliability:"אמינות","Sequence numbers + ACKs":"מספרי רצף + ACK",Recovery:"התאוששות",Retransmission:"שידור חוזר",Header:"כותרת","Connection closed":"החיבור נסגר","Every byte accounted for":"כל בית נספר","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP פתח חיבור, מספר ואישר כל בית, זיהה פער ושלח מחדש רק את המקטע החסר, ואז סגר את שני הכיוונים בצורה מסודרת. curl קיבל כל בית לפי הסדר ולא הרגיש באובדן. לחצו על ״שוב״ כדי לצפות שוב.",Segments:"מקטעים","14 (1 lost, 1 resent)":"14 (1 אבד, 1 נשלח מחדש)","Bytes delivered":"בתים שנמסרו","78 up, 2,920 down":"78 בהעלאה, 2,920 בהורדה","Loss found by":"האובדן התגלה באמצעות","Duplicate ACK + SACK":"ACK כפול + SACK","Open Connection":"פתיחת חיבור","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl כבר יודע את כתובת השרת. לפני שנתונים כלשהם זזים, כל צד בוחר מספר רצף התחלתי ומאשר אותו: SYN, SYN-ACK, ACK. המספרים כאן יחסיים; האמיתיים מתחילים בערך אקראי.",Server:"שרת","203.0.113.10, port 80":"203.0.113.10, פורט 80","Send Data":"שליחת נתונים","Every byte is numbered":"כל בית ממוספר","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl שולח את בקשת ה־HTTP שלו בת 78 הבתים: בתים 1 עד 78. מספר ה־ACK של השרת, 79, הוא הבית הבא שהוא מצפה לו, כלומר כל מה שלפניו הגיע.",Sent:"נשלח","79 = next byte expected":"79 = הבית הבא הצפוי","Two Segments Back":"שני מקטעים בחזרה","One of them is lost":"אחד מהם אובד","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"השרת עונה ב־2,920 בתים: שני מקטעים מלאים של 1,460 בתים, המקסימום שנכנס כאן בחבילה אחת, שנשלחים זה אחר זה. הראשון נופל איפשהו באינטרנט; השני עובר.","Segment 1":"מקטע 1","bytes 1–1460 (lost)":"בתים 1–1460 (אבד)","Segment 2":"מקטע 2","Segment size":"גודל מקטע","seq=1 and seq=1461":"seq=1 ו־seq=1461","the first is lost":"הראשון אובד","A Gap Is Noticed":"מתגלה פער","Duplicate ACK with SACK":"ACK כפול עם SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"בתים 1461–2920 מגיעים, אבל 1–1460 לא הגיעו מעולם. ACK יכול לספור רק בתים שהתקבלו לפי הסדר, ולכן המחשב הנייד חוזר מיד על ACK 1 ומוסיף בלוק SACK שאומר שבתים 1461–2920 כבר אצלו.","1 (still waiting for byte 1)":"1 (עדיין מחכה לבית 1)","holds bytes 1461–2920":"בתים 1461–2920 אצלו","At once, not delayed":"מיד, בלי השהיה","sack: has 1461–2920":"sack: יש 1461–2920","Resend the Gap":"שליחת הפער מחדש","Only the missing bytes":"רק הבתים החסרים","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"ה־SACK אומר לשרת בדיוק מה חסר, ולכן הוא שולח מחדש רק את מקטע 1, והמחשב הנייד מאשר הכול. אילו לא היה חוזר שום ACK, טיימרים היו נכנסים לפעולה: קודם חבילת בדיקה אחרי כשני סבבים הלוך ושוב, ואחר כך פסק הזמן לשידור חוזר (לפחות 200 ms ב־Linux).",Resent:"נשלח מחדש","bytes 1–1460 only":"רק בתים 1–1460","Next ACK":"ה־ACK הבא","2921 (everything)":"2921 (הכול)","curl saw":"curl ראה","Every byte, in order":"כל בית, לפי הסדר","just the missing segment":"רק המקטע החסר","Close Connection":"סגירת חיבור","Each side says goodbye":"כל צד נפרד","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl סיים, ולכן הוא סוגר. כל כיוון נסגר בנפרד: המחשב הנייד שולח FIN והשרת מאשר אותו, ואז השרת שולח FIN משלו והמחשב הנייד מאשר אותו. המחשב הנייד שומר את פרטי החיבור לזמן מה (TIME-WAIT).","Closed by":"נסגר על ידי","A FIN from each side":"FIN מכל צד",Order:"סדר",Then:"ואז","Laptop waits (TIME-WAIT)":"המחשב הנייד ממתין (TIME-WAIT)",Data:"נתונים","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 בתים: תגובת ה־HTTP, בתים 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 בתים: תגובת ה־HTTP, בתים 1461–2920","has 1461–2920":"יש 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"בתים שהגיעו אחרי הפער, כך שרק את הפער צריך לשלוח מחדש.","Fast Datagrams":"דאטגרמות מהירות","Your voice":"הקול שלכם","Their voice":"הקול של הצד השני","Media Server":"שרת מדיה","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP שולח נתונים בחבילות עצמאיות שנקראות דאטגרמות, בלי חיבור, בלי אישורים ובלי שליחות חוזרות. זה שומר עליו מהיר וקל: מתאים לקול, וידאו, משחקים ו־DNS, שבהם תשובה מאוחרת גרועה יותר מתשובה חסרה.",None:"אין","None (no ACKs, no resends)":"אין (בלי ACK, בלי שליחה חוזרת)",Ordering:"סדר","Not guaranteed":"לא מובטח","Call keeps flowing":"השיחה ממשיכה לזרום","Fast, simple, no guarantees":"מהיר, פשוט, בלי התחייבויות","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"האודיו התחיל כבר עם החבילה הראשונה, כל דאטגרמה נסעה בעצמה, וזו שאבדה פשוט נעלמה: UDP לא שם לב בכלל. האפליקציה כיסתה את הפער והשיחה נמשכה. לחצו על ״שוב״ כדי לצפות שוב.",Datagrams:"דאטגרמות","11 (1 lost, never resent)":"11 (1 אבדה, לא נשלחה מחדש)","Setup time":"זמן הקמה","0 ms (no handshake)":"0 ms (בלי לחיצת יד)",Shown:"מוצג","The first 0.2 s of a call":"0.2 s הראשונות של שיחה","Send Right Away":"שליחה מיידית","No handshake, data goes first":"בלי לחיצת יד, הנתונים יוצאים ראשונים","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"אפליקציית שיחות כבר יודעת את הכתובת והפורט של שרת המדיה מההתחברות. היא לא פותחת חיבור: הדאטגרמה הראשונה כבר נושאת 20 ms מהקול שלכם, מאחורי כותרת UDP של 8 בתים.",Setup:"הקמה",Ports:"פורטים","92 B of audio, no setup":"92 B של אודיו, בלי הקמה","A Stream of Datagrams":"זרם של דאטגרמות","One every 20 ms, each on its own":"אחת כל 20 ms, כל אחת לעצמה","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"האפליקציה ממשיכה לשלוח דאטגרמה כל 20 ms. כל אחת עומדת בפני עצמה, עם כותרת משלה ובלי קשר לאחרות. UDP לא ממספר אותן, ושום דבר לא חוזר כדי לאשר שהן הגיעו.",Rate:"קצב","1 datagram / 20 ms":"1 דאטגרמה / 20 ms",Numbering:"מספור","None in UDP itself":"אין ב־UDP עצמו",Confirmation:"אישור","None (no ACKs)":"אין (בלי ACK)","voice frames 2–5":"מסגרות קול 2–5","each with its own 8-byte header":"כל אחת עם כותרת משלה של 8 בתים","Lost on the Way":"אבדה בדרך","Nobody resends it":"אף אחד לא שולח אותה מחדש","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"מסגרת 7 נופלת איפשהו באינטרנט. שרת המדיה אף פעם לא מבקש אותה, ו־UDP אף פעם לא מודיע למחשב הנייד: אין אישורים שיכולים להיעדר. הדאטגרמות שאחריה מגיעות כרגיל.",Lost:"אבדה","Voice frame 7":"מסגרת קול 7","Never (no ACKs)":"אף פעם (בלי ACK)",Missing:"חסר","20 ms of audio":"20 ms של אודיו","voice frames 6–8":"מסגרות קול 6–8","frame 7 is lost":"מסגרת 7 אובדת","Replies Come Back":"תשובות חוזרות","The other voice comes back":"הקול השני חוזר","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"הקול של הצד השני מגיע באותה דרך, כדאטגרמות נפרדות שנשלחות לפורט 50000. הן נכנסות כי הנתב שלכם זכר את הפורט היוצא כשתרגם את הכתובת שלכם (NAT).",Direction:"כיוון","Independent of ours":"בלתי תלוי בשלנו","Through NAT":"דרך NAT","Router remembers the port":"הנתב זוכר את הפורט","the other person’s voice":"הקול של הצד השני","sent to port 50000":"נשלח לפורט 50000","The App Decides":"האפליקציה מחליטה","Reliability is up to the app":"האמינות באחריות האפליקציה","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"אפליקציית השיחות ממספרת את המסגרות שלה בעצמה (RTP עושה את זה), ולכן היא רואה שמסגרת 7 חסרה ומחליקה את הפער של 20 ms במקום לחכות. המתנה לשליחה חוזרת הייתה גורמת לכל השיחה לפגר.","App’s job (e.g. RTP)":"תפקיד האפליקציה (למשל RTP)",Loss:"אובדן","Hidden by the app":"מוסתר על ידי האפליקציה","Also on UDP":"גם על UDP","DNS, games, QUIC":"DNS, משחקים, QUIC","Version etc.":"גרסה וכו׳","2, no padding, no extension, no CSRCs":"2, בלי ריפוד, בלי הרחבה, בלי CSRC","Marker, payload type":"סמן, סוג מטען","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, סוכם בהקמת השיחה)","Counts up by one per packet, so the app can spot a missing or late one.":"עולה באחד בכל חבילה, כדי שהאפליקציה תזהה חבילה חסרה או מאוחרת.",Timestamp:"חותמת זמן","Audio clock at 48,000 per second: +960 per 20 ms frame.":"שעון אודיו של 48,000 בשנייה: +960 לכל מסגרת של 20 ms.","Identifies this audio stream.":"מזהה את זרם האודיו הזה.",Audio:"אודיו","80 bytes of Opus audio (20 ms)":"80 בתים של אודיו Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, סוכם בהקמת השיחה)","Addressing & Routing":"מיעון וניתוב","Outgoing packet":"חבילה יוצאת",Reply:"תשובה","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP נותן לכל מכשיר כתובת ומעביר חבילות מרשת לרשת. כל נתב מסתכל רק על כתובת היעד כדי לבחור את הקפיצה הבאה. IP פועל ״במאמץ הטוב ביותר״: הוא לא מבטיח מסירה או סדר. TCP מוסיף אותם מעליו.","Network (Layer 3)":"רשת (שכבה 3)",Address:"כתובת","Lowered by 1 at each router":"יורד ב־1 בכל נתב",Delivery:"מסירה","Best effort":"במאמץ הטוב ביותר","There and back":"הלוך ושוב","Twelve routers each way":"שנים־עשר נתבים לכל כיוון","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"המחשב הנייד שלח את החבילה לנתב שלו, שהכניס בה את הכתובת הציבורית שלו. בסך הכול שנים־עשר נתבים העבירו אותה הלאה לפי כתובת היעד בלבד, והתשובה מצאה את דרכה חזרה באותה צורה. לחצו על ״שוב״ כדי לצפות שוב.",Routers:"נתבים","12 each way (1 home + 11)":"12 לכל כיוון (1 ביתי + 11)","TTL at server":"TTL בשרת","116 (sent with 128)":"116 (נשלח עם 128)","Rewritten by NAT":"משוכתב על ידי NAT","Source out, destination back":"המקור ביציאה, היעד בחזרה","IPv4 (IPv6 works alike)":"IPv4 (גם IPv6 עובד כך)","Local or Not?":"מקומי או לא?","Compare the address with the subnet":"משווים את הכתובת לתת־הרשת","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"למחשב הנייד יש כתובת 192.168.1.10 עם מסכה /24, ולכן הרשת שלו היא 192.168.1.0 עד 192.168.1.255. השרת, 203.0.113.10, מחוץ לטווח הזה, ולכן החבילה חייבת ללכת לשער ברירת המחדל: הנתב הביתי.",Laptop:"מחשב נייד","Local range":"טווח מקומי",Gateway:"שער","Find the Router":"מציאת הנתב","ARP turns an IP into a MAC":"ARP הופך IP ל־MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"ברשת המקומית, מסגרות נמסרות לפי כתובת MAC. אם כתובת ה־MAC של הנתב לא נמצאת במטמון ה־ARP של המחשב הנייד, הוא משדר לכולם ״למי יש 192.168.1.1?״ והנתב עונה עם כתובת ה־MAC שלו.",Asks:"שואל","Who has 192.168.1.1?":"למי יש 192.168.1.1?","Sent to":"נשלח אל","Everyone (broadcast)":"כולם (שידור)",Learns:"לומד","Router’s MAC address":"כתובת ה־MAC של הנתב","who has 192.168.1.1?":"למי יש 192.168.1.1?","tell 192.168.1.10":"תודיע ל־192.168.1.10","Send the Packet":"שליחת החבילה","Addresses, TTL and protocol":"כתובות, TTL ופרוטוקול","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"כותרת ה־IP נושאת את כתובות המקור והיעד, ערך TTL ואת הפרוטוקול שבפנים. כאן היא מכילה TCP SYN לפורט 443. Windows מתחיל את ה־TTL ב־128 (Linux ו־macOS משתמשים ב־64).","From → to":"מאיפה ← לאן","TTL 128 · protocol TCP":"TTL 128 · פרוטוקול TCP","NAT, Then Hop by Hop":"NAT, ואז קפיצה אחר קפיצה","The router rewrites and forwards":"הנתב משכתב ומעביר הלאה","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"הנתב מחליף את המקור הפרטי בכתובת הציבורית שלו 198.51.100.7 (וכאן את פורט 52344 ב־40112), רושם את המיפוי, ומוריד את ה־TTL ל־127. אחר כך 11 נתבים באינטרנט בוחרים כל אחד את הקפיצה הבאה לפי היעד ומורידים שוב את ה־TTL.","New source":"מקור חדש","Leaves home":"ביציאה מהבית","At the server":"בשרת","TTL 116 (11 more hops)":"TTL 116 (עוד 11 קפיצות)","TTL 127 · after NAT":"TTL 127 · אחרי NAT","The Reply Comes Back":"התשובה חוזרת","NAT translates it for the laptop":"NAT מתרגם אותה עבור המחשב הנייד","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"השרת עונה לכתובת שהוא ראה, 198.51.100.7:40112. הנתב מחפש אותה בטבלת ה־NAT שלו, משכתב את היעד בחזרה ל־192.168.1.10:52344 ומעביר אותה הלאה. התשובה התחילה עם TTL 64 ומגיעה עם 52.","Delivered to":"נמסר אל","TTL 52 · after NAT":"TTL 52 · אחרי NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (אחרי NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (אחרי NAT)","ARP request · 28 bytes":"בקשת ARP · 28 בתים","Broadcast: every device on the network receives it.":"שידור לכולם: כל מכשיר ברשת מקבל אותה.","The sender’s network card.":"כרטיס הרשת של השולח.","Hardware type":"סוג חומרה","Protocol type":"סוג פרוטוקול","Address sizes":"גודלי כתובות",Operation:"פעולה","1 (request: who has …?)":"1 (בקשה: למי יש …?)","Sender MAC":"MAC של השולח","Sender IP":"IP של השולח","Target MAC":"MAC של היעד","All zeros: this is what the request wants to find out.":"כולו אפסים: זה מה שהבקשה רוצה לגלות.","Target IP":"IP של היעד","ARP reply · 28 bytes":"תשובת ARP · 28 בתים","Straight back to the device that asked.":"ישירות בחזרה למכשיר ששאל.","2 (reply: … is at …)":"2 (תשובה: … נמצא ב־…)","Seen as it leaves the router’s internet side":"כפי שנראתה ביציאה מהצד של הנתב הפונה לאינטרנט","The internet provider’s router, the next hop.":"הנתב של ספק האינטרנט, הקפיצה הבאה.","The router’s internet-facing port.":"הפורט של הנתב הפונה לאינטרנט.","As sent: this system starts at 64.":"כפי שנשלח: המערכת הזו מתחילה ב־64.","The router’s NAT swapped in its own port for the laptop’s.":"ה־NAT של הנתב החליף את הפורט של המחשב הנייד בפורט משלו.","The sender’s next router; each hop puts the packet in a new frame.":"הנתב הבא של השולח; כל קפיצה מכניסה את החבילה למסגרת חדשה.","Name Resolution":"פענוח שמות",Query:"שאילתה",Referral:"הפניה","DNSSEC not requested here":"DNSSEC לא התבקש כאן","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS הופך שמות כמו www.example.com לכתובות IP שמחשבים משתמשים בהן כדי להגיע זה לזה. אין שרת אחד שמכיר כל שם: המערכת היא היררכיה של שרתים, ותשובות נשמרות במטמון לאורך הדרך, כך שרוב החיפושים לא צריכים להגיע רחוק.","53, UDP (TCP if large)":"53, UDP (או TCP אם גדול)",Turns:"הופך","Names into IP addresses":"שמות לכתובות IP",Hierarchy:"היררכיה","Root → TLD → authoritative":"שורש ← TLD ← מוסמך",Caching:"מטמון","For each record’s TTL":"לפי ה־TTL של כל רשומה","Name resolved":"השם פוענח","And remembered for an hour":"ונשמר לשעה","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"החל ממטמון ריק, הרזולבר עבר מהשורש ל־.com ולשרת של example.com עצמו, ואז ענה למחשב הנייד. עד שה־TTL יפוג, החיפוש הבא של השם הזה ייענה ישר מהמטמון. לחצו על ״שוב״ כדי לצפות שוב.",Queries:"שאילתות","4 (laptop 1, resolver 3)":"4 (המחשב הנייד 1, הרזולבר 3)","Cached for":"נשמר במטמון למשך","Ask the Resolver":"שואלים את הרזולבר","The laptop hands the question off":"המחשב הנייד מעביר את השאלה","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"הדפדפן צריך את כתובת ה־IP של www.example.com, ולא לו ולא ל־Windows יש אותה במטמון. המחשב הנייד שולח שאלה אחת לרזולבר הרקורסיבי שהוגדר לו, 8.8.8.8, ומבקש ממנו לבצע את כל החיפוש (רקורסיה רצויה).","www.example.com, type A":"www.example.com, סוג A",Asked:"נשאל","8.8.8.8 (recursive)":"8.8.8.8 (רקורסיבי)","RD (recursion desired)":"RD (רקורסיה רצויה)","flags: RD":"דגלים: RD","Points the way to .com":"מכוון אל .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"המטמון של הרזולבר ריק (הוא רק התחיל), ולכן הוא מתחיל מלמעלה. שרת שורש לא יודע את הכתובת, אבל הוא יודע אילו שרתים מטפלים ב־.com ועונה בהפניה. רזולברים רבים שולחים לו רק ״com״, לא את השם המלא.","Root servers":"שרתי שורש","13 names, 1,000+ anycast sites":"13 שמות, יותר מ־1,000 אתרי anycast","Referral (13 .com servers)":"הפניה (13 שרתי .com)","no answer: ask .com":"אין תשובה: לשאול את .com","Points the way to example.com":"מכוון אל example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"הרזולבר שואל אחד משרתי ה־.com. גם הם לא שומרים כתובות לכל אתר, אבל הם יודעים באילו שרתי שמות משתמש כל דומיין .com, ולכן גם התשובה הזו היא הפניה, עם הכתובות של אותם שרתים (glue) מצורפות.",Knows:"יודע","Name servers of .com domains":"שרתי השמות של דומיינים ב־.com","Referral + glue addresses":"הפניה + כתובות glue","no answer: ask example.com":"אין תשובה: לשאול את example.com","Gives the actual answer":"נותן את התשובה עצמה","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"לבסוף הרזולבר שואל את שרת השמות של example.com עצמו, שמחזיק את הרשומות של הדומיין. הוא עונה עם רשומת A ומסמן את התשובה כמוסמכת. בעל הדומיין קובע כמה זמן מותר לשמור אותה במטמון: כאן, 3600 שניות.","AA (authoritative), TTL 3600":"AA (מוסמך), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · דגל AA","Answer & Cache":"תשובה ומטמון","The laptop gets its address":"המחשב הנייד מקבל את הכתובת שלו","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"הרזולבר שולח את התשובה חזרה למחשב הנייד ושומר עותק. במשך השעה הבאה הוא יכול לענות על השם הזה מיד, ולכן החיפוש בשיעור ה־HTTP לקח רק 24 ms. גם המחשב הנייד שומר אותה במטמון.","RD, RA (recursion available)":"RD, RA (רקורסיה זמינה)","Cached by":"נשמר במטמון אצל","Resolver and laptop":"הרזולבר והמחשב הנייד","flags: RD RA":"דגלים: RD RA","Referral: com. NS ×13 (with glue)":"הפניה: com. NS ×13 (עם glue)","Referral: example.com. NS ×2 (with glue)":"הפניה: example.com. NS ×2 (עם glue)","Response A 203.0.113.10 (authoritative)":"תגובה A 203.0.113.10 (מוסמכת)","As sent: this system starts at 128.":"כפי שנשלח: המערכת הזו מתחילה ב־128.","0x0000: query":"0x0000: שאילתה","UDP size 1232, DNSSEC OK = 0":"גודל UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"מציין כמה גדולה יכולה להיות תשובת UDP. חתימות DNSSEC לא מתבקשות כאן, כדי שהשיעור יישאר קצר; רזולבר מאמת כמו 8.8.8.8 כן מבקש אותן.","0x8000: response":"0x8000: תגובה",Authority:"סמכות",Additional:"נוספות","0x8400: response, AA (authoritative)":"0x8400: תגובה, AA (מוסמכת)","Getting an Address":"קבלת כתובת","From the laptop":"מהמחשב הנייד","From the DHCP server":"משרת ה־DHCP","Dynamic Host Configuration Protocol":"פרוטוקול הגדרת מארח דינמית","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP נותן למכשיר כל מה שהוא צריך כדי להשתמש ברשת: כתובת IP, מסכת תת־רשת, הנתב שדרכו שולחים תעבורה ושרתי ה־DNS שאותם שואלים. כתובות מוחכרות לזמן קבוע ומחודשות כל עוד המכשיר נשאר ברשת.","UDP 67 (server), 68 (client)":"UDP 67 (שרת), 68 (לקוח)","Hands out":"מחלק","IP, mask, gateway, DNS":"IP, מסכה, שער, DNS",Exchange:"חילופים",Lease:"חכירה","Renewed at half its time":"מחודשת במחצית הזמן","On the network":"ברשת","Leased, and kept up to date":"מוחכרת, ומתעדכנת","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"ארבע הודעות לקחו את המחשב הנייד ממצב בלי כתובת להגדרה עובדת, ובמחצית החכירה של 24 שעות הוא חידש אותה בבקשה ישירה לנתב. לחצו על ״שוב״ כדי לצפות שוב.",Messages:"הודעות","4 to join, 2 per renewal":"4 להצטרפות, 2 לכל חידוש","24 h, renewed at 12 h":"24 h, חידוש אחרי 12 h","No Address Yet":"עדיין אין כתובת","The laptop joins the network":"המחשב הנייד מצטרף לרשת","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"המחשב הנייד בדיוק התחבר. יש לו כתובת MAC מובנית, אבל אין לו כתובת IP, שער או שרת DNS, ולכן הוא עוד לא יכול לדבר עם שום דבר מעבר לרשת שלו. הוא מבקש אותם באמצעות DHCP.","IP address":"כתובת IP","None (uses 0.0.0.0)":"אין (משתמש ב־0.0.0.0)","MAC address":"כתובת MAC",Needs:"צריך",Discover:"גילוי","Shout to the whole network":"קריאה לכל הרשת","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"בלי כתובת משלו, המחשב הנייד שולח מ־0.0.0.0 לכתובת השידור 255.255.255.255, כך שכל מכשיר ברשת המקומית מקבל את ההודעה. רק שרתי DHCP עונים.",From:"מאת","0.0.0.0, UDP port 68":"0.0.0.0, פורט UDP 68","255.255.255.255, port 67":"255.255.255.255, פורט 67",Carries:"נושא","MAC, transaction ID":"MAC, מזהה טרנזקציה","any DHCP server out there?":"יש כאן שרת DHCP?",Offer:"הצעה","The router proposes an address":"הנתב מציע כתובת","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"שרת ה־DHCP של הנתב בוחר כתובת פנויה ומציע אותה יחד עם שאר ההגדרות. המחשב הנייד עוד לא יכול להשתמש בכתובת IP, ולכן ההצעה נשלחת ישר לכתובת ה־MAC שלו (חלק מהלקוחות מבקשים שידור לכולם במקום).",Offered:"הוצע","Gateway, DNS":"שער, DNS","offer: 192.168.1.10/24":"הצעה: 192.168.1.10/24","gateway, DNS, lease 24 h":"שער, DNS, חכירה ל־24 h","Accept, out loud":"קבלה, בקול רם","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"המחשב הנייד מבקש את הכתובת שהוצעה, ומציין את השרת שבחר. הוא עדיין משדר לכולם, כך שכל שרת DHCP אחר שהציע הצעה יודע שלא נבחר ויכול לשחרר את הכתובת שלו.",Requests:"מבקש","Chosen server":"השרת שנבחר","I’ll take 192.168.1.10":"אני לוקח את 192.168.1.10","from server 192.168.1.1":"משרת 192.168.1.1",Acknowledge:"אישור","The address is the laptop’s":"הכתובת שייכת למחשב הנייד","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"השרת מאשר, והמחשב הנייד מגדיר את הכתובת, המסכה, השער ושרת ה־DNS. מערכות רבות בודקות קודם באמצעות ARP שאף מכשיר אחר לא משתמש כבר בכתובת.","DNS server":"שרת DNS","192.168.1.10 is yours":"192.168.1.10 שלך","for 24 hours":"ל־24 שעות",Renew:"חידוש","Halfway through the lease":"באמצע החכירה","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"שתים־עשרה שעות אחר כך, חצי מהחכירה עבר. עכשיו יש למחשב הנייד כתובת, ולכן הוא מבקש מהנתב ישירות להאריך את החכירה, והנתב מאפס אותה ל־24 שעות. אם הנתב לא היה עונה, הוא היה משדר לכולם ב־87.5%.",When:"מתי","50% of lease (T1 = 12 h)":"50% מהחכירה (T1 = 12 h)","The router (unicast)":"הנתב (unicast)","If unanswered":"אם אין תשובה","Broadcast at 87.5% (T2)":"שידור לכולם ב־87.5% (T2)","renew 192.168.1.10":"חידוש 192.168.1.10","sent straight to 192.168.1.1":"נשלח ישר ל־192.168.1.1","lease renewed":"החכירה חודשה","another 24 hours":"עוד 24 שעות",Message:"הודעה","1 (request, from a client)":"1 (בקשה, מלקוח)",Hardware:"חומרה","Ethernet, 6-byte addresses":"Ethernet, כתובות של 6 בתים",Hops:"קפיצות","Chosen by the client; every reply repeats it.":"נבחר על ידי הלקוח; כל תשובה חוזרת עליו.",Seconds:"שניות","0x0000 (unicast replies are fine)":"0x0000 (תשובות unicast בסדר)","Broadcast flag off: the server may send straight to the client’s MAC address.":"דגל השידור כבוי: השרת רשאי לשלוח ישר לכתובת ה־MAC של הלקוח.","Client address":"כתובת הלקוח","Filled in only when the client already has an address (renewing).":"ממולא רק כשכבר יש ללקוח כתובת (בחידוש).","Your address":"הכתובת שלך","The address the server is giving out.":"הכתובת שהשרת מחלק.","Next server":"השרת הבא","Relay agent":"סוכן ממסר","Client MAC":"MAC של הלקוח","Server name, boot file":"שם שרת, קובץ אתחול",empty:"ריק","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"מסמן שהאפשרויות שאחריו הן של DHCP.","Message type: 1 (Discover)":"סוג הודעה: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"מזהה לקוח: 01 00:00:5e:00:53:10","Host name: alice-laptop":"שם מארח: alice-laptop","Vendor class: MSFT 5.0":"מחלקת ספק: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"פרמטרים מבוקשים: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (תשובה, משרת)","Message type: 2 (Offer)":"סוג הודעה: 2 (Offer)","Server identifier: 192.168.1.1":"מזהה שרת: 192.168.1.1","Lease time: 86,400 s (24 h)":"זמן חכירה: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"זמן חידוש (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"זמן קישור מחדש (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"מסכת תת־רשת: 255.255.255.0","Broadcast address: 192.168.1.255":"כתובת שידור: 192.168.1.255","DNS server: 8.8.8.8":"שרת DNS: 8.8.8.8","Message type: 3 (Request)":"סוג הודעה: 3 (Request)","Requested address: 192.168.1.10":"כתובת מבוקשת: 192.168.1.10","Client FQDN: alice-laptop":"FQDN של הלקוח: alice-laptop","Message type: 5 (ACK)":"סוג הודעה: 5 (ACK)","Network Diagnostics":"אבחון רשת","Ping / probe":"Ping / בדיקה","Echo reply":"תשובת הד","Error report":"דיווח שגיאה","Internet Control Message Protocol":"פרוטוקול הודעות בקרה באינטרנט","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP הוא הדרך שבה הרשת מדווחת בחזרה: נתב אומר שהזמן של חבילה נגמר, שרת אומר ששום דבר לא מאזין בפורט. כלים כמו ping ו־traceroute בנויים מההודעות האלה. הוא נוסע בתוך IP אבל לא נושא נתוני יישום.","Carried in":"נישא בתוך","IP (protocol 1)":"IP (פרוטוקול 1)","A type and a code":"סוג וקוד",Tools:"כלים",Often:"לעיתים קרובות","Filtered by firewalls":"מסונן על ידי חומות אש","The network answered":"הרשת ענתה","Replies, expiries and errors":"תשובות, פקיעות ושגיאות","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"בקשת הד מדדה את זמן הסבב, חבילות עם TTL קטן גרמו לכל נתב בדרך להזדהות, ופורט סגור דווח ישר בחזרה. לחצו על ״שוב״ כדי לצפות שוב.","Round trip":"סבב הלוך ושוב",Path:"מסלול","12 routers, server at hop 13":"12 נתבים, השרת בקפיצה 13","Types used":"סוגים בשימוש","8, 0, 11 and 3":"8, 0, 11 ו־3","Reply TTL":"TTL של התשובה",Ping:"Ping","Echo request":"בקשת הד","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"״ping -n 1 203.0.113.10״ שולח בקשת הד אחת של ICMP (ping רגיל שולח ארבע, בהפרש של שנייה): סוג 8, קוד 0, עם מזהה, מספר רצף ו־32 בתים של מילוי. המערכת של השרת עונה בעצמה, בלי צורך באפליקציה.","Type, code":"סוג, קוד","8, 0 (echo request)":"8, 0 (בקשת הד)","type 8 · seq 1":"סוג 8 · seq 1","32 bytes of data":"32 בתים של נתונים","Echo Reply":"תשובת הד","Round-trip time":"זמן סבב","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"השרת שולח בחזרה תשובת הד, סוג 0, עם אותו מזהה, מספר רצף ונתונים. ping מדפיס את הזמן שלקח ואת ה־TTL שאיתו הגיעה התשובה: ״bytes=32 time=34ms TTL=52״.","0, 0 (echo reply)":"0, 0 (תשובת הד)","TTL on arrival":"TTL בהגעה","type 0 · seq 1":"סוג 0 · seq 1","same 32 bytes back":"אותם 32 בתים בחזרה","The first router answers":"הנתב הראשון עונה","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"״ping -n 1 -i 1״ שולח את אותה בקשה עם TTL של 1. הנתב הביתי מוריד אותו ל־0, ולכן הוא חייב להשליך את החבילה, והוא שולח בחזרה הודעת Time Exceeded מהכתובת שלו: ״Reply from 192.168.1.1: TTL expired in transit.״","Sent with":"נשלח עם","Dropped by":"הושלך על ידי","11, 0 (time exceeded)":"11, 0 (הזמן פג)","echo request":"בקשת הד","expires at the first router":"פג בנתב הראשון","type 11 · from 192.168.1.1":"סוג 11 · מ־192.168.1.1","quotes the dropped header":"מצטט את הכותרת שהושלכה","The next router answers":"הנתב הבא עונה","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"עם ״-i 2״, הנתב הביתי מוריד את ה־TTL ל־1 ומעביר הלאה. הנתב הראשון אצל ספק האינטרנט מוריד אותו ל־0 ומדווח בחזרה מ־198.51.100.1. הנתב הביתי מתרגם את הדיווח בחזרה למחשב הנייד כמו כל תשובה.","ISP router 198.51.100.1":"נתב הספק 198.51.100.1","expires at the second router":"פג בנתב השני","type 11 · from 198.51.100.1":"סוג 11 · מ־198.51.100.1","That’s Traceroute":"זה Traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … עד שמגיעים","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert עושה את זה אוטומטית: הוא מעלה את ה־TTL באחד בכל פעם, שולח שלוש בדיקות לכל קפיצה ומציג מי מדווח בחזרה. קפיצות 3 עד 12 עובדות באותה צורה, ועם TTL 13 הבקשה מגיעה סוף־סוף לשרת, שעונה כרגיל.","12 routers, then the server":"12 נתבים, ואז השרת","Per hop":"לכל קפיצה","3 probes":"3 בדיקות","On Linux":"ב־Linux","traceroute sends UDP":"traceroute שולח UDP","enough hops to arrive":"מספיק קפיצות כדי להגיע","the server itself answers":"השרת עצמו עונה","end of the route":"סוף המסלול",Unreachable:"לא ניתן להגיע","Nothing listening on that port":"שום דבר לא מאזין בפורט הזה","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"אפליקציה שולחת דאטגרמת UDP לפורט 9999, ששום דבר לא מאזין בו. השרת לא יכול למסור אותה, ולכן הוא עונה ב־Destination Unreachable, קוד 3 (הפורט לא זמין), ומצטט את תחילת הדאטגרמה. חומות אש רבות משליכות חבילות כאלה בשקט במקום זאת.","3, 3 (port unreachable)":"3, 3 (הפורט לא זמין)","Other codes":"קודים אחרים","0 net, 1 host, 4 too big":"0 רשת, 1 מארח, 4 גדול מדי",Firewalls:"חומות אש","Often silent instead":"לעיתים קרובות שותקות במקום","to port 9999":"לפורט 9999","nothing listening there":"שום דבר לא מאזין שם","type 3 · code 3":"סוג 3 · קוד 3","port unreachable":"הפורט לא זמין","ICMP · Echo request":"ICMP · בקשת הד",Code:"קוד","Covers the whole ICMP message.":"מכסה את כל הודעת ה־ICMP.",Identifier:"מזהה","Matches replies to this ping program.":"מתאים תשובות לתוכנית ה־ping הזו.","Windows counts up across every ping it sends.":"Windows סופר כלפי מעלה לאורך כל ping שהוא שולח.","Windows ping’s filler: the alphabet, a to w, then again.":"המילוי של ping ב־Windows: האלפבית, מ־a עד w, ושוב מההתחלה.","ICMP · Echo reply":"ICMP · תשובת הד","Sent back exactly as it came.":"נשלח בחזרה בדיוק כפי שהגיע.","ICMP · Time exceeded (TTL reached 0)":"ICMP · הזמן פג (ה־TTL הגיע ל־0)","Time exceeded (TTL reached 0)":"הזמן פג (ה־TTL הגיע ל־0)",Unused:"לא בשימוש","Original packet":"החבילה המקורית","Its source, destination":"המקור והיעד שלה","its IP header and first 8 bytes (28 bytes)":"כותרת ה־IP שלה ו־8 הבתים הראשונים (28 בתים)","App data":"נתוני אפליקציה","What the app sent; nothing on the server is listening for it.":"מה שהאפליקציה שלחה; שום דבר בשרת לא מאזין לזה.","ICMP · Destination unreachable (port unreachable)":"ICMP · היעד לא זמין (הפורט לא זמין)","Destination unreachable (port unreachable)":"היעד לא זמין (הפורט לא זמין)","Sending Email":"שליחת דואר","SMTP command":"פקודת SMTP","SMTP reply":"תשובת SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP מעביר דואר אלקטרוני: מאפליקציית הדואר שלכם לשרת של הספק שלכם, ומהשרת הזה לשרת של הנמען. זו שיחה של פקודות טקסט קצרות, שכל אחת מהן נענית בקוד תשובה בן שלוש ספרות. קריאת דואר היא עבודה אחרת, שנעשית עם IMAP או POP3.","465/587 submit, 25 relay":"465/587 הגשה, 25 ממסר","TCP, usually with TLS":"TCP, בדרך כלל עם TLS",Commands:"פקודות",Replies:"תשובות","2xx ok, 3xx go on, 4/5xx error":"2xx תקין, 3xx להמשיך, 4/5xx שגיאה","Mail delivered":"הדואר נמסר","Two hops, one message":"שתי קפיצות, הודעה אחת","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"האפליקציה של אליס מסרה את ההודעה לספק שלה בחיבור מוצפן ומאומת. הספק מצא ב־DNS את שרת הדואר של בוב והעביר אליו את ההודעה, אחרי ששדרג את הקישור הזה ל־TLS. עכשיו היא מחכה בתיבת הדואר של בוב עד שהוא יקרא אותה עם IMAP או POP3.","Laptop → provider → Bob’s":"מחשב נייד ← ספק ← השרת של בוב",Submission:"הגשה","Port 465, TLS, login":"פורט 465, TLS, התחברות",Relay:"ממסר","Port 25, STARTTLS":"פורט 25, STARTTLS","Checks at Bob’s":"בדיקות אצל בוב","Connect Securely":"התחברות מאובטחת","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"אליס לוחצת על ״שליחה״. אפליקציית הדואר שלה מתחברת לשרת ההגשה של הספק שלה, smtp.example.com, בפורט 465. בפורט הזה TLS מתחיל מיד, ולכן כל שיחת ה־SMTP, כולל הסיסמה שלה, מוצפנת.","TLS from the start":"TLS מההתחלה","SMTP inside TLS":"SMTP בתוך TLS","Greeting & Login":"ברכה והתחברות","EHLO, then AUTH":"EHLO, ואז AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"השרת מברך עם קוד 220. האפליקציה אומרת EHLO והשרת מפרט במה הוא תומך, כולל AUTH. האפליקציה מתחברת עם AUTH PLAIN (שם משתמש וסיסמה, בקידוד base64) ומקבלת 235: מאומת.",Greeting:"ברכה",Capabilities:"יכולות","Login result":"תוצאת ההתחברות","user and password, base64":"משתמש וסיסמה, base64","Send the Message":"שליחת ההודעה","Envelope, then content":"מעטפה, ואז תוכן","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM ו־RCPT TO הם המעטפה: השולח והנמען. PIPELINING מאפשר לשלוש הפקודות לחלוק חבילה אחת. אחרי 354 מגיעה ההודעה, שמסתיימת בשורה שיש בה רק נקודה.",Envelope:"מעטפה","Content ends":"סוף התוכן","A line with only “.”":"שורה עם ״.״ בלבד",Result:"תוצאה","… message …":"… ההודעה …","Find Bob’s Server":"מציאת השרת של בוב","An MX lookup in DNS":"חיפוש MX ב־DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"הספק של אליס צריך עכשיו למסור ל־example.org. הוא שואל את ה־DNS על רשומת ה־MX של הדומיין, שמציינת את השרת שמקבל את הדואר שלו, ואז מחפש את הכתובת של אותו שרת.","MX record":"רשומת MX","Asked by":"נשאל על ידי","Alice’s provider":"הספק של אליס","Server to Server":"משרת לשרת","Port 25, upgraded with STARTTLS":"פורט 25, משודרג עם STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"הספק מתחבר ל־mx.example.org בפורט 25. השיחה הזו מתחילה כטקסט גלוי: הברכה והתשובה ל־EHLO מפרסמות STARTTLS, הספק מבקש אותו, מקבל 220 ושני הצדדים עוברים ל־TLS.","Starts as":"בהתחלה","Plain text":"טקסט גלוי",Upgrade:"שדרוג",Deliver:"מסירה","The same transaction again":"אותה טרנזקציה שוב","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"כש־TLS פעיל, הספק חוזר על EHLO, ואז על המעטפה וההודעה, עכשיו עם חתימת DKIM וכותרת Received שנוספו. השרת של בוב בודק SPF, DKIM ו־DMARC ומקבל אותה.","Login needed":"נדרשת התחברות","No (server to server)":"לא (משרת לשרת)","1,316 bytes (signed)":"1,316 בתים (חתום)","Server Hello + encrypted handshake, 2 segments":"Server Hello + לחיצת יד מוצפנת, 2 מקטעים","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 יכולות (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (פרטי הזדהות)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (ברצף, בלי המתנה)","Message (316 bytes), then “.”":"הודעה (316 בתים), ואז ״.״","250 capabilities (PIPELINING, STARTTLS …)":"250 יכולות (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 יכולות (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"הודעה (1,316 בתים), ואז ״.״","What this client supports. Its exact contents vary from client to client; this is an example.":"במה הלקוח הזה תומך. התוכן המדויק משתנה מלקוח ללקוח; זו דוגמה.","up to 512 bytes":"עד 512 בתים","The server’s choices and its key share.":"הבחירות של השרת ושיתוף המפתח שלו.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (השרשרת), Certificate Verify (החתימה), Finished","Alice’s message (316 bytes), then a line holding only “.”":"ההודעה של אליס (316 בתים), ואז שורה שיש בה רק ״.״","example.org, type MX, class IN":"example.org, סוג MX, מחלקה IN","mx.example.org, type A, class IN":"mx.example.org, סוג A, מחלקה IN",Timestamps:"חותמות זמן","Used to measure round trips; both sides offered them.":"משמשות למדידת סבבים; שני הצדדים הציעו אותן.","The signed message (1,316 bytes), then a line holding only “.”":"ההודעה החתומה (1,316 בתים), ואז שורה שיש בה רק ״.״","Downloading Email":"הורדת דואר","POP3 command":"פקודת POP3","POP3 reply":"תשובת POP3","Post Office Protocol, version 3":"פרוטוקול סניף הדואר, גרסה 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3 מאפשר לאפליקציית דואר להוריד הודעות מתיבת דואר בשרת. הוא תוכנן למכשיר אחד שמביא את הדואר ואז מוחק אותו מהשרת. הפקודות הן מילים קצרות, וכל תשובה מתחילה ב־+OK או ב־-ERR.",Model:"מודל","Download, then delete":"הורדה, ואז מחיקה","Mail downloaded":"הדואר הורד","And gone from the server":"ונעלם מהשרת","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"האפליקציה של בוב התחברה, ראתה שתי הודעות, הורידה את הראשונה ומחקה אותה, והשרת ביצע את המחיקה ב־QUIT. ההודעה הזו נמצאת עכשיו רק במחשב הנייד הזה, ולכן POP3 מתאים למכשיר אחד ו־IMAP מתאים לכמה מכשירים.","2 waiting, 1 downloaded":"2 ממתינות, 1 הורדה",Deleted:"נמחקה","At QUIT (UPDATE state)":"ב־QUIT (מצב UPDATE)","Best for":"מתאים במיוחד","A single device":"מכשיר יחיד","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"אפליקציית הדואר של בוב מתחברת ל־pop.example.org בפורט 995, שבו TLS מתחיל מיד. בתוכו, השרת מברך עם +OK. (בפורט 110 הסשן מתחיל כטקסט גלוי ומשודרג עם הפקודה STLS.)","USER, then PASS":"USER, ואז PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"האפליקציה שולחת את שם המשתמש עם USER ואת הסיסמה עם PASS. כל פקודה מקבלת +OK משלה. מכיוון שהסשן נמצא בתוך TLS, הסיסמה לא קריאה בדרך.","Protected by":"מוגן על ידי","Check the Mailbox":"בדיקת תיבת הדואר","STAT and LIST":"STAT ו־LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT מחזיר את מספר ההודעות ואת הגודל הכולל שלהן: 2 הודעות, 5120 בתים. LIST נותן את המספר והגודל של כל הודעה, ומסתיים בשורה שיש בה רק נקודה.","Message 1":"הודעה 1","Message 2":"הודעה 2",Download:"הורדה","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 מבקש את ההודעה הראשונה. השרת עונה +OK עם הגודל שלה, ואז את ההודעה ונקודה סוגרת: 1904 בתים ועוד שורת התשובה, שני מקטעי TCP.",Command:"פקודה","Delete & Quit":"מחיקה ויציאה","Deleted only at QUIT":"נמחקת רק ב־QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 רק מסמן את ההודעה. השרת מוחק אותה כשהאפליקציה אומרת QUIT: אם החיבור היה נופל לפני כן, שום דבר לא היה נמחק. אפליקציות רבות מציעות ״להשאיר עותק בשרת״, מה שמדלג על DELE.","Marks message 1":"מסמן את הודעה 1",Removed:"הוסרה",Option:"אפשרות","Leave a copy on server":"להשאיר עותק בשרת","PASS (password)":"PASS (סיסמה)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, ההודעה, ״.״ (2 מקטעים)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, ההודעה בת 1,904 הבתים, ואז שורה שיש בה רק ״.״","IMAP command":"פקודת IMAP","IMAP response":"תגובת IMAP","Internet Message Access Protocol":"פרוטוקול גישה להודעות אינטרנט","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP מאפשר לאפליקציות דואר לעבוד עם תיבת דואר שנשארת בשרת. תיקיות, סימוני ״נקרא״ ו״מסומן״ ומחיקות נשמרים שם, כך שטלפון, מחשב נייד ודואר ווב רואים כולם את אותה תיבה. השרת יכול גם להודיע לאפליקציה על דואר חדש ברגע שהוא מגיע.","Mail stays on the server":"הדואר נשאר בשרת",Syncs:"מסנכרן","Folders and flags":"תיקיות ודגלים","Mailbox in sync":"תיבת הדואר מסונכרנת","Read once, read everywhere":"נקרא פעם אחת, נקרא בכל מקום","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"האפליקציה של בוב פתחה את תיבת הדואר הנכנס שלו, קראה הודעה, מה שסימן אותה \\Seen בשרת עבור כל המכשירים שלו, ואז המתינה עם IDLE עד שהשרת הודיע על דואר חדש. שום דבר לא נמחק: השרת עדיין מחזיק הכול.","2, then 3 (new mail)":"2, ואז 3 (דואר חדש)","Read mark":"סימון ״נקרא״","\\Seen, stored on server":"\\Seen, נשמר בשרת","New mail":"דואר חדש","Pushed during IDLE":"נדחף בזמן IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"האפליקציה של בוב מתחברת ל־imap.example.org בפורט 993, שבו TLS מתחיל מיד. השרת מברך בשורת ״* OK״ ללא תג, שמפרטת גם את היכולות שלו, כמו IDLE.","Commands carry tags":"לפקודות יש תגים","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"כל פקודה מתחילה בתג שהאפליקציה בוחרת, כמו a1, והשרת מסיים את התשובה שלו באותו תג. כך כמה פקודות יכולות להיות בדרך בו־זמנית וכל תשובה מותאמת לפקודה שלה. שורות שמתחילות ב־* הן נתונים ללא תג.",Tags:"תגים","Match replies to commands":"מתאימים תשובות לפקודות","Open the Inbox":"פתיחת תיבת הדואר הנכנס","SELECT a folder":"SELECT לתיקייה","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX פותח את התיקייה. השרת מדווח על מספר ההודעות, הדגלים שהוא תומך בהם וההודעה הראשונה שלא נקראה, ואז מאשר שהתיקייה פתוחה לקריאה וכתיבה.","First unread":"ראשונה שלא נקראה",Access:"גישה","Read a Message":"קריאת הודעה","FETCH, and the \\Seen flag":"FETCH, והדגל \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] מוריד את הודעה 2 (שלושה מקטעי TCP). זה מציב את הדגל \\Seen שלה בשרת, כך שהיא מופיעה כנקראה גם בטלפון של בוב, וההודעה נשארת שם.","Flag set":"דגל שהוצב","\\Seen (on the server)":"\\Seen (בשרת)","Wait for New Mail":"המתנה לדואר חדש","IDLE: the server pushes":"IDLE: השרת דוחף","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE אומר לשרת ״תודיע לי כשמשהו משתנה״. כ־42 שניות אחר כך ההודעה של אליס מגיעה והשרת דוחף מיד ״* 3 EXISTS״. האפליקציה מסיימת את IDLE עם DONE ויכולה להביא את הדואר החדש.","Server says":"השרת אומר","* 3 EXISTS (new mail)":"* 3 EXISTS (דואר חדש)","Ended by":"הסתיים על ידי","a1 LOGIN (user and password)":"a1 LOGIN (משתמש וסיסמה)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, ההודעה בת 3,216 הבתים, ואז a3 OK FETCH completed","Transferring Files":"העברת קבצים","FTP command":"פקודת FTP","FTP reply":"תשובת FTP","File data":"נתוני קובץ","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP מעביר קבצים בין לקוח לשרת. הוא חריג בכך שהוא משתמש בשני חיבורי TCP: אחד לפקודות ולתשובות, וחיבור חדש לכל קובץ או רשימה. הוא מתחילת שנות ה־70 ושולח הכול, כולל סיסמאות, כטקסט גלוי.","21 control, data varies":"21 בקרה, הנתונים משתנים",Connections:"חיבורים","Control + one per transfer":"בקרה + אחד לכל העברה",Encryption:"הצפנה","None (plain text)":"אין (טקסט גלוי)","Safer options":"אפשרויות בטוחות יותר","File downloaded":"הקובץ הורד","Two connections, no encryption":"שני חיבורים, בלי הצפנה","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"הפקודות עברו בחיבור הבקרה, הקובץ בחיבור נתונים משלו, וסגירת החיבור הזה סימנה את סוף הקובץ. כל מי שבדרך יכול היה לקרוא את הסיסמה ואת הקובץ, ולכן היום משתמשים ב־SFTP או ב־FTPS.","2 (control + data)":"2 (בקרה + נתונים)",File:"קובץ","4,000 bytes, 3 segments":"4,000 בתים, 3 מקטעים",Password:"סיסמה","Sent in plain text":"נשלחת כטקסט גלוי","Use instead":"במקום זה","Control Connection":"חיבור בקרה","Port 21, plain text":"פורט 21, טקסט גלוי","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"אפליקציית ה־FTP פותחת חיבור TCP ל־ftp.example.com בפורט 21. חיבור הבקרה הזה נושא פקודות ותשובות לאורך כל הסשן. השרת מברך עם 220. כמו ב־SMTP, כל תשובה מתחילה בקוד בן שלוש ספרות.","USER and PASS, readable by anyone":"USER ו־PASS, קריאים לכל אחד","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"האפליקציה שולחת USER, השרת מבקש את הסיסמה עם 331, ו־PASS שולח אותה. שום דבר לא מוצפן, ולכן שם המשתמש והסיסמה חוצים כל רשת בדרך כטקסט קריא.","Visible to":"גלוי עבור","Anyone on the path":"כל מי שבדרך","Passive Mode":"מצב פסיבי","The server names a data port":"השרת מציין פורט נתונים","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I מבקש עותק בינארי זהה בית אחר בית. PASV מבקש מהשרת לפתוח פורט לחיבור הנתונים. התשובה מקודדת את הכתובת והפורט כשישה מספרים: 195 × 256 + 149 = פורט 50069. המחשב הנייד מתחבר החוצה, וזה עובד דרך NAT.","Data port":"פורט נתונים","Active mode":"מצב אקטיבי","Server dials in: NAT blocks":"השרת מתקשר פנימה: NAT חוסם","Data Connection":"חיבור נתונים","A second TCP connection":"חיבור TCP שני","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"האפליקציה פותחת חיבור TCP שני, לפורט 50069, ומבקשת את הקובץ בחיבור הבקרה עם RETR. השרת עונה שם 150 ומתחיל לשלוח את הקובץ בחיבור החדש.","Data to":"נתונים אל","The File Arrives":"הקובץ מגיע","Closing the connection ends it":"סגירת החיבור מסיימת אותו","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"4,000 הבתים מגיעים ב־3 מקטעי TCP. FTP לא שולח סימון אורך בתוך הנתונים עצמם: השרת סוגר את חיבור הנתונים כדי לסמן את סוף הקובץ. אחרי שהמחשב הנייד אישר הכול, השרת מאשר עם 226 בחיבור הבקרה.","End of file":"סוף הקובץ","Data connection closed":"חיבור הנתונים נסגר","4,000 bytes, readable by anyone":"4,000 בתים, קריאים לכל אחד","end of file:":"סוף הקובץ:","data connection closed":"חיבור הנתונים נסגר",Quit:"יציאה","Close the control connection":"סגירת חיבור הבקרה","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT מסיים את הסשן והשרת נפרד עם 221. לכל דבר רגיש, SFTP (פרוטוקול אחר, שרץ מעל SSH) או FTPS (FTP בתוך TLS) עושים את אותה עבודה עם הצפנה.","Encrypted cousins":"קרובי משפחה מוצפנים","FTP data":"נתוני FTP","The file itself, unencrypted: anyone on the path could read it.":"הקובץ עצמו, לא מוצפן: כל מי שבדרך יכול היה לקרוא אותו.","Secure Remote Login":"גישה מרחוק בטוחה","Plain setup":"הקמה גלויה","From laptop":"מהמחשב הנייד","From server":"מהשרת","Some packets not shown":"חלק מהחבילות לא מוצגות","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH נותן לכם חיבור מוצפן ומאומת למחשב אחר, כדי להריץ עליו פקודות, להעתיק קבצים (SFTP, scp) או להעביר חיבורים אחרים. השרת מוכיח מי הוא באמצעות מפתח מארח; אתם מוכיחים מי אתם באמצעות זוג מפתחות או סיסמה.","Server proves":"השרת מוכיח","Host key (known_hosts)":"מפתח מארח (known_hosts)","You prove":"אתם מוכיחים","Key pair or password":"זוג מפתחות או סיסמה","Logged in securely":"מחוברים בצורה מאובטחת","Encrypted from the key exchange on":"מוצפן מהחלפת המפתחות והלאה","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"שני הצדדים הסכימו על אלגוריתמים, בנו מפתחות משותפים בהחלפה היברידית פוסט־קוונטית, והשרת הוכיח את זהותו עם מפתח המארח שלו. אליס הוכיחה את זהותה בחתימה עם מפתח פרטי שמעולם לא עזב את המחשב הנייד, ואז הקלידה פקודה, חבילה אחת לכל הקשה.",Login:"התחברות","Ed25519 key, no password":"מפתח Ed25519, בלי סיסמה","Say Hello":"אומרים שלום","Versions, in plain text":"גרסאות, בטקסט גלוי","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"אליס מריצה ״ssh alice@server.example.com״. אחרי לחיצת היד של TCP בפורט 22, כל צד שולח שורה אחת של טקסט גלוי שמציינת את גרסת פרוטוקול SSH (2.0) ואת התוכנה שלו. כל השאר ב־SSH בינארי.","Agree on Algorithms":"הסכמה על אלגוריתמים","KEXINIT lists, first match wins":"רשימות KEXINIT, ההתאמה הראשונה מנצחת","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"כל צד שולח KEXINIT שמפרט כל אלגוריתם שהוא תומך בו, לפי סדר העדפה, להחלפת מפתחות, מפתחות מארח, הצפנה, שלמות ודחיסה. בכל קטגוריה נבחר האלגוריתם הראשון ברשימה של המחשב הנייד שגם השרת תומך בו.","Host key":"מפתח מארח","server’s algorithm lists":"רשימות האלגוריתמים של השרת","in order of preference":"לפי סדר העדפה","laptop’s algorithm lists":"רשימות האלגוריתמים של המחשב הנייד","Key Exchange":"החלפת מפתחות","Shared keys, and a host key check":"מפתחות משותפים, ובדיקת מפתח המארח","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"המחשב הנייד שולח את החצי שלו בהחלפה היברידית: מפתח Streamlined NTRU Prime, שנבחר כדי לעמוד בפני מחשבים קוונטיים עתידיים, ועוד מפתח X25519. השרת עונה עם החצי שלו, מפתח המארח שלו וחתימה על ההחלפה. NEWKEYS מפעיל את ההצפנה.",Hybrid:"היברידי","Matches known_hosts":"תואם ל־known_hosts","First visit":"ביקור ראשון","ssh asks you to confirm":"ssh מבקש מכם לאשר","public keys":"מפתחות ציבוריים","its half, its host key":"החצי שלו, מפתח המארח שלו","and a signature":"וחתימה","Log In with a Key":"התחברות עם מפתח","Sign, don’t send a secret":"חותמים, לא שולחים סוד","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"השרת מפרט את שיטות ההתחברות שהוא מקבל. המחשב הנייד מציע את המפתח הציבורי של אליס, והשרת אומר שהוא יקבל אותו. אז המחשב הנייד חותם על הסשן הזה עם המפתח הפרטי, שאף פעם לא עוזב את המחשב הנייד. השרת בודק את החתימה מול authorized_keys.",Methods:"שיטות","Ed25519, private stays here":"Ed25519, הפרטי נשאר כאן","Checked with":"נבדק מול","alice’s public key":"המפתח הציבורי של alice","would you accept it?":"תקבל אותו?","yes, that key":"כן, המפתח הזה","is in authorized_keys":"נמצא ב־authorized_keys","same key, plus a signature":"אותו מפתח, ועוד חתימה","made with the private key":"שנוצרה עם המפתח הפרטי","logged in":"מחובר","Open a Session":"פתיחת סשן","Channels inside one connection":"ערוצים בתוך חיבור אחד","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"חיבור SSH אחד יכול לשאת ערוצים רבים: מעטפת, העברות קבצים, פורטים מועברים. המחשב הנייד פותח ערוץ סשן, ואז מבקש מסוף ומעטפת (לא מוצג), והשרת שולח את טקסט הפתיחה שלו ושורת פקודה.",Channel:"ערוץ",session:"session","Then asks for":"אחר כך מבקש","A terminal and a shell":"מסוף ומעטפת","Also possible":"אפשרי גם","SFTP, port forwarding":"SFTP, העברת פורטים","open a channel:":"פתיחת ערוץ:","channel open":"הערוץ נפתח","Type a Command":"הקלדת פקודה","Every key is a packet":"כל הקשה היא חבילה","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"אליס מקלידה pwd. כל הקשה יוצאת מיד בחבילה מוצפנת משלה, והשרת שולח את התו בחזרה כדי שיוצג (ההד). מאז גרסה 9.5, OpenSSH שולח הקשות בקצב של 20 ms ומוסיף חבילות פיתיון, כך שקשה יותר לקרוא את קצב ההקלדה מהתזמון.","Per key":"לכל הקשה","1 packet, 90 bytes":"1 חבילה, 90 בתים",Echo:"הד","Sent back by the server":"נשלח בחזרה על ידי השרת",Timing:"תזמון","20 ms beat plus decoys":"קצב של 20 ms ועוד פיתיונות","Enter key":"מקש Enter","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"לקוח: KEX_ECDH_INIT (מפתחות ציבוריים sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"שרת: KEX_ECDH_REPLY (מפתח מארח, החצי שלו, חתימה)","Encrypted (len=44): service request, ssh-userauth":"מוצפן (len=44): בקשת שירות, ssh-userauth","Encrypted (len=44): service accept":"מוצפן (len=44): השירות התקבל","Encrypted (len=68): login with method none":"מוצפן (len=68): התחברות בשיטה none","Encrypted (len=52): try publickey,password":"מוצפן (len=52): נסו publickey,password","Encrypted (len=140): offer public key":"מוצפן (len=140): הצעת מפתח ציבורי","Encrypted (len=100): public key OK":"מוצפן (len=100): המפתח הציבורי בסדר","Encrypted (len=308): public key + signature":"מוצפן (len=308): מפתח ציבורי + חתימה","Encrypted (len=28): login success":"מוצפן (len=28): ההתחברות הצליחה","Encrypted (len=52): channel open: session":"מוצפן (len=52): פתיחת ערוץ: session","Encrypted (len=44): channel open confirmed":"מוצפן (len=44): פתיחת הערוץ אושרה","Encrypted (len=36): keystroke":"מוצפן (len=36): הקשה","Encrypted (len=36): echo":"מוצפן (len=36): הד","Encrypted (len=36): keystroke (Enter)":"מוצפן (len=36): הקשה (Enter)","Encrypted (len=132): output and a new prompt":"מוצפן (len=132): פלט ושורת פקודה חדשה","Packet length":"אורך חבילה","Bytes after this field.":"הבתים שאחרי השדה הזה.","Padding length":"אורך ריפוד","Random padding brings the packet to a multiple of 8 bytes.":"ריפוד אקראי מביא את החבילה לכפולה של 8 בתים.",Cookie:"Cookie","Host keys":"מפתחות מארח","Ciphers, out":"צפנים, יוצא","Ciphers, in":"צפנים, נכנס","MACs, out":"MAC, יוצא","Compression, out":"דחיסה, יוצא","Compression, in":"דחיסה, נכנס","Languages, out":"שפות, יוצא","Languages, in":"שפות, נכנס","First packet follows":"החבילה הראשונה באה אחריו",Reserved:"שמור","Public keys":"מפתחות ציבוריים","51 bytes: ssh-ed25519 public key":"51 בתים: מפתח ציבורי ssh-ed25519","Server’s half":"החצי של השרת","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 בתים (טקסט מוצפן sntrup761 בגודל 1,039 + X25519 32)",Signature:"חתימה","83 bytes: ssh-ed25519 signature over the exchange":"83 בתים: חתימת ssh-ed25519 על ההחלפה","From the next packet on, this side encrypts.":"מהחבילה הבאה והלאה, הצד הזה מצפין.","SSH · encrypted packet":"SSH · חבילה מוצפנת","Encrypted packet":"חבילה מוצפנת","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"עם chacha20-poly1305 אפילו האורך מוצפן; תג של 16 בתים בסוף חושף כל שינוי.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): משתמש ״alice״, שירות ״ssh-connection״, שיטה ״none״","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): שיטות שאפשר להמשיך בהן: ״publickey,password״","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): שיטה ״publickey״, בלי חתימה, המפתח הציבורי ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): אותו מפתח ssh-ed25519","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): שיטה ״publickey-hostbound-v00@openssh.com״, המפתח, מפתח המארח של השרת וחתימה","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): ״session״, ערוץ 0, חלון 2 MB, חבילות עד 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): ערוץ 0 פתוח","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״p״","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״p״, נשלח בחזרה כדי שיוצג","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״w״","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״w״, נשלח בחזרה כדי שיוצג","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״d״","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, ״d״, נשלח בחזרה כדי שיוצג","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 1 בית, תו חזרת גררה (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), ערוץ 0: 94 בתים: שורה חדשה, קודי המסוף של המעטפת, ״/home/alice״, ושורת הפקודה הצבעונית","From browser":"מהדפדפן","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS מניח ערוץ מאובטח מעל TCP. הוא מוכיח את זהות השרת בעזרת תעודה, מסכם על מפתחות חדשים, ואז מצפין ומאמת כל מה שנשלח. HTTPS, דואר מאובטח ופרוטוקולים רבים אחרים רצים בתוכו. SSL היה שמו של קודמו.",Sits:"ממוקם","Between TCP and the app":"בין TCP לאפליקציה","OSI layer":"שכבת OSI","Often placed at 6":"לרוב משויך לשכבה 6",Current:"נוכחי",Retired:"הוצא משימוש","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 ו־3, TLS 1.0 ו־1.1","The app’s own (443, 993 …)":"של האפליקציה עצמה (443, 993 …)","Secure from start to finish":"מאובטח מתחילתו ועד סופו","One round trip to set up":"סבב אחד להקמה","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"סבב אחד הלוך ושוב הספיק כדי להסכים על גרסה, צופן ומפתח היברידי פוסט־קוונטי. שרשרת התעודות הוכיחה מי השרת, וכל בית אחרי ה־Server Hello היה מוצפן ומאומת, עד ה־close_notify. לחצו על ״שוב״ כדי לצפות שוב.","1 round trip":"סבב אחד","Everything the browser supports":"כל מה שהדפדפן תומך בו","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"אחרי לחיצת היד של TCP הדפדפן מפרט מה הוא יודע לעשות: גרסאות TLS, חבילות הצפנה ושיתופי מפתח לקבוצות שהוא מצפה להן, כולל ההיברידית הפוסט־קוונטית X25519MLKEM768. הוא גם מציין את שם האתר (SNI) ואת הפרוטוקולים שהוא מדבר (ALPN).",Versions:"גרסאות","versions, ciphers, key shares":"גרסאות, צפנים, שיתופי מפתח","Choices made, keys computed":"הבחירות נעשו, המפתחות חושבו","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"השרת בוחר TLS 1.3, את חבילת ההצפנה ואת הקבוצה ההיברידית, ושולח את שיתוף המפתח שלו. משני השיתופים שני הצדדים מחשבים את אותו סוד, בלי שהוא יעבור אי־פעם ברשת. כל מה שאחרי ההודעה הזו מוצפן.",Group:"קבוצה","From here on":"מכאן והלאה","its key share":"שיתוף המפתח שלו",Certificate:"תעודה","Who the server is, proven":"מי השרת, מוכח","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"עכשיו בהצפנה, סדרת ההודעות נמשכת: הפרוטוקול שנבחר (http/1.1), שרשרת התעודות, חתימה שנעשתה עם המפתח הפרטי של התעודה, ו־Finished.",Chain:"שרשרת","Site → intermediate → root":"אתר ← ביניים ← שורש","Proves the private key":"מוכיח את המפתח הפרטי",Checked:"נבדק","Name, dates, trusted root":"שם, תאריכים, שורש מהימן","encrypted: http/1.1, certificates,":"מוצפן: http/1.1, תעודות,","signature, Finished":"חתימה, Finished","One round trip, then data":"סבב אחד, ואז נתונים","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"הדפדפן שולח Finished משלו: ערך ביקורת על כל מה ששני הצדדים אמרו, במפתח של הסוד החדש, כך שכל שינוי בהודעות ה־hello היה מתגלה. TLS 1.3 צריך סבב אחד לפני שנתונים זורמים; TLS 1.2 היה צריך שניים.",Covers:"מכסה","The whole handshake":"כל לחיצת היד","For old middleboxes":"עבור התקני ביניים ישנים","check value over":"ערך ביקורת על","the whole handshake":"כל לחיצת היד","Encrypted Data":"נתונים מוצפנים","Records, tags and tickets":"רשומות, תגים וכרטיסים","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP נוסע עכשיו ברשומות מוצפנות, לכל אחת תג של 16 בתים שחושף כל שינוי. השרת גם שולח שני כרטיסי סשן: בפעם הבאה הדפדפן יוכל לחדש את הסשן עם אחד מהם ולדלג על התעודה.","Per record":"לכל רשומה","22 bytes of overhead":"22 בתים של תקורה","2, for resuming later":"2, לחידוש מאוחר יותר",Visible:"מה גלוי","IPs, SNI, sizes, timing":"כתובות IP, SNI, גדלים, תזמון","2 session tickets":"2 כרטיסי סשן","for resuming later":"לחידוש מאוחר יותר",Closing:"סגירה","close_notify, then TCP":"close_notify, ואז TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"אחרי 75 שניות ללא פעילות השרת סוגר את החיבור. קודם הוא שולח התראת close_notify, מוצפנת כמו כל השאר, כדי שהדפדפן יידע שהנתונים הסתיימו בכוונה ולא נקטעו על ידי תוקף. אחר כך TCP נסגר כרגיל.",Alert:"התראה","Shows nothing was cut off":"מראה ששום דבר לא נקטע","TCP FIN from both sides":"TCP FIN משני הצדדים","alert: close_notify":"התראה: close_notify",encrypted:"מוצפן","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ מוצפן)","Encrypted handshake (continued)":"לחיצת יד מוצפנת (המשך)","Encrypted handshake (certificate, verify, Finished)":"לחיצת יד מוצפנת (תעודה, אימות, Finished)","Application Data (inside: close_notify alert)":"Application Data (בפנים: התראת close_notify)","Alert: close_notify (the data ends here, on purpose)":"התראה: close_notify (הנתונים מסתיימים כאן, בכוונה)","No IP address":"אין כתובת IP","192.168.1.1 · DHCP server":"192.168.1.1 · שרת DHCP"},d={"Two-way web messaging":"הודעות ווב בשני הכיוונים","Browser video calls":"שיחות וידאו בדפדפן","HTTP/3 over UDP":"HTTP/3 מעל UDP","Routing between networks":"ניתוב בין רשתות","Address setup, neighbour discovery":"הגדרת כתובות, גילוי שכנים","Private DNS lookups":"חיפושי DNS פרטיים","Signed DNS answers":"תשובות DNS חתומות","Network Time Protocol":"פרוטוקול זמן רשת","Joining a network (WPA2)":"הצטרפות לרשת (WPA2)","Wi-Fi Protected Access 3":"גישה מוגנת ל־Wi-Fi 3","802.1X Enterprise Wi-Fi":"Wi-Fi ארגוני 802.1X","Hotel and café Wi-Fi logins":"כניסה ל־Wi-Fi בבתי מלון ובבתי קפה","Windows file sharing":"שיתוף קבצים ב־Windows","Forward proxy and CONNECT":"פרוקסי קדמי ו־CONNECT","Socket Secure proxy":"פרוקסי Socket Secure","TLS offloading":"פריקת TLS","A modern VPN":"VPN מודרני","IKEv2 and ESP":"IKEv2 ו־ESP","Industrial control (OT)":"בקרה תעשייתית (OT)",Proxy:"פרוקסי","App Server":"שרת אפליקציה","File Server":"שרת קבצים","ISP Router":"נתב ספק האינטרנט","Transit Router":"נתב מעבר","Hosting Router":"נתב האחסון","Their Router":"הנתב של הצד השני","Their Laptop":"המחשב הנייד של הצד השני",Transit:"מעבר",Hosting:"אחסון","The router itself.":"הנתב עצמו.","Mail in Sync":"דואר מסונכרן","Live Updates":"עדכונים חיים","From the browser":"מהדפדפן","From the server":"מהשרת","The WebSocket Protocol":"פרוטוקול WebSocket","A WebSocket keeps one connection open between a web page and a server, so either side can send a message at any moment: chat, live scores, games, shared documents. It starts as an ordinary HTTP request asking to upgrade; after that, messages travel in small frames with a header of just a few bytes.":"WebSocket שומר חיבור אחד פתוח בין דף ווב לשרת, כך שכל צד יכול לשלוח הודעה בכל רגע: צ׳אט, תוצאות חיות, משחקים, מסמכים משותפים. הוא מתחיל כבקשת HTTP רגילה שמבקשת שדרוג; אחר כך ההודעות עוברות במסגרות קטנות עם כותרת של כמה בתים בלבד.","80 (ws://), 443 (wss://)":"80 (ws://), 443 (wss://)","An HTTP request (Upgrade)":"בקשת HTTP (Upgrade)","Frames both ways, any time":"מסגרות בשני הכיוונים, בכל זמן","Frame header":"כותרת מסגרת","2–14 bytes":"2–14 בתים","One request, then messages":"בקשה אחת, ואז הודעות","One HTTP request turned an ordinary TCP connection into a two-way channel. After that every message cost a few bytes of header, and the server could send whenever it had something to say. Press REPLAY to watch it again.":"בקשת HTTP אחת הפכה חיבור TCP רגיל לערוץ דו־כיווני. מאז כל הודעה עלתה כמה בתים של כותרת, והשרת יכול היה לשלוח בכל פעם שהיה לו מה לומר. לחצו על ״שוב״ כדי לצפות שוב.","GET with Upgrade, then 101":"GET עם Upgrade, ואז 101","Smallest frame":"המסגרת הקטנה ביותר","2 bytes (a ping)":"2 בתים (ping)","Server push":"דחיפה מהשרת","Any time, unasked":"בכל זמן, בלי שביקשו","Real sites":"אתרים אמיתיים","wss:// (inside TLS)":"wss:// (בתוך TLS)","TCP to the server, as for HTTP":"TCP אל השרת, כמו ב־HTTP",'The chat page is already open, loaded from www.example.com. Its script calls new WebSocket("ws://www.example.com/chat"), and the browser starts with an ordinary TCP connection to port 80. (Real sites use wss://, the same thing inside TLS; plain ws:// lets you read every byte.)':'דף הצ׳אט כבר פתוח, נטען מ־www.example.com. הסקריפט שלו קורא ל־new WebSocket("ws://www.example.com/chat"), והדפדפן מתחיל בחיבור TCP רגיל לפורט 80. (אתרים אמיתיים משתמשים ב־wss://, אותו דבר בתוך TLS; ws:// פשוט מאפשר לקרוא כל בית.)',"ws://www.example.com/chat":"ws://www.example.com/chat","Ask to Upgrade":"בקשת שדרוג","An HTTP request with Upgrade: websocket":"בקשת HTTP עם Upgrade: websocket","The browser sends an HTTP GET with Upgrade: websocket and Connection: Upgrade. Sec-WebSocket-Key is 16 random bytes written in base64, which the server has to answer correctly. The browser also offers to compress messages (permessage-deflate).":"הדפדפן שולח HTTP GET עם Upgrade: websocket ו־Connection: Upgrade. Sec-WebSocket-Key הוא 16 בתים אקראיים כתובים ב־base64, שהשרת צריך לענות עליהם נכון. הדפדפן גם מציע לדחוס את ההודעות (permessage-deflate).","Asks for":"מבקש","16 random bytes, base64":"16 בתים אקראיים, base64",UPGRADE:"UPGRADE","Switch Protocols":"החלפת פרוטוקול","101: from now on, WebSocket":"101: מעכשיו, WebSocket","The server answers 101 Switching Protocols. Its Sec-WebSocket-Accept is the key with a fixed string added, hashed with SHA-1 and written in base64: proof that it understood the request. It didn’t take up compression, so messages go as plain text. HTTP is finished on this connection; from now on both sides send WebSocket frames.":"השרת עונה 101 Switching Protocols. ה־Sec-WebSocket-Accept שלו הוא המפתח עם מחרוזת קבועה שנוספה לו, מגובב ב־SHA-1 וכתוב ב־base64: הוכחה שהבין את הבקשה. הוא לא קיבל את הדחיסה, ולכן ההודעות עוברות כטקסט גלוי. HTTP הסתיים בחיבור הזה; מעכשיו שני הצדדים שולחים מסגרות WebSocket.",Accept:"Accept","SHA-1 of the key + a fixed string":"SHA-1 של המפתח + מחרוזת קבועה",Compression:"דחיסה","Offered, not taken":"הוצעה, לא התקבלה","NOW A WEBSOCKET":"עכשיו זה WEBSOCKET","Small frames, from either side":"מסגרות קטנות, מכל צד",'You send "Hello": a 2-byte header, a 4-byte masking key and the 5 masked bytes, 11 bytes in all instead of a whole HTTP request. Seconds later the server pushes Bob’s message without being asked: the connection is still open, so it can. Frames from the browser are always masked; frames from the server never are.':'אתם שולחים "Hello": כותרת של 2 בתים, מפתח מיסוך של 4 בתים ו־5 הבתים הממוסכים, 11 בתים בסך הכול במקום בקשת HTTP שלמה. כעבור שניות השרת דוחף את ההודעה של Bob בלי שאיש ביקש: החיבור עדיין פתוח, ולכן הוא יכול. מסגרות מהדפדפן תמיד ממוסכות; מסגרות מהשרת אף פעם לא.',"You send":"אתם שולחים","Server pushes":"השרת דוחף",'"bob: hi there"':'"bob: hi there"',Masked:"מיסוך","From the browser only":"רק מהדפדפן",TEXT:"טקסט",masked:"ממוסך",unasked:"בלי שביקשו","Keeping It Alive":"שמירה על החיבור","Ping and pong":"Ping ו־pong","After half a minute with nothing to say, the server sends a ping, so routers and firewalls on the way don’t forget the quiet connection. The browser answers with a pong on its own; the page’s script never sees either.":"אחרי חצי דקה בלי מה לומר, השרת שולח ping, כדי שהנתבים וחומות האש בדרך לא ישכחו את החיבור השקט. הדפדפן עונה מעצמו ב־pong; הסקריפט של הדף לא רואה אף אחד מהם.","Opcode 9, from either side":"Opcode 9, מכל צד",Pong:"Pong","Opcode 10, by itself":"Opcode 10, מעצמו","How often":"באיזו תדירות","Up to the server (30 s)":"לפי השרת (30 שנ׳)","A close frame each way":"מסגרת סגירה בכל כיוון","When you leave the chat, the page’s script closes the WebSocket with status 1000 (normal closure): the browser sends a close frame and the server answers with its own. Then the server closes the TCP connection. (Simply closing the tab would send 1001, going away.)":"כשאתם עוזבים את הצ׳אט, הסקריפט של הדף סוגר את ה־WebSocket עם סטטוס 1000 (סגירה רגילה): הדפדפן שולח מסגרת סגירה והשרת עונה במסגרת משלו. אחר כך השרת סוגר את חיבור ה־TCP. (סגירה פשוטה של הלשונית הייתה שולחת 1001, going away.)",Opcode:"Opcode","8 (close)":"8 (סגירה)","1000 (normal closure)":"1000 (סגירה רגילה)","TCP closes":"TCP נסגר",CLOSE:"סגירה","1000 normal closure":"1000 סגירה רגילה","FIN 1: this frame is a whole message. The opcode says what it carries.":"FIN 1: המסגרת הזאת היא הודעה שלמה. ה־opcode אומר מה היא נושאת.","Mask, length":"מיסוך, אורך","Everything a browser sends is masked.":"כל מה שדפדפן שולח ממוסך.","Masking key":"מפתח מיסוך","Chosen at random for every frame.":"נבחר באקראי לכל מסגרת.",Payload:"מטען","Each byte XORed with the masking key in turn; the server XORs it back.":"כל בית בתורו עובר XOR עם מפתח המיסוך; השרת מבטל את ה־XOR.","A server never masks what it sends.":"שרת אף פעם לא ממסך את מה שהוא שולח.","Status code":"קוד סטטוס","Joining a Network":"הצטרפות לרשת","From the access point":"מנקודת הגישה","4-way handshake":"לחיצת יד בארבעה שלבים","Access Point":"נקודת גישה","Wi-Fi (802.11) with WPA2":"Wi-Fi (802.11) עם WPA2","Wi-Fi carries a network over radio. Before a device can send anything, it has to find the network, join it and prove it knows the password. With WPA2-Personal that proof is the 4-way handshake: four short messages that turn the password into fresh encryption keys, without the password ever going over the air.":"Wi-Fi מעביר רשת ברדיו. לפני שמכשיר יכול לשלוח משהו, עליו למצוא את הרשת, להצטרף אליה ולהוכיח שהוא יודע את הסיסמה. ב־WPA2-Personal ההוכחה הזאת היא לחיצת היד בארבעה שלבים: ארבע הודעות קצרות שהופכות את הסיסמה למפתחות הצפנה חדשים, בלי שהסיסמה תעבור אי פעם באוויר.","Data Link (Layer 2)":"קו נתונים (שכבה 2)",Standard:"תקן",Joining:"הצטרפות","Probe, authenticate, associate":"גישוש, אימות, שיוך","Keys from":"מפתחות מ־","The 4-way handshake":"לחיצת היד בארבעה שלבים",Connected:"מחובר","Eleven frames to a secure link":"אחת־עשרה מסגרות עד קישור מאובטח","The laptop found the network, joined it with two formalities and proved it knew the password in a four-message handshake, without ever sending it. Everything after that was encrypted with keys made for this connection alone. Press REPLAY to watch it again.":"המחשב הנייד מצא את הרשת, הצטרף אליה בשני טקסים והוכיח שהוא יודע את הסיסמה בלחיצת יד של ארבע הודעות, בלי לשלוח אותה אף פעם. כל מה שבא אחר כך הוצפן במפתחות שנוצרו לחיבור הזה בלבד. לחצו על ״שוב״ כדי לצפות שוב.","Frames to join":"מסגרות להצטרפות","Password sent":"סיסמה שנשלחה",Never:"אף פעם","Session keys":"מפתחות הפעלה","New every time":"חדשים בכל פעם",Next:"הבא","DHCP, for an IP address":"DHCP, לכתובת IP","Find the Network":"מציאת הרשת","A beacon, then a probe":"משואה, ואז גישוש",'About ten times a second the router’s Wi-Fi sends a beacon: here is "HomeNet", protected with WPA2, on channel 36. The laptop could simply wait to hear one; to be quicker it also asks out loud with a probe request, and the access point answers with a probe response.':'בערך עשר פעמים בשנייה ה־Wi-Fi של הנתב שולח משואה (beacon): הנה "HomeNet", מוגנת ב־WPA2, בערוץ 36. המחשב הנייד יכול היה פשוט לחכות לשמוע אחת; כדי להיות מהיר יותר הוא גם שואל בקול בבקשת גישוש, ונקודת הגישה עונה בתשובת גישוש.',"WPA2-Personal (password)":"WPA2-Personal (סיסמה)",BEACON:"משואה","WPA2 · channel 36":"WPA2 · ערוץ 36",PROBE:"גישוש","any networks here?":"יש פה רשתות?","PROBE RESPONSE":"תשובת גישוש","Join the Network":"הצטרפות לרשת","Two formalities: hello, then join":"שני טקסים: שלום, ואז הצטרפות","Open System authentication lets anyone this far: no password yet. Then the laptop asks to associate, repeating the security it chose (CCMP, with a password), and the access point gives it association ID 1. The laptop is connected, but the only thing it may send is the handshake that comes next.":"אימות Open System נותן לכל אחד להגיע עד כאן: עדיין בלי סיסמה. אחר כך המחשב הנייד מבקש להשתייך, וחוזר על האבטחה שבחר (CCMP, עם סיסמה), ונקודת הגישה נותנת לו מזהה שיוך 1. המחשב מחובר, אבל הדבר היחיד שהוא רשאי לשלוח הוא לחיצת היד שבאה עכשיו.",Authentication:"אימות","Open System (no password)":"Open System (בלי סיסמה)","Association ID":"מזהה שיוך","Allowed so far":"מותר בינתיים",success:"הצלחה",ASSOCIATE:"שיוך",'join "HomeNet"':'הצטרפות ל־"HomeNet"',"CCMP, password":"CCMP, סיסמה",ASSOCIATED:"משויך","association ID 1":"מזהה שיוך 1","Messages 1 and 2":"הודעות 1 ו־2","The 4-way handshake: nonces":"לחיצת היד בארבעה שלבים: מספרים חד־פעמיים","Both sides already hold the same key, worked out from the password and the network’s name (the PMK); it never goes over the air. The access point sends a random number, the ANonce. The laptop sends its own, the SNonce, with a check value (MIC). From the PMK, the two nonces and both MAC addresses, each side now works out the same session keys.":"לשני הצדדים כבר יש אותו מפתח, שחושב מהסיסמה ומשם הרשת (ה־PMK); הוא אף פעם לא עובר באוויר. נקודת הגישה שולחת מספר אקראי, ה־ANonce. המחשב הנייד שולח את שלו, ה־SNonce, עם ערך בדיקה (MIC). מה־PMK, משני המספרים ומשתי כתובות ה־MAC כל צד מחשב עכשיו את אותם מפתחות הפעלה.","Shared key":"מפתח משותף","PMK, from the password":"PMK, מהסיסמה",Exchanged:"הוחלפו","Two random nonces":"שני מספרים חד־פעמיים אקראיים","Worked out":"חושבו","Session keys (PTK)":"מפתחות הפעלה (PTK)","MESSAGE 1":"הודעה 1","MESSAGE 2":"הודעה 2","Messages 3 and 4":"הודעות 3 ו־4","The 4-way handshake: keys":"לחיצת היד בארבעה שלבים: מפתחות","Message 3 shows the access point has the same keys (its MIC checks out) and brings the group key (GTK) for broadcasts, encrypted. Message 4 says the laptop is ready, and both ends start encrypting.":"הודעה 3 מראה שלנקודת הגישה יש אותם מפתחות (ה־MIC שלה תקין) ומביאה את מפתח הקבוצה (GTK) לשידורים, מוצפן. הודעה 4 אומרת שהמחשב הנייד מוכן, ושני הקצוות מתחילים להצפין.","Group key":"מפתח קבוצה","GTK, sent encrypted":"GTK, נשלח מוצפן",Install:"התקנה","Both ends at once":"שני הקצוות בבת אחת","MESSAGE 3":"הודעה 3","group key, encrypted":"מפתח קבוצה, מוצפן","MESSAGE 4":"הודעה 4","keys installed":"המפתחות הותקנו","Encrypted Now":"מוצפן עכשיו","And what a listener could still do":"ומה שמי שמאזין עדיין יכול לעשות","Every data frame is encrypted now, like this first one carrying a DHCP Discover: anyone nearby sees only the MAC addresses and the size. But someone who recorded the four handshake messages can try password guesses at home, as fast as their computer allows: a guess is right when it gives the same MIC. A long, random password makes that hopeless; WPA3 removes the weakness.":"כל מסגרת נתונים מוצפנת עכשיו, כמו הראשונה הזאת שנושאת DHCP Discover: מי שנמצא בקרבת מקום רואה רק את כתובות ה־MAC ואת הגודל. אבל מי שהקליט את ארבע הודעות לחיצת היד יכול לנסות סיסמאות בבית, מהר ככל שהמחשב שלו מאפשר: ניחוש נכון כשהוא נותן את אותו MIC. סיסמה ארוכה ואקראית הופכת את זה לחסר סיכוי; WPA3 מסיר את החולשה.","Others see":"מה אחרים רואים","MAC addresses, sizes, timing":"כתובות MAC, גדלים, תזמון","Weak point":"נקודת תורפה","Offline password guessing":"ניחוש סיסמה במצב לא מקוון",Defence:"הגנה","A long password, or WPA3":"סיסמה ארוכה, או WPA3","DHCP Discover inside":"בפנים DHCP Discover","ENCRYPTED FROM HERE ON":"מוצפן מכאן והלאה","QoS Data (encrypted)":"QoS Data (מוצפן)","Seen over the air, on Wi-Fi channel 36":"נראה באוויר, בערוץ Wi-Fi 36","Frame type":"סוג מסגרת","Management, Beacon":"ניהול, Beacon",Duration:"משך","Nobody acknowledges a broadcast, so nothing is booked.":"אף אחד לא מאשר שידור, ולכן שום דבר לא נשמר.",Receiver:"נמען","Broadcast: every device in range listens.":"שידור: כל מכשיר בטווח מאזין.",Transmitter:"משדר","The access point.":"נקודת הגישה.","The access point’s own address: which network this is about.":"הכתובת של נקודת הגישה עצמה: על איזו רשת מדובר.","Lets the receiver spot a repeat when a frame is sent again.":"מאפשר לנמען לזהות חזרה כשמסגרת נשלחת שוב.","The access point’s clock; devices on the network keep theirs in step with it.":"השעון של נקודת הגישה; המכשירים ברשת מכוונים את שלהם לפיו.","Beacon interval":"מרווח משואות","A beacon goes out about ten times a second.":"משואה יוצאת בערך עשר פעמים בשנייה.","0x0011: access point network, encrypted":"0x0011: רשת עם נקודת גישה, מוצפנת","Privacy bit set: joining takes a key.":"סיבית הפרטיות דולקת: הצטרפות דורשת מפתח.","The network’s name.":"שם הרשת.","Supported rates":"קצבים נתמכים","Only the oldest, slowest rates; the fast ones are in the elements that follow.":"רק הקצבים הישנים והאיטיים ביותר; המהירים נמצאים ברכיבים הבאים.","DTIM count 0, period 1":"מונה DTIM 0, מחזור 1","Tells sleeping devices whether frames are waiting for them.":"אומר למכשירים ישנים אם מחכות להם מסגרות.","Robust Security Network: how this network is protected.":"Robust Security Network: איך הרשת הזאת מוגנת.","Element ID, length":"מזהה רכיב, אורך","48, 20 bytes":"48, 20 בתים","Group cipher":"צופן קבוצתי","Encrypts broadcasts, which every device on the network can read.":"מצפין שידורים, שכל מכשיר ברשת יכול לקרוא.","Pairwise cipher":"צופן זוגי","Encrypts each device’s own traffic, with keys only it and the access point have.":"מצפין את התעבורה של כל מכשיר במפתחות שרק לו ולנקודת הגישה יש.","Key management":"ניהול מפתחות","1: PSK (a shared password)":"1: PSK (סיסמה משותפת)","More elements":"רכיבים נוספים","Wi-Fi 4, 5 and 6 capabilities and settings (HT, VHT, HE: channel 36, 80 MHz wide), and vendor extras.":"יכולות והגדרות של Wi-Fi 4, 5 ו־6 (HT, VHT, HE: ערוץ 36, רוחב 80 MHz) ותוספות של היצרן.","Management, Probe Request":"ניהול, Probe Request","The laptop’s Wi-Fi card.":"כרטיס ה־Wi-Fi של המחשב הנייד.","empty (any network)":"ריק (כל רשת)","Any access point may answer. (Devices used to ask for every network they had joined by name, telling anyone listening where they had been.)":"כל נקודת גישה רשאית לענות. (פעם מכשירים שאלו בשמה על כל רשת שהצטרפו אליה אי פעם, וכך סיפרו לכל מי שהאזין איפה היו.)","What the laptop’s radio can do: Wi-Fi 4, 5 and 6 capabilities, and vendor extras.":"מה הרדיו של המחשב הנייד יודע לעשות: יכולות Wi-Fi 4, 5 ו־6 ותוספות של היצרן.","Management, Probe Response":"ניהול, Probe Response","How long the channel stays booked for this exchange; other devices wait.":"כמה זמן הערוץ נשאר שמור לחילופים האלה; מכשירים אחרים מחכים.","The radio this frame is for.":"הרדיו שהמסגרת הזאת מיועדת לו.","Authentication · Open System":"אימות · Open System","Management, Authentication":"ניהול, Authentication",Algorithm:"אלגוריתם","Open: anyone may get this far. The password is checked later, in the 4-way handshake.":"פתוח: כל אחד יכול להגיע עד כאן. הסיסמה נבדקת אחר כך, בלחיצת היד בארבעה שלבים.",Transaction:"טרנזקציה","0 (success)":"0 (הצלחה)","Management, Association Request":"ניהול, Association Request","Listen interval":"מרווח האזנה","10 beacons":"10 משואות","How often the laptop wakes to check for waiting frames when saving power.":"באיזו תדירות המחשב הנייד מתעורר במצב חיסכון בחשמל כדי לבדוק מסגרות שמחכות לו.","What the laptop’s radio can do (Wi-Fi 4, 5 and 6), and vendor extras.":"מה הרדיו של המחשב הנייד יודע לעשות (Wi-Fi 4, 5 ו־6) ותוספות של היצרן.","Management, Association Response":"ניהול, Association Response","The laptop’s number at this access point (the top two bits are always set).":"המספר של המחשב הנייד בנקודת הגישה הזאת (שתי הסיביות העליונות תמיד דולקות).","The settings the access point uses (Wi-Fi 4, 5 and 6), and vendor extras.":"ההגדרות שנקודת הגישה משתמשת בהן (Wi-Fi 4, 5 ו־6) ותוספות של היצרן.","Data, QoS Data":"נתונים, QoS Data","0x02 (from the access point)":"0x02 (מנקודת הגישה)","Sent by the access point itself.":"נשלח על ידי נקודת הגישה עצמה.","QoS control":"בקרת QoS","Priority 7, the highest: the handshake goes first.":"עדיפות 7, הגבוהה ביותר: לחיצת היד קודמת לכול.",Organization:"ארגון","0x888e (802.1X authentication)":"0x888e (אימות 802.1X)","What follows: plays the part an Ethernet type field does on a cable.":"מה שבא אחר כך: ממלא את התפקיד ששדה הסוג של Ethernet ממלא בכבל.","Descriptor type":"סוג מתאר","Key information":"מידע על המפתח","0x008a: pairwise, ACK":"0x008a: זוגי, ACK","ACK: the laptop must answer.":"ACK: המחשב הנייד חייב לענות.","Key length":"אורך המפתח","The pairwise key is 16 bytes (AES-128).":"המפתח הזוגי באורך 16 בתים (AES-128).","Replay counter":"מונה שידור חוזר","Counts up with each message from the access point; an old one sent again is ignored.":"עולה עם כל הודעה מנקודת הגישה; הודעה ישנה שנשלחת שוב נדחית.","A random number from the access point.":"מספר אקראי מנקודת הגישה.","Key IV":"IV של המפתח",zeros:"אפסים","Key RSC":"RSC של המפתח","No keys yet, so nothing to check with.":"עדיין אין מפתחות, ולכן אין במה לבדוק.","Key data length":"אורך נתוני המפתח","0x01 (to the access point)":"0x01 (אל נקודת הגישה)","The access point itself.":"נקודת הגישה עצמה.","0x010a: pairwise, MIC":"0x010a: זוגי, MIC","MIC: this message carries a check value.":"MIC: ההודעה הזאת נושאת ערך בדיקה.","A random number from the laptop. From both numbers, both MAC addresses and the key that comes from the password, each side works out the same session keys.":"מספר אקראי מהמחשב הנייד. משני המספרים, משתי כתובות ה־MAC ומהמפתח שנגזר מהסיסמה כל צד מחשב את אותם מפתחות הפעלה.","Worked out with the new keys: it proves the sender knows the password, and that the message wasn’t changed.":"חושב במפתחות החדשים: מוכיח שהשולח יודע את הסיסמה ושההודעה לא שונתה.","0x13ca: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13ca: זוגי, התקנה, ACK, MIC, מאובטח, נתוני מפתח מוצפנים","Install: start using the keys. The group key comes encrypted.":"התקנה: להתחיל להשתמש במפתחות. מפתח הקבוצה מגיע מוצפן.","Where the group key’s packet numbers start.":"מאיפה מתחילים מספרי החבילות של מפתח הקבוצה.","Key data":"נתוני מפתח","Encrypted with a key from the handshake.":"מוצפן במפתח מלחיצת היד.","The access point’s RSN element":"רכיב ה־RSN של נקודת הגישה","GTK: the group key, for broadcasts":"GTK: מפתח הקבוצה, לשידורים","0x030a: pairwise, MIC, secure":"0x030a: זוגי, MIC, מאובטח","Secure: the keys are in place.":"מאובטח: המפתחות במקומם.","CCMP · encrypted":"CCMP · מוצפן","0x41 (protected, to the access point)":"0x41 (מוגן, אל נקודת הגישה)","Protected: what follows the header is encrypted.":"מוגן: מה שבא אחרי הכותרת מוצפן.","Where the access point should pass it on to: everyone on the network.":"למי נקודת הגישה צריכה להעביר אותה: לכל מי שברשת.","CCMP header":"כותרת CCMP","packet number 1, key 0":"מספר חבילה 1, מפתח 0","Counts up with every frame; one seen before is thrown away.":"עולה עם כל מסגרת; מסגרת שכבר נראתה נזרקת.","LLC/SNAP: an IPv4 packet":"LLC/SNAP: חבילת IPv4","Shows any change to the frame.":"חושף כל שינוי במסגרת.","Safer Wi-Fi":"Wi-Fi בטוח יותר","WPA3 is the current Wi-Fi security standard. Its Personal mode keeps the simple shared password but changes how it is checked: SAE, a password exchange that no recording can attack offline, gives every connection a fresh key. It also makes protected management frames compulsory.":"WPA3 הוא תקן האבטחה הנוכחי של Wi-Fi. מצב ה־Personal שלו שומר על הסיסמה המשותפת הפשוטה אבל משנה את אופן הבדיקה שלה: SAE, חילוף סיסמה שאף הקלטה לא מאפשרת לתקוף במצב לא מקוון, נותן לכל חיבור מפתח חדש. הוא גם הופך מסגרות ניהול מוגנות לחובה.","Password check":"בדיקת סיסמה",Required:"חובה","Protected management frames":"מסגרות ניהול מוגנות",Since:"מאז","Connected with WPA3":"מחובר עם WPA3","Same password, better protocol":"אותה סיסמה, פרוטוקול טוב יותר","The laptop and the access point proved to each other that they know the password without giving anyone a way to test guesses offline, then made fresh keys exactly as WPA2 does. Press REPLAY to watch it again.":"המחשב הנייד ונקודת הגישה הוכיחו זה לזה שהם יודעים את הסיסמה בלי לתת לאיש דרך לבדוק ניחושים במצב לא מקוון, ואז יצרו מפתחות חדשים בדיוק כמו ב־WPA2. לחצו על ״שוב״ כדי לצפות שוב.","SAE frames":"מסגרות SAE","4 (commit, confirm)":"4 (commit, confirm)","4 EAPOL-Key frames":"4 מסגרות EAPOL-Key","Offline guessing":"ניחוש לא מקוון","Not possible":"לא אפשרי","Forged disconnects":"ניתוקים מזויפים",Ignored:"נדחים","A WPA3 Network":"רשת WPA3","The beacon asks for SAE":"המשואה מבקשת SAE","The beacon looks like WPA2’s with two changes in its RSN element: the key management is SAE instead of PSK, and protected management frames are required. Everyone still uses one shared password.":"המשואה נראית כמו של WPA2 עם שני שינויים ברכיב ה־RSN: ניהול המפתחות הוא SAE במקום PSK, ומסגרות ניהול מוגנות הן חובה. כולם עדיין משתמשים בסיסמה משותפת אחת.","Management frames":"מסגרות ניהול","Protected (required)":"מוגנות (חובה)","Still one for everyone":"עדיין אחת לכולם","SAE Commit":"SAE Commit","Each side commits to the password":"כל צד מתחייב לסיסמה","Instead of Open System authentication, the two sides run SAE, a password exchange between equals. Each picks a random secret and sends a scalar and an element worked out from that secret and the password. The password is the same on both sides, the secrets are not, so every connection ends up with a new key.":"במקום אימות Open System, שני הצדדים מריצים SAE, חילוף סיסמה בין שווים. כל אחד בוחר סוד אקראי ושולח סקלר ורכיב שחושבו מהסוד הזה ומהסיסמה. הסיסמה זהה בשני הצדדים, הסודות לא, ולכן כל חיבור מקבל מפתח חדש.","19 (256-bit curve)":"19 (עקומה של 256 סיביות)","Each sends":"כל צד שולח","A scalar and an element":"סקלר ורכיב",Replaces:"מחליף את","Open System authentication":"אימות Open System",COMMIT:"COMMIT","scalar + element":"סקלר + רכיב","SAE Confirm":"SAE Confirm","Proof, without the password":"הוכחה, בלי הסיסמה","Each side now works out the shared key and sends a confirm, a value only someone with the right password could produce. Recording all four SAE frames doesn’t let an attacker test guesses at home: every guess takes a live exchange with the access point, which can slow them down or shut them out.":"עכשיו כל צד מחשב את המפתח המשותף ושולח confirm, ערך שרק מי שיש לו את הסיסמה הנכונה יכול להפיק. הקלטת ארבע מסגרות ה־SAE לא מאפשרת לתוקף לבדוק ניחושים בבית: כל ניחוש דורש חילוף חי עם נקודת הגישה, שיכולה להאט אותו או לחסום אותו.","A new key (PMK) each time":"מפתח חדש (PMK) בכל פעם",Guessing:"ניחוש","Live only, never offline":"רק בזמן אמת, אף פעם לא במצב לא מקוון","Password leaks":"דליפת סיסמה","Past traffic stays safe":"התעבורה הקודמת נשארת מוגנת",CONFIRM:"CONFIRM","proof of the key":"הוכחת המפתח","Join, Handshake":"הצטרפות, לחיצת יד","Then the 4-way handshake, as in WPA2":"אחר כך לחיצת היד בארבעה שלבים, כמו ב־WPA2","Association works as before, repeating the choice of SAE. The 4-way handshake that follows is WPA2’s, starting from the key SAE just made, except that message 3 also brings the IGTK, a key that signs broadcast management frames.":"השיוך עובד כמו קודם, וחוזר על הבחירה ב־SAE. לחיצת היד בארבעה שלבים שבאה אחר כך היא של WPA2, ומתחילה מהמפתח ש־SAE יצר זה עתה, אלא שהודעה 3 מביאה גם את ה־IGTK, מפתח שחותם על מסגרות ניהול משודרות.","Message 3 adds":"הודעה 3 מוסיפה","Why It’s Safer":"למה זה בטוח יותר","Forged disconnects stop working":"ניתוקים מזויפים מפסיקים לעבוד","With WPA2, anyone in range could forge a “disconnect” frame and knock a device off the network, often to record its handshake when it joined again. WPA3 requires protected management frames, so forged disconnects are ignored. Many routers also offer a transition mode that lets WPA2 devices join too; those devices keep WPA2’s weaknesses.":"ב־WPA2 כל מי שבטווח יכול היה לזייף מסגרת ״ניתוק״ ולהעיף מכשיר מהרשת, לעיתים קרובות כדי להקליט את לחיצת היד שלו כשהוא מצטרף שוב. WPA3 מחייב מסגרות ניהול מוגנות, ולכן ניתוקים מזויפים נדחים. נתבים רבים מציעים גם מצב מעבר שמאפשר גם למכשירי WPA2 להצטרף; המכשירים האלה שומרים על החולשות של WPA2.",Protected:"מוגנות","Disconnects, other management":"ניתוקים, ניהול אחר","WPA2/3 mode":"מצב WPA2/3","WPA2 devices stay at risk":"מכשירי WPA2 נשארים בסיכון","Stronger still":"חזק עוד יותר","WPA3-Enterprise (192-bit)":"WPA3-Enterprise (192 סיביות)","MANAGEMENT FRAMES PROTECTED":"מסגרות הניהול מוגנות","0x00c0: management frame protection required":"0x00c0: הגנת מסגרות ניהול היא חובה","Disconnect messages and other management frames are signed, so they can’t be forged.":"הודעות ניתוק ומסגרות ניהול אחרות חתומות, ולכן אי אפשר לזייף אותן.","Authentication · SAE Commit":"אימות · SAE Commit","Simultaneous Authentication of Equals: WPA3’s password exchange.":"Simultaneous Authentication of Equals: חילוף הסיסמה של WPA3.","19 (256-bit elliptic curve)":"19 (עקומה אליפטית של 256 סיביות)",Scalar:"סקלר","Worked out from a random secret and the password.":"מחושב מסוד אקראי ומהסיסמה.",Element:"רכיב","A point on the curve, also tied to the password. Recording the scalar and element doesn’t let anyone test password guesses afterwards.":"נקודה על העקומה, שגם היא קשורה לסיסמה. הקלטת הסקלר והרכיב לא מאפשרת לאיש לבדוק ניחושי סיסמה אחר כך.","Authentication · SAE Confirm":"אימות · SAE Confirm","Proves this side worked out the same key, without giving it away.":"מוכיח שהצד הזה חישב את אותו מפתח, בלי לחשוף אותו.","0x0088: pairwise, ACK":"0x0088: זוגי, ACK","0x0108: pairwise, MIC":"0x0108: זוגי, MIC","0x13c8: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13c8: זוגי, התקנה, ACK, MIC, מאובטח, נתוני מפתח מוצפנים","IGTK: the key that signs broadcast management frames":"IGTK: המפתח שחותם על מסגרות ניהול משודרות","0x0308: pairwise, MIC, secure":"0x0308: זוגי, MIC, מאובטח","Sign-In":"כניסה","From the router":"מהנתב","From the test server":"משרת הבדיקה","Hotel Router":"נתב המלון","192.168.1.1 · captive portal":"192.168.1.1 · פורטל שבוי","Wi-Fi login pages":"דפי כניסה ל־Wi-Fi","Hotels, cafés, airports and trains often put a login page in front of their Wi-Fi. Until you accept the terms (or pay), the router lets nothing out to the internet. It catches your device’s first plain HTTP request and answers it with a redirect to its own page; your device notices because a test page it knows comes back wrong.":"בתי מלון, בתי קפה, נמלי תעופה ורכבות שמים לעיתים קרובות דף כניסה לפני ה־Wi-Fi שלהם. עד שתקבלו את התנאים (או תשלמו), הנתב לא מוציא שום דבר לאינטרנט. הוא תופס את בקשת ה־HTTP הלא מוצפנת הראשונה של המכשיר ועונה עליה בהפניה לדף שלו; המכשיר שם לב כי דף בדיקה שהוא מכיר חוזר עם תשובה שגויה.",Where:"איפה","Hotels, cafés, airports":"בתי מלון, בתי קפה, נמלי תעופה",How:"איך","Catches plain HTTP requests":"תופס בקשות HTTP לא מוצפנות","Noticed by":"מי מגלה","Your system’s test page":"דף הבדיקה של המערכת שלכם","Logging in":"בכניסה","Lets your MAC address through":"מעביר את כתובת ה־MAC שלכם","Newer way":"דרך חדשה יותר","DHCP option 114 (RFC 8910)":"אפשרות DHCP 114 (RFC 8910)","Described In":"מתואר ב־",Online:"מקוון","Noticed, logged in, let through":"זוהה, נכנס, הועבר","Windows asked a test page for an answer it knows and got a redirect instead, so it knew a portal was in the way and opened the login page. Once the terms were accepted, the router let the laptop through, and the same check came back right. Press REPLAY to watch it again.":"Windows ביקשה מדף בדיקה תשובה שהיא מכירה וקיבלה הפניה במקומה, ולכן הבינה שפורטל עומד בדרך ופתחה את דף הכניסה. אחרי שהתנאים התקבלו, הנתב העביר את המחשב הנייד, ואותה בדיקה חזרה תקינה. לחצו על ״שוב״ כדי לצפות שוב.","A plain HTTP test page":"דף בדיקה ב־HTTP לא מוצפן","Faked by":"זויף על ידי","The router (TTL 64)":"הנתב (TTL 64)","Let through":"הועבר","The laptop’s MAC address":"כתובת ה־MAC של המחשב הנייד","Open Wi-Fi":"Wi-Fi פתוח","Use HTTPS, or a VPN":"השתמשו ב־HTTPS או ב־VPN","Joined, Offline":"מחובר, בלי יציאה","An address, but no way out":"יש כתובת, אין יציאה","The laptop has joined the hotel’s Wi-Fi, which has no password, and got an address from the router by DHCP. The router answers the laptop itself and passes on its DNS lookups, but drops anything else bound for the internet until the guest has logged in. (An open network also means anyone nearby can read whatever isn’t protected by HTTPS.)":"המחשב הנייד הצטרף ל־Wi-Fi של המלון, שאין לו סיסמה, וקיבל כתובת מהנתב ב־DHCP. הנתב עונה למחשב בעצמו ומעביר הלאה את חיפושי ה־DNS שלו, אבל זורק כל דבר אחר שמיועד לאינטרנט עד שהאורח נכנס. (רשת פתוחה פירושה גם שכל מי שנמצא בקרבת מקום יכול לקרוא כל מה שלא מוגן ב־HTTPS.)","192.168.1.10 (by DHCP)":"192.168.1.10 (ב־DHCP)","Wi-Fi password":"סיסמת Wi-Fi","None (open network)":"אין (רשת פתוחה)","Blocked until you log in":"חסום עד הכניסה","CONNECTED, NO INTERNET YET":"מחובר, עדיין בלי אינטרנט","Internet Check":"בדיקת אינטרנט","Windows checks a test page":"Windows בודקת דף בדיקה",'After joining any network, Windows looks up www.msftconnecttest.com (the router passes the lookup on) and asks it for /connecttest.txt over plain HTTP; the right answer is the text "Microsoft Connect Test". The router catches the connection and answers the handshake itself, in the test server’s name. The laptop can’t tell yet.':'אחרי הצטרפות לכל רשת, Windows מחפשת את www.msftconnecttest.com (הנתב מעביר את החיפוש) ומבקשת ממנו את /connecttest.txt ב־HTTP לא מוצפן; התשובה הנכונה היא הטקסט "Microsoft Connect Test". הנתב תופס את החיבור ועונה על לחיצת היד בעצמו, בשם שרת הבדיקה. המחשב הנייד עדיין לא יכול לדעת.',"Test page":"דף בדיקה","msftconnecttest.com/connecttest.txt":"msftconnecttest.com/connecttest.txt",Expected:"צפוי","Answered by":"עונה","The router, posing as the server":"הנתב, שמתחזה לשרת",'from "203.0.113.30"':'מ־"203.0.113.30"',"/connecttest.txt":"/connecttest.txt",Redirected:"הופנה","The wrong answer gives it away":"התשובה השגויה מסגירה אותו",'Instead of the test text, the "server" answers 302 Found, pointing to the router’s login page. Its TTL is 64, not lowered at all, because it came straight from the router. Windows sees the wrong answer, marks the network as needing action and opens the browser, whose first request the router redirects the same way, to its login page. This only works with plain HTTP: the router can’t fake an HTTPS page without a certificate error.':'במקום טקסט הבדיקה, ה"שרת" עונה 302 Found ומפנה לדף הכניסה של הנתב. ה־TTL שלו 64, בלי שום הפחתה, כי הוא הגיע ישר מהנתב. Windows רואה את התשובה השגויה, מסמנת את הרשת כדורשת פעולה ופותחת את הדפדפן, שאת בקשתו הראשונה הנתב מפנה באותה דרך לדף הכניסה שלו. זה עובד רק עם HTTP לא מוצפן: הנתב לא יכול לזייף דף HTTPS בלי שגיאת אישור.',"302 → 192.168.1.1/login":"302 → 192.168.1.1/login","Give-away":"מה מסגיר","TTL 64, from one hop away":"TTL 64, מקפיצה אחת","Why HTTP":"למה HTTP","HTTPS can’t be faked":"אי אפשר לזייף HTTPS","302 FOUND":"302 FOUND","ACTION NEEDED":"נדרשת פעולה","The Login Page":"דף הכניסה","Served by the router itself":"הנתב עצמו מגיש אותו","The browser opens http://192.168.1.1/login, a page the router serves itself: the hotel’s name, the terms of use and an Accept button. This connection really does go to the router.":"הדפדפן פותח את http://192.168.1.1/login, דף שהנתב עצמו מגיש: שם המלון, תנאי השימוש וכפתור אישור. החיבור הזה באמת הולך לנתב.",Page:"דף","http://192.168.1.1/login":"http://192.168.1.1/login","Served by":"מוגש על ידי","The router":"הנתב",Size:"גודל","2,400 bytes of HTML":"2,400 בתים של HTML","/login":"/login","the login page":"דף הכניסה","Accept the Terms":"קבלת התנאים","The router lets the laptop out":"הנתב מוציא את המחשב הנייד","Clicking Accept posts a small form back to the router. It adds the laptop’s MAC address to the list of devices allowed out, often for the length of the stay, and redirects the browser on its way.":"לחיצה על אישור שולחת טופס קטן לנתב. הוא מוסיף את כתובת ה־MAC של המחשב הנייד לרשימת המכשירים שמותר להם לצאת, לרוב לכל משך השהות, ומפנה את הדפדפן ליעדו.",Form:"טופס","terms=accepted":"terms=accepted","Router allows":"הנתב מתיר","302 to where you were going":"302 לאן שהלכתם","you’re online":"אתם מקוונים","MAC ADDRESS ALLOWED":"כתובת MAC הותרה","The same check, now real":"אותה בדיקה, הפעם אמיתית","Windows checks again. This time the router lets the connection through to the real test server, twelve routers away (its replies arrive with TTL 52), and the answer is the expected text. The network is marked as connected to the internet.":"Windows בודקת שוב. הפעם הנתב מעביר את החיבור לשרת הבדיקה האמיתי, במרחק שנים־עשר נתבים (התשובות שלו מגיעות עם TTL 52), והתשובה היא הטקסט הצפוי. הרשת מסומנת כמחוברת לאינטרנט.","Connected to the internet":"מחובר לאינטרנט",ONLINE:"מקוון","www.msftconnecttest.com, type A, class IN":"www.msftconnecttest.com, סוג A, מחלקה IN","www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)":"www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)","Sent with 64 and not lowered at all: it came from the router next door, not from a server 12 routers away.":"נשלח עם 64 בלי שום הפחתה: הוא הגיע מהנתב הסמוך, לא משרת במרחק 12 נתבים.","2,400 bytes: the login page":"2,400 בתים: דף הכניסה","Via a Proxy":"דרך פרוקסי","TLS, through the tunnel":"TLS, דרך המנהרה","Forward proxy, and CONNECT for HTTPS":"פרוקסי קדמי, ו־CONNECT ל־HTTPS","A forward proxy fetches web pages on your behalf. Companies and schools use one to filter sites, keep copies of popular pages and log what goes out; the sites you visit see the proxy, not you. Plain HTTP passes through it in the clear. For HTTPS the browser asks the proxy for a tunnel, and the encrypted connection runs through it unread.":"פרוקסי קדמי מביא דפי ווב בשמכם. חברות ובתי ספר משתמשים בו כדי לסנן אתרים, לשמור עותקים של דפים פופולריים ולתעד את מה שיוצא; האתרים שאתם מבקרים בהם רואים את הפרוקסי, לא אתכם. HTTP לא מוצפן עובר דרכו גלוי. ב־HTTPS הדפדפן מבקש מהפרוקסי מנהרה, והחיבור המוצפן עובר דרכו בלי להיקרא.","Common ports":"פורטים נפוצים","http:// pages":"דפי http://","Fetched by the proxy":"הפרוקסי מביא אותם","https:// pages":"דפי https://","Tunnelled with CONNECT":"במנהרת CONNECT","Used for":"משמש ל־","Filtering, caching, logging":"סינון, מטמון, תיעוד","Two ways through":"שתי דרכים לעבור","Fetched for you, or tunnelled":"הובא בשבילכם, או במנהרה","For the plain page, the proxy did the work: it read the request, fetched the page on its own connection and could have kept, changed or refused it. For HTTPS it only opened a tunnel and copied encrypted bytes, knowing nothing but the site’s name. Press REPLAY to watch it again.":"בדף הלא מוצפן הפרוקסי עשה את העבודה: קרא את הבקשה, הביא את הדף בחיבור משלו ויכול היה לשמור אותו, לשנות אותו או לסרב. ב־HTTPS הוא רק פתח מנהרה והעתיק בתים מוצפנים, בלי לדעת דבר מלבד שם האתר. לחצו על ״שוב״ כדי לצפות שוב.","Server sees":"השרת רואה","The proxy (192.0.2.80)":"את הפרוקסי (192.0.2.80)","Plain HTTP":"HTTP לא מוצפן","The proxy reads it all":"הפרוקסי קורא הכול","Name and sizes only":"רק שם וגדלים","DNS for the site":"DNS לאתר","Done by the proxy":"הפרוקסי עושה","Proxy Settings":"הגדרות פרוקסי","The browser sends everything there":"הדפדפן שולח לשם הכול","The browser is set to send everything through a proxy at 192.0.2.80, port 8080, as many companies and schools require. You open http://www.example.com. The browser doesn’t look up www.example.com itself: it connects to the proxy and leaves the rest to it.":"הדפדפן מוגדר לשלוח הכול דרך פרוקסי בכתובת 192.0.2.80, פורט 8080, כפי שחברות ובתי ספר רבים דורשים. אתם פותחים את http://www.example.com. הדפדפן לא מחפש את www.example.com בעצמו: הוא מתחבר לפרוקסי ומשאיר לו את השאר.","Left to the proxy":"נשאר לפרוקסי","To the Proxy":"אל הפרוקסי","TCP to port 8080":"TCP לפורט 8080","The laptop opens an ordinary TCP connection, not to the website, but to the proxy’s port 8080.":"המחשב הנייד פותח חיבור TCP רגיל, לא אל האתר, אלא אל פורט 8080 של הפרוקסי.","192.0.2.80, port 8080":"192.0.2.80, פורט 8080","Not to":"לא אל","The Whole URL":"ה־URL המלא","Sent to a proxy, the request line carries the whole address, not just the path: GET http://www.example.com/ HTTP/1.1. That is how the proxy knows where to go. Chrome adds Proxy-Connection: keep-alive, a header only proxies read.":"כשהבקשה נשלחת לפרוקסי, שורת הבקשה נושאת את הכתובת המלאה, לא רק את הנתיב: GET http://www.example.com/ HTTP/1.1. כך הפרוקסי יודע לאן ללכת. Chrome מוסיף Proxy-Connection: keep-alive, כותרת שרק פרוקסים קוראים.","Request line":"שורת בקשה","To a server":"אל שרת","Readable by":"קריא ל־","The proxy (plain HTTP)":"הפרוקסי (HTTP לא מוצפן)","to the proxy":"אל הפרוקסי","Proxy Fetches It":"הפרוקסי מביא אותו","Its own connection to the server":"חיבור משלו אל השרת","The proxy looks up www.example.com itself (not shown) and opens its own connection to the server. Its request is the ordinary kind, GET /, with headers of its own: Via names the proxy, and X-Forwarded-For gives the address the request came from (the home router’s public address, since the laptop is behind NAT).":"הפרוקסי מחפש את www.example.com בעצמו (לא מוצג) ופותח חיבור משלו אל השרת. הבקשה שלו רגילה, GET /, עם כותרות משלו: Via מציינת את הפרוקסי, ו־X-Forwarded-For נותנת את הכתובת שממנה הגיעה הבקשה (הכתובת הציבורית של הנתב הביתי, כי המחשב הנייד מאחורי NAT).","The proxy’s own":"החיבור של הפרוקסי עצמו","1.1 proxy.example.net":"1.1 proxy.example.net","Forwarded for":"בשם","Page Passed On":"הדף מועבר הלאה","The page, passed on":"הדף, מועבר הלאה","The server answers the proxy, and the proxy passes the page on to the laptop with a Via header of its own. It could keep a copy and give it to the next person who asks without troubling the server (X-Cache: MISS says it had none yet), and it can refuse sites that aren’t allowed.":"השרת עונה לפרוקסי, והפרוקסי מעביר את הדף למחשב הנייד עם כותרת Via משלו. הוא יכול לשמור עותק ולתת אותו למבקש הבא בלי להטריח את השרת (X-Cache: MISS אומר שעוד לא היה לו עותק), והוא יכול לסרב לאתרים שאינם מותרים.","The proxy, not the laptop":"הפרוקסי, לא המחשב הנייד",Cache:"מטמון","MISS (first request)":"MISS (בקשה ראשונה)","Proxy can":"הפרוקסי יכול","Cache, filter, log, change":"לשמור במטמון, לסנן, לתעד, לשנות","CONNECT www.example.com:443":"CONNECT www.example.com:443","Now you open https://www.example.com. A proxy can’t fetch an HTTPS page for you without breaking its encryption, so the browser asks for a tunnel instead: CONNECT www.example.com:443. The proxy opens a TCP connection to port 443 and answers 200 Connection established.":"עכשיו אתם פותחים את https://www.example.com. פרוקסי לא יכול להביא בשבילכם דף HTTPS בלי לשבור את ההצפנה, ולכן הדפדפן מבקש במקום זאת מנהרה: CONNECT www.example.com:443. הפרוקסי פותח חיבור TCP לפורט 443 ועונה 200 Connection established.","Proxy opens":"הפרוקסי פותח","TCP to port 443":"TCP לפורט 443","200 Connection established":"200 Connection established","Connection established":"החיבור נוצר","In the Tunnel":"במנהרה","The proxy copies, unread":"הפרוקסי מעתיק בלי לקרוא","From now on the proxy copies bytes both ways without reading them. The browser’s TLS Client Hello goes in on the laptop’s connection and comes out, byte for byte the same, on the proxy’s connection to the server. TLS runs from end to end, so the proxy learns the site’s name and the sizes, never the pages. (Some company proxies do open HTTPS, using a certificate authority installed on every company laptop; then they see everything.)":"מעכשיו הפרוקסי מעתיק בתים לשני הכיוונים בלי לקרוא אותם. ה־TLS Client Hello של הדפדפן נכנס בחיבור של המחשב הנייד ויוצא, זהה בית אחר בית, בחיבור של הפרוקסי אל השרת. TLS עובר מקצה לקצה, ולכן הפרוקסי לומד את שם האתר ואת הגדלים, אבל אף פעם לא את הדפים. (יש פרוקסי ארגוניים שכן פותחים HTTPS, בעזרת רשות תעודות שמותקנת בכל מחשב נייד של החברה; ואז הם רואים הכול.)","Proxy sees":"הפרוקסי רואה","Site name, sizes, timing":"שם האתר, גדלים, תזמון","Hidden from it":"מוסתר ממנו","Pages, passwords, cookies":"דפים, סיסמאות, עוגיות","TLS, laptop to server":"TLS, מהמחשב הנייד לשרת","the same bytes":"אותם בתים","COPIES BYTES, CAN’T READ THEM":"מעתיק בתים, לא יכול לקרוא אותם","Any Connection":"כל חיבור","From the proxy":"מהפרוקסי","SOCKS Proxy":"פרוקסי SOCKS","Socket Secure, version 5":"Socket Secure, גרסה 5","SOCKS is a general-purpose proxy. Where an HTTP proxy understands web requests, a SOCKS proxy simply opens a connection on your behalf and copies the bytes, whatever the protocol: web, email, games, SSH. Apps use it to reach a network through one gateway, or to hide their own address; ssh -D and Tor both offer one.":"SOCKS הוא פרוקסי כללי. בעוד שפרוקסי HTTP מבין בקשות אינטרנט, פרוקסי SOCKS פשוט פותח חיבור בשמכם ומעתיק את הבתים, יהיה הפרוטוקול אשר יהיה: אינטרנט, דואר, משחקים, SSH. אפליקציות משתמשות בו כדי להגיע לרשת דרך שער יחיד או כדי להסתיר את הכתובת שלהן; ssh -D ו־Tor מציעים פרוקסי כזה.","Session (Layer 5)":"שכבת הסשן (שכבה 5)","Any TCP, and UDP":"כל TCP, וגם UDP",Logins:"התחברות","None, or user and password":"בלי, או שם משתמש וסיסמה","Offered by":"מוצע על ידי","ssh -D, Tor, proxy servers":"ssh -D, Tor, שרתי פרוקסי","Tunnel open":"המנהרה פתוחה","A few bytes, then just copying":"כמה בתים, ואז רק העתקה","Four tiny messages told the proxy where to connect; after that it only copied bytes. The website saw the proxy’s address, and because the laptop sent a name rather than an address, even the DNS lookup happened at the proxy. Press REPLAY to watch it again.":"ארבע הודעות זעירות אמרו לפרוקסי לאן להתחבר; אחר כך הוא רק העתיק בתים. האתר ראה את הכתובת של הפרוקסי, ומכיוון שהמחשב הנייד שלח שם ולא כתובת, אפילו שאילתת ה־DNS התבצעה בפרוקסי. לחצו על ״שוב״ כדי לצפות שוב.","4 messages, 37 bytes":"4 הודעות, 37 בתים","DNS lookup":"שאילתת DNS","At the proxy":"בפרוקסי","Only the TLS inside":"רק ה־TLS שבפנים","TCP to port 1080":"TCP לפורט 1080","An app set to use a SOCKS proxy (a browser, a game launcher, or a tunnel made with ssh -D) opens a TCP connection to it, port 1080. SOCKS doesn’t care what will travel inside: it can carry any TCP connection.":"אפליקציה שמוגדרת להשתמש בפרוקסי SOCKS (דפדפן, משגר משחקים או מנהרה שנוצרה עם ssh -D) פותחת אליו חיבור TCP, לפורט 1080. ל־SOCKS לא אכפת מה יעבור בפנים: הוא יכול לשאת כל חיבור TCP.","Any TCP connection":"כל חיבור TCP","Wants to reach":"רוצה להגיע אל","https://www.example.com":"https://www.example.com","Version 5, and how to log in":"גרסה 5, ואיך מתחברים","The laptop sends three bytes: version 5, one login method offered, and that method, 0: no login. The proxy answers with two: version 5, method 0. Had it chosen method 2, the app would next send a user name and password, in plain text.":"המחשב הנייד שולח שלושה בתים: גרסה 5, שיטת התחברות אחת מוצעת, והשיטה עצמה, 0: בלי התחברות. הפרוקסי עונה בשניים: גרסה 5, שיטה 0. אילו בחר בשיטה 2, האפליקציה הייתה שולחת אחר כך שם משתמש וסיסמה, כטקסט גלוי.","Laptop sends":"המחשב הנייד שולח","05 01 00 (3 bytes)":"05 01 00 (3 בתים)","Proxy answers":"הפרוקסי עונה","05 00 (2 bytes)":"05 00 (2 בתים)","None needed here":"לא נדרשת כאן",GREETING:"ברכה","no login, please":"בלי התחברות, בבקשה",METHOD:"שיטה","no login needed":"לא נדרשת התחברות","Where To?":"לאן?","Connect to www.example.com:443":"התחבר אל www.example.com:443","The laptop asks the proxy to connect to www.example.com, port 443. It gives the name rather than an address, so the proxy does the DNS lookup and the laptop needs none. The proxy opens its own TCP connection to the server, then replies: succeeded, and the address and port it connected from.":"המחשב הנייד מבקש מהפרוקסי להתחבר אל www.example.com, פורט 443. הוא נותן את השם ולא כתובת, ולכן הפרוקסי מבצע את שאילתת ה־DNS והמחשב הנייד לא צריך אף אחת. הפרוקסי פותח חיבור TCP משלו אל השרת, ואז עונה: הצליח, ואת הכתובת והפורט שמהם התחבר.","www.example.com (a name)":"www.example.com (שם)","Succeeded, from 192.0.2.80:40220":"הצליח, מ־192.0.2.80:40220",SUCCEEDED:"הצליח","from 192.0.2.80:40220":"מ־192.0.2.80:40220","Copied both ways, unread":"מועתק לשני הכיוונים, בלי קריאה","Now the proxy just copies. The app starts TLS with the server: its Client Hello goes in on the laptop’s connection and comes out unchanged on the proxy’s, and the server’s answer comes back the same way. The server only ever sees the proxy’s address; the proxy sees only encrypted bytes.":"עכשיו הפרוקסי רק מעתיק. האפליקציה מתחילה TLS עם השרת: ה־Client Hello שלה נכנס בחיבור של המחשב הנייד ויוצא ללא שינוי בחיבור של הפרוקסי, ותשובת השרת חוזרת באותה דרך. השרת רואה רק את הכתובת של הפרוקסי; הפרוקסי רואה רק בתים מוצפנים.","The proxy’s address":"הכתובת של הפרוקסי","Encrypted bytes":"בתים מוצפנים","Same bytes":"אותם בתים","On both connections":"בשני החיבורים",unchanged:"ללא שינוי","+ encrypted handshake":"+ לחיצת יד מוצפנת","Version 5, 1 method: no login":"גרסה 5, מספר שיטות 1: בלי התחברות","Version 5, method chosen: no login":"גרסה 5, השיטה שנבחרה: בלי התחברות","Succeeded, bound to 192.0.2.80:40220":"הצליח, קשור ל־192.0.2.80:40220","SOCKS5 · greeting":"SOCKS5 · ברכה","Methods offered":"שיטות מוצעות","0 (no login)":"0 (בלי התחברות)","SOCKS5 · method chosen":"SOCKS5 · השיטה שנבחרה","Method chosen":"השיטה שנבחרה","SOCKS5 · connect request":"SOCKS5 · בקשת חיבור","Open a TCP connection on my behalf.":"פתח חיבור TCP בשמי.","Address type":"סוג כתובת","3 (domain name)":"3 (שם דומיין)","The proxy looks the name up itself, so the laptop needs no DNS lookup of its own.":"הפרוקסי מחפש את השם בעצמו, כך שהמחשב הנייד לא צריך שאילתת DNS משלו.","SOCKS5 · reply":"SOCKS5 · תשובה","0 (succeeded)":"0 (הצליח)","The address the proxy connects from.":"הכתובת שממנה הפרוקסי מתחבר.",Offloading:"פריקת TLS","Reverse Proxy":"פרוקסי הפוך","TLS (SSL) offloading":"פריקת TLS (SSL)","A reverse proxy stands in front of a website’s servers: visitors connect to it, and it passes their requests on to an app server behind it. It can spread the load over many servers, keep copies of pages and turn away attacks. Often it also does the TLS work, decrypting HTTPS at the edge so the servers behind it speak plain HTTP. That is SSL (or TLS) offloading.":"פרוקסי הפוך עומד לפני השרתים של אתר: המבקרים מתחברים אליו, והוא מעביר את הבקשות שלהם לשרת אפליקציה שמאחוריו. הוא יכול לפזר את העומס על פני שרתים רבים, לשמור עותקים של דפים ולהדוף התקפות. לעיתים קרובות הוא גם עושה את עבודת ה־TLS, ומפענח HTTPS בקצה כדי שהשרתים שמאחוריו ידברו HTTP לא מוצפן. זו פריקת SSL (או TLS).","Visitors reach":"המבקרים מגיעים אל","The proxy, never the app":"הפרוקסי, אף פעם לא האפליקציה","TLS ends":"TLS מסתיים","At the proxy (offloading)":"בפרוקסי (פריקה)","Plain HTTP (or TLS again)":"HTTP לא מוצפן (או שוב TLS)",Adds:"מוסיף","For example":"לדוגמה","nginx, HAProxy, cloud LBs":"nginx, HAProxy, מאזני עומס בענן","Served from the edge":"מוגש מהקצה","Encrypted outside, plain inside":"מוצפן בחוץ, גלוי בפנים","The laptop saw one HTTPS website. Behind it, the reverse proxy decrypted the request, asked an app server in plain HTTP over the private network and encrypted the answer for the trip back. Press REPLAY to watch it again.":"המחשב הנייד ראה אתר HTTPS אחד. מאחוריו, הפרוקסי ההפוך פענח את הבקשה, ביקש משרת אפליקציה ב־HTTP לא מוצפן דרך הרשת הפרטית והצפין את התשובה לדרך חזרה. לחצו על ״שוב״ כדי לצפות שוב.","Laptop ↔ proxy only":"רק מחשב נייד ↔ פרוקסי","App learns visitor":"האפליקציה יודעת מי המבקר","From X-Forwarded-For":"מ־X-Forwarded-For","Certificate kept":"התעודה נשמרת","On the proxy":"בפרוקסי","The Front Door":"דלת הכניסה","The proxy holds the certificate":"התעודה אצל הפרוקסי","The laptop opens https://www.example.com. The address DNS gives for the name belongs to the reverse proxy, which holds the site’s certificate and does the TLS handshake. Nothing tells the laptop there is another server behind it.":"המחשב הנייד פותח את https://www.example.com. הכתובת ש־DNS נותן לשם שייכת לפרוקסי ההפוך, שמחזיק את התעודה של האתר ומבצע את לחיצת היד של TLS. שום דבר לא מגלה למחשב הנייד שיש שרת נוסף מאחוריו.","Laptop connects to":"המחשב הנייד מתחבר אל","On the reverse proxy":"בפרוקסי ההפוך","Also called":"נקרא גם","Load balancer, edge":"מאזן עומס, קצה","TLS Ends Here":"כאן TLS מסתיים","Offloading: the proxy does the TLS work":"פריקה: הפרוקסי עושה את עבודת ה־TLS","The request arrives encrypted, and the reverse proxy decrypts it. That is the offloading: the TLS work is done here, once, instead of on every app server. Now the proxy can read the URL, headers and cookies, and pick a server by them.":"הבקשה מגיעה מוצפנת, והפרוקסי ההפוך מפענח אותה. זו הפריקה: עבודת ה־TLS נעשית כאן, פעם אחת, במקום בכל שרת אפליקציה. עכשיו הפרוקסי יכול לקרוא את ה־URL, הכותרות והעוגיות, ולבחור שרת לפיהם.","At the reverse proxy":"בפרוקסי ההפוך","Proxy can read":"הפרוקסי יכול לקרוא","URL, headers, cookies":"URL, כותרות, עוגיות","Then picks":"ואז בוחר","An app server":"שרת אפליקציה","TLS ENDS HERE":"כאן TLS מסתיים","In the Clear":"בגלוי","Passed on to the app server":"מועבר לשרת האפליקציה","The proxy passes the request on over the data centre’s private network, as plain HTTP to port 8080. It adds X-Forwarded-For, the visitor’s address, and X-Forwarded-Proto: https, how the visitor came in; otherwise the app would see only the proxy. Anyone able to watch this private network could read it all.":"הפרוקסי מעביר את הבקשה ברשת הפרטית של מרכז הנתונים, כ־HTTP לא מוצפן לפורט 8080. הוא מוסיף X-Forwarded-For, הכתובת של המבקר, ו־X-Forwarded-Proto: https, האופן שבו המבקר הגיע; אחרת האפליקציה הייתה רואה רק את הפרוקסי. כל מי שיכול לצפות ברשת הפרטית הזו היה יכול לקרוא הכול.","The App Answers":"האפליקציה עונה","In plain HTTP too":"גם ב־HTTP לא מוצפן","The app server builds the page and answers the proxy, in plain HTTP: it never deals with TLS or certificates at all.":"שרת האפליקציה בונה את הדף ועונה לפרוקסי ב־HTTP לא מוצפן: הוא אף פעם לא מתעסק עם TLS או תעודות.","text/html, 12,500 bytes":"text/html, 12,500 בתים","readable inside":"קריא בפנים","Encrypted Again":"מוצפן שוב","An ordinary HTTPS answer":"תשובת HTTPS רגילה","The reverse proxy encrypts the answer in the TLS session it holds with the laptop and sends it on. From outside, it is an ordinary HTTPS site.":"הפרוקסי ההפוך מצפין את התשובה בסשן ה־TLS שהוא מחזיק עם המחשב הנייד ושולח אותה הלאה. מבחוץ זה אתר HTTPS רגיל.","Laptop sees":"המחשב הנייד רואה","One HTTPS server":"שרת HTTPS אחד","App servers":"שרתי אפליקציה","Never handle TLS":"אף פעם לא מטפלים ב־TLS",Certificates:"תעודות","Renewed in one place":"מתחדשות במקום אחד","Three Options":"שלוש אפשרויות","Offload, re-encrypt or pass through":"פריקה, הצפנה מחדש או העברה ישירה","Offloading, as here, is simple and fast but leaves the inside traffic readable. Re-encrypting opens a second TLS connection from the proxy to the app server, so it stays encrypted inside too. Passing through forwards the TLS bytes without opening them: the certificate lives on the app servers, and the proxy can only choose a server by address and the name in the Client Hello, not by URL.":"פריקה, כמו כאן, פשוטה ומהירה אבל משאירה את התעבורה הפנימית קריאה. הצפנה מחדש פותחת חיבור TLS שני מהפרוקסי לשרת האפליקציה, כך שגם בפנים הכול נשאר מוצפן. העברה ישירה מעבירה את בתי ה־TLS בלי לפתוח אותם: התעודה נמצאת על שרתי האפליקציה, והפרוקסי יכול לבחור שרת רק לפי הכתובת והשם שב־Client Hello, לא לפי ה־URL.",Offload:"פריקה","Plain HTTP inside":"HTTP לא מוצפן בפנים","Re-encrypt":"הצפנה מחדש","TLS inside as well":"TLS גם בפנים","Pass through":"העברה ישירה","Proxy can’t read it":"הפרוקסי לא יכול לקרוא","PLAIN HTTP INSIDE":"HTTP לא מוצפן בפנים","A Modern VPN":"VPN מודרני","WireGuard (encrypted)":"WireGuard (מוצפן)","TCP beyond the VPN":"TCP מעבר ל־VPN",Keepalive:"Keepalive","VPN Server":"שרת VPN","A VPN carries your traffic inside an encrypted tunnel to a VPN server, which sends it on to the internet. On a café’s Wi-Fi, others see only encrypted packets going to the VPN server; websites see the VPN server’s address instead of yours. WireGuard is a modern VPN: a small amount of code, one fixed set of modern algorithms and a handshake of two messages.":"VPN מעביר את התעבורה שלכם בתוך מנהרה מוצפנת אל שרת VPN, שממשיך לשלוח אותה לאינטרנט. ב־Wi-Fi של בית קפה, אחרים רואים רק חבילות מוצפנות שהולכות לשרת ה־VPN; אתרים רואים את הכתובת של שרת ה־VPN במקום את שלכם. WireGuard הוא VPN מודרני: מעט קוד, ערכה קבועה אחת של אלגוריתמים מודרניים ולחיצת יד של שתי הודעות.","UDP (51820 by default)":"UDP (ברירת מחדל 51820)","2 messages, 1 round trip":"2 הודעות, 1 הלוך ושוב",Crypto:"קריפטוגרפיה",Identity:"זהות","Public keys, like SSH":"מפתחות ציבוריים, כמו ב־SSH","The WireGuard whitepaper":"המאמר הטכני של WireGuard","Tunnel up":"המנהרה פעילה","Encrypted to the VPN, plain beyond it":"מוצפן עד ה־VPN, גלוי אחריו","Two handshake messages made the keys. After that every packet the laptop sent was sealed whole inside a UDP packet to the VPN server, and the website saw only the VPN server’s address. Beyond the VPN server traffic is no better protected than without one, so HTTPS still matters. Press REPLAY to watch it again.":"שתי הודעות לחיצת יד יצרו את המפתחות. אחר כך כל חבילה שהמחשב הנייד שלח נאטמה בשלמותה בתוך חבילת UDP אל שרת ה־VPN, והאתר ראה רק את הכתובת של שרת ה־VPN. מעבר לשרת ה־VPN התעבורה מוגנת לא יותר מאשר בלעדיו, ולכן HTTPS עדיין חשוב. לחצו על ״שוב״ כדי לצפות שוב.","Others nearby see":"אחרים בסביבה רואים","UDP to 192.0.2.51":"UDP אל 192.0.2.51","Websites see":"אתרים רואים","The VPN server":"שרת ה־VPN","Beyond the VPN":"מעבר ל־VPN","Only HTTPS protects":"רק HTTPS מגן",Overhead:"תקורה","60 bytes + padding":"60 בתים + ריפוד","Set Up Once":"מגדירים פעם אחת","Keys, not passwords":"מפתחות, לא סיסמאות","The laptop runs the WireGuard app with a short configuration: its own private key, the server’s public key and address (192.0.2.51, UDP port 51820), and AllowedIPs = 0.0.0.0/0, which means everything goes through the tunnel. Inside the tunnel the laptop’s address is 10.8.0.2.":"המחשב הנייד מריץ את אפליקציית WireGuard עם תצורה קצרה: המפתח הפרטי שלו, המפתח הציבורי והכתובת של השרת (192.0.2.51, פורט UDP 51820), ו־AllowedIPs = 0.0.0.0/0, כלומר הכול עובר דרך המנהרה. בתוך המנהרה הכתובת של המחשב הנייד היא 10.8.0.2.","Inside address":"כתובת פנימית","Through the tunnel":"דרך המנהרה","Everything (0.0.0.0/0)":"הכול (0.0.0.0/0)","TUNNEL ADDRESS 10.8.0.2":"כתובת במנהרה 10.8.0.2","Two messages, one round trip":"שתי הודעות, הלוך ושוב אחד","When the laptop first has something to send, it starts a handshake: 148 bytes with a fresh public key, its own long-term key (encrypted, so only the server learns who is calling) and the time (encrypted, so a recording can’t be replayed). The server answers only keys it knows, here with 92 bytes. One round trip, and both sides have new session keys.":"כשלמחשב הנייד יש לראשונה מה לשלוח, הוא מתחיל לחיצת יד: 148 בתים עם מפתח ציבורי חדש, המפתח הקבוע שלו (מוצפן, כך שרק השרת יודע מי מתקשר) והשעה (מוצפנת, כך שאי אפשר לשדר שוב הקלטה). השרת עונה רק למפתחות שהוא מכיר, כאן ב־92 בתים. הלוך ושוב אחד, ולשני הצדדים יש מפתחות סשן חדשים.",Initiation:"פתיחה","Server answers":"השרת עונה","Only keys it knows":"רק למפתחות מוכרים",INITIATION:"פתיחה","fresh key + identity":"מפתח חדש + זהות",RESPONSE:"תשובה","keys agreed":"מפתחות מוסכמים","Into the Tunnel":"אל תוך המנהרה","A packet inside a packet":"חבילה בתוך חבילה","You open https://www.example.com; its address was looked up through the tunnel too (not shown). The first packet of the connection, a TCP SYN from 10.8.0.2 to the web server, is encrypted whole and sent inside a UDP packet to the VPN server. On the café’s Wi-Fi only the outer packet shows: from the laptop to 192.0.2.51, port 51820.":"אתם פותחים את https://www.example.com; גם הכתובת שלו נשאלה דרך המנהרה (לא מוצג). החבילה הראשונה בחיבור, TCP SYN מ־10.8.0.2 לשרת האינטרנט, מוצפנת בשלמותה ונשלחת בתוך חבילת UDP אל שרת ה־VPN. ב־Wi-Fi של בית הקפה רואים רק את החבילה החיצונית: מהמחשב הנייד אל 192.0.2.51, פורט 51820.",Outside:"בחוץ","UDP to 192.0.2.51:51820":"UDP אל 192.0.2.51:51820","inside: TCP SYN to :443":"בפנים: TCP SYN אל :443","Out to the Web":"החוצה לאינטרנט","Decrypted, then sent on":"מפוענח ונשלח הלאה","The VPN server decrypts the packet, swaps 10.8.0.2 for its own public address (NAT) and sends the SYN on, one hop older (TTL 127). The SYN offers a maximum segment of 1380 bytes, not 1460: the tunnel adds 60 bytes to every packet. The web server sees a visitor at 192.0.2.51 and answers there.":"שרת ה־VPN מפענח את החבילה, מחליף את 10.8.0.2 בכתובת הציבורית שלו (NAT) ושולח את ה־SYN הלאה, מבוגר בקפיצה אחת (TTL 127). ה־SYN מציע מקטע מרבי של 1380 בתים, לא 1460: המנהרה מוסיפה 60 בתים לכל חבילה. שרת האינטרנט רואה מבקר ב־192.0.2.51 ועונה לשם.","Website sees":"האתר רואה","192.0.2.51 (the VPN)":"192.0.2.51 (ה־VPN)","Hidden from the site":"מוסתרת מהאתר","127 (one hop, the VPN)":"127 (קפיצה אחת, ה־VPN)","from 192.0.2.51":"מ־192.0.2.51","The Way Back":"הדרך חזרה","Sealed again, for the laptop":"נאטם שוב, בשביל המחשב הנייד","The answer goes back the same way. The VPN server seals the SYN-ACK in a WireGuard packet for the laptop, which opens it and hands it to Windows as if it had come straight from the web server.":"התשובה חוזרת באותה דרך. שרת ה־VPN אוטם את ה־SYN-ACK בחבילת WireGuard בשביל המחשב הנייד, שפותח אותה ומוסר אותה ל־Windows כאילו הגיעה ישר משרת האינטרנט.",Counter:"מונה","Each side counts its own":"כל צד סופר בעצמו",Replays:"שידורים חוזרים","Thrown away":"נזרקים","inside: TCP SYN-ACK":"בפנים: TCP SYN-ACK","Keeping It Open":"להשאיר פתוח","A keepalive, and new keys":"Keepalive, ומפתחות חדשים","With nothing to send, a WireGuard tunnel goes quiet. Because the laptop is behind NAT, it is set to send an empty packet every 25 seconds (PersistentKeepalive), a keepalive of 32 bytes, so the router doesn’t forget the connection. Every two minutes a new handshake makes fresh keys, and if the laptop moves to another network, the tunnel simply carries on from its new address.":"כשאין מה לשלוח, מנהרת WireGuard שותקת. מכיוון שהמחשב הנייד מאחורי NAT, הוא מוגדר לשלוח חבילה ריקה כל 25 שניות (PersistentKeepalive), keepalive של 32 בתים, כדי שהנתב לא ישכח את החיבור. כל שתי דקות לחיצת יד חדשה יוצרת מפתחות טריים, ואם המחשב הנייד עובר לרשת אחרת, המנהרה פשוט ממשיכה מהכתובת החדשה.","Every 25 s, 32 bytes":"כל 25 שניות, 32 בתים","New keys":"מפתחות חדשים","Every 2 minutes":"כל 2 דקות","New network":"רשת חדשה","The tunnel carries on":"המנהרה ממשיכה",KEEPALIVE:"KEEPALIVE","empty, 32 bytes":"ריקה, 32 בתים","Message type":"סוג הודעה","Sender index":"אינדקס השולח","A number this side picked for the session; the other side puts it in every packet it sends back.":"מספר שהצד הזה בחר לסשן; הצד השני שם אותו בכל חבילה שהוא שולח בחזרה.","Ephemeral key":"מפתח זמני","A new public key, made just for this handshake.":"מפתח ציבורי חדש, שנוצר רק בשביל לחיצת היד הזו.","Encrypted static key":"מפתח קבוע מוצפן","The laptop’s long-term public key (32 bytes) and a 16-byte tag, encrypted: only the server learns who is calling.":"המפתח הציבורי הקבוע של המחשב הנייד (32 בתים) ותג של 16 בתים, מוצפנים: רק השרת יודע מי מתקשר.","Encrypted timestamp":"חותמת זמן מוצפנת","The time (12 bytes) and a tag, encrypted. An old initiation sent again is refused.":"השעה (12 בתים) ותג, מוצפנים. הודעת פתיחה ישנה שנשלחת שוב נדחית.","Keyed with the server’s public key: without it, the server doesn’t answer at all.":"מחושב עם המפתח הציבורי של השרת: בלעדיו השרת לא עונה בכלל.","Used only when the server is busy and asks for a cookie first.":"בשימוש רק כשהשרת עמוס ומבקש קודם עוגייה.","Receiver index":"אינדקס המקבל","The other side’s index: which session this packet belongs to.":"האינדקס של הצד השני: לאיזה סשן שייכת החבילה הזו.","The server’s new public key for this handshake.":"המפתח הציבורי החדש של השרת ללחיצת היד הזו.","Encrypted nothing":"כלום מוצפן","Only a tag: it proves the server holds its private key.":"רק תג: הוא מוכיח שהשרת מחזיק את המפתח הפרטי שלו.","Counts up with every packet; one seen before is thrown away.":"עולה בכל חבילה; חבילה שכבר נראתה נזרקת.","The whole inner packet, padded to a multiple of 16 bytes, then a 16-byte tag.":"כל החבילה הפנימית, מרופדת עד כפולה של 16 בתים, ואחריה תג של 16 בתים.","then 12 bytes of padding, and the tag":"ואחר כך 12 בתים של ריפוד, והתג","The laptop sent it with 128; the VPN server took 1 when it passed it on.":"המחשב הנייד שלח אותה עם 128; שרת ה־VPN הוריד 1 כשהעביר אותה הלאה.","Nothing but the 16-byte tag: an empty packet that keeps the tunnel open.":"שום דבר מלבד התג של 16 בתים: חבילה ריקה ששומרת על המנהרה פתוחה.","ESP (encrypted)":"ESP (מוצפן)","TCP beyond the gateway":"TCP מעבר לשער","VPN Gateway":"שער VPN","IP Security":"אבטחת IP","IPsec protects IP packets themselves. IKEv2 sets things up: the two sides agree on algorithms, make keys and prove who they are with certificates or other credentials. Then ESP carries each packet encrypted inside another. IPsec links offices together and brings laptops into company networks, and it is built into most operating systems and firewalls.":"IPsec מגן על חבילות ה־IP עצמן. IKEv2 מכין הכול: שני הצדדים מסכימים על אלגוריתמים, יוצרים מפתחות ומוכיחים מי הם בעזרת תעודות או פרטי זיהוי אחרים. אחר כך ESP נושא כל חבילה מוצפנת בתוך חבילה אחרת. IPsec מחבר משרדים זה לזה ומכניס מחשבים ניידים לרשתות של חברות, והוא מובנה ברוב מערכות ההפעלה וחומות האש.","Behind NAT":"מאחורי NAT","ESP (IP protocol 50)":"ESP (פרוטוקול IP 50)","Certificates, EAP, keys":"תעודות, EAP, מפתחות","IKE to set up, ESP to carry":"IKE להקמה, ESP להעברה","Four IKE messages agreed on algorithms, found the NAT, proved both identities and set up the tunnel. After that each packet travelled whole inside ESP, encrypted and checked, and wrapped in UDP to get through the home router. Press REPLAY to watch it again.":"ארבע הודעות IKE הסכימו על אלגוריתמים, גילו את ה־NAT, הוכיחו את שתי הזהויות והקימו את המנהרה. אחר כך כל חבילה עברה בשלמותה בתוך ESP, מוצפנת ומאומתת, ועטופה ב־UDP כדי לעבור דרך הנתב הביתי. לחצו על ״שוב״ כדי לצפות שוב.","IKE messages":"הודעות IKE","4 (2 exchanges)":"4 (2 חילופים)","NAT traversal":"מעבר NAT","One SPI each way":"SPI אחד לכל כיוון","Agree on algorithms, swap keys":"הסכמה על אלגוריתמים, החלפת מפתחות","The VPN client opens with IKE on UDP port 500. Its first message proposes the algorithms (AES-GCM with 256-bit keys, SHA-256, Curve25519) and carries a public key and a random nonce; the gateway picks the proposal and sends its own key and nonce. Both now share a secret, but neither has proved who it is yet.":"לקוח ה־VPN פותח ב־IKE בפורט UDP 500. ההודעה הראשונה שלו מציעה את האלגוריתמים (AES-GCM עם מפתחות של 256 ביט, SHA-256, Curve25519) ונושאת מפתח ציבורי ו־nonce אקראי; השער בוחר בהצעה ושולח מפתח ו־nonce משלו. עכשיו לשניהם יש סוד משותף, אבל אף אחד עוד לא הוכיח מי הוא.",Proposed:"מוצע","After this":"אחרי זה","Shared keys, no identities":"מפתחות משותפים, בלי זהויות","proposal, key, nonce":"הצעה, מפתח, nonce","NAT detection":"זיהוי NAT","chosen proposal, key, nonce":"ההצעה שנבחרה, מפתח, nonce","A NAT in the Way":"NAT בדרך","So everything moves to port 4500":"ולכן הכול עובר לפורט 4500","Both messages also carried hashes of the address and port each side sent from. At the gateway they don’t match what arrived: the home router rewrote the laptop’s address on the way (NAT). ESP has no port numbers, so a NAT can’t pass it; both sides move to UDP port 4500 and wrap ESP in UDP from now on.":"שתי ההודעות נשאו גם גיבובים של הכתובת והפורט שמהם שלח כל צד. בשער הם לא תואמים למה שהגיע: הנתב הביתי שכתב בדרך את הכתובת של המחשב הנייד (NAT). ל־ESP אין מספרי פורטים, ולכן NAT לא יכול להעביר אותו; שני הצדדים עוברים לפורט UDP 4500 ומעכשיו עוטפים את ESP ב־UDP.","Hashes of":"גיבובים של","Address and port sent from":"הכתובת והפורט שמהם נשלח",Mismatch:"אי־התאמה","The router rewrote them":"הנתב שכתב אותם",Fix:"הפתרון","Everything over UDP 4500":"הכול דרך UDP 4500","NAT DETECTED":"זוהה NAT","Prove who you are, encrypted":"להוכיח מי אתה, מוצפן","Now encrypted, each side sends its identity, its certificate and a signature over everything said so far, so anyone in the middle would be caught. The laptop asks for an address inside the network and gets 10.8.0.2. The same exchange sets up the ESP tunnel itself, with its own keys and an SPI for each direction.":"עכשיו, כשהכול מוצפן, כל צד שולח את הזהות שלו, את התעודה שלו וחתימה על כל מה שנאמר עד כה, כך שכל מי שיושב באמצע ייתפס. המחשב הנייד מבקש כתובת בתוך הרשת ומקבל 10.8.0.2. אותו חילוף גם מקים את מנהרת ה־ESP עצמה, עם מפתחות משלה ו־SPI לכל כיוון.","UDP 4500 (NAT traversal)":"UDP 4500 (מעבר NAT)","Identity, by certificate":"זהות, בתעודה","Laptop gets":"המחשב הנייד מקבל","10.8.0.2, and a DNS server":"10.8.0.2 ושרת DNS","identity, certificate":"זהות, תעודה",signature:"חתימה","address 10.8.0.2":"כתובת 10.8.0.2","The whole packet, encrypted":"כל החבילה, מוצפנת","You open https://www.example.com, looked up through the tunnel at the DNS server the gateway gave (not shown). The SYN from 10.8.0.2 is encrypted whole into an ESP packet: an SPI that names the tunnel, a sequence number, then the encrypted packet and a check value, all inside UDP port 4500. Its UDP checksum is zero: ESP checks its own contents.":"אתם פותחים את https://www.example.com, שנשאל דרך המנהרה בשרת ה־DNS שהשער נתן (לא מוצג). ה־SYN מ־10.8.0.2 מוצפן בשלמותו לתוך חבילת ESP: SPI שמציין את המנהרה, מספר רצף, ואחריהם החבילה המוצפנת וערך בדיקה, הכול בתוך UDP פורט 4500. סכום הביקורת של UDP הוא אפס: ESP בודק את התוכן שלו בעצמו.","Names the tunnel":"מציין את המנהרה","The whole IP packet":"כל חבילת ה־IP","62 bytes + padding":"62 בתים + ריפוד","Out and Back":"הלוך וחזור","Through the gateway and home again":"דרך השער ובחזרה הביתה","The gateway decrypts the packet and sends the SYN on from its own address, one hop older. The answer comes back to the gateway and returns through the tunnel as another ESP packet, with the SPI for the laptop’s direction and its own sequence numbers.":"השער מפענח את החבילה ושולח את ה־SYN הלאה מהכתובת שלו, מבוגר בקפיצה אחת. התשובה חוזרת לשער ומשם חוזרת במנהרה כחבילת ESP נוספת, עם ה־SPI של הכיוון של המחשב הנייד ומספרי רצף משלה.","192.0.2.51 (the gateway)":"192.0.2.51 (השער)","Each direction":"כל כיוון","Its own SPI and keys":"SPI ומפתחות משלו","Which VPN?":"איזה VPN?","IPsec or WireGuard":"IPsec או WireGuard","IPsec is older and very flexible: it negotiates its algorithms, takes many kinds of credentials and is built into Windows, macOS, iOS, Android and most firewalls, which makes it the usual way to join a company network or link two offices. WireGuard does less, with far less code and one fixed set of algorithms.":"IPsec ותיק יותר וגמיש מאוד: הוא מנהל משא ומתן על האלגוריתמים, מקבל סוגים רבים של פרטי זיהוי ומובנה ב־Windows, macOS, iOS, Android וברוב חומות האש, ולכן הוא הדרך המקובלת להצטרף לרשת של חברה או לחבר שני משרדים. WireGuard עושה פחות, עם הרבה פחות קוד וערכה קבועה אחת של אלגוריתמים.","Built into":"מובנה ב־","Also links":"מחבר גם","Office to office":"משרד למשרד",Negotiates:"מנהל משא ומתן על","Its algorithms (WireGuard: no)":"האלגוריתמים (WireGuard: לא)","Initiator SPI":"SPI של היוזם","Picked by the laptop: which IKE session this is.":"נבחר על ידי המחשב הנייד: איזה סשן IKE זה.","Responder SPI":"SPI של המשיב","0 (not known yet)":"0 (עדיין לא ידוע)","Next payload":"המטען הבא","Exchange type":"סוג החילוף","0x08 (initiator)":"0x08 (יוזם)","Message ID":"מזהה הודעה","Each request and its response share a number; the next exchange counts up.":"כל בקשה והתשובה לה חולקות מספר; החילוף הבא מגדיל אותו.","SA payload":"מטען SA","Next payload, length":"המטען הבא, אורך",Proposal:"הצעה","What the laptop offers; a real client often offers several.":"מה שהמחשב הנייד מציע; לקוח אמיתי מציע לעיתים קרובות כמה הצעות.","KE payload":"מטען KE","DH group":"קבוצת DH","This side’s public key. From the two, both work out the same secret.":"המפתח הציבורי של הצד הזה. משני המפתחות שני הצדדים מחשבים אותו סוד.","Nonce payload":"מטען Nonce","Notify payload":"מטען Notify",Notify:"Notify",Hash:"גיבוב","A hash of the SPIs and the address and port this side sent from. If what arrives doesn’t match, a NAT changed it on the way.":"גיבוב של ה־SPI ושל הכתובת והפורט שמהם הצד הזה שלח. אם מה שמגיע לא תואם, NAT שינה אותו בדרך.","The same for the address and port it sent to.":"אותו דבר לכתובת ולפורט שאליהם נשלח.","0x20 (response)":"0x20 (תשובה)","The one the server chose from the laptop’s offer.":"זו שהשרת בחר מתוך מה שהמחשב הנייד הציע.","Non-ESP marker":"סמן שאינו ESP","Four zero bytes: an IKE message, not an ESP packet (they share port 4500).":"ארבעה בתים של אפס: הודעת IKE, לא חבילת ESP (הן חולקות את פורט 4500).","Encrypted payload":"מטען מוצפן","Encrypted payloads":"מטענים מוצפנים","Everything else in this message, encrypted with the keys from IKE_SA_INIT.":"כל השאר בהודעה הזו, מוצפן במפתחות מ־IKE_SA_INIT.","IDi, CERT, AUTH: who the laptop is, proven":"IDi, CERT, AUTH: מי המחשב הנייד, עם הוכחה","CP: asks for an inside address and DNS":"CP: מבקש כתובת פנימית ו־DNS","SA: what to use for ESP (AES-GCM)":"SA: במה להשתמש ל־ESP (AES-GCM)","TSi, TSr: which traffic goes in the tunnel":"TSi, TSr: איזו תעבורה נכנסת למנהרה","Integrity check":"בדיקת שלמות","IDr, CERT, AUTH: who the gateway is, proven":"IDr, CERT, AUTH: מי השער, עם הוכחה","CP: inside address 10.8.0.2, DNS 10.8.0.1":"CP: כתובת פנימית 10.8.0.2, DNS 10.8.0.1","SA: ESP with AES-GCM, and the SPIs":"SA: ESP עם AES-GCM, וה־SPI","TSi, TSr: everything (0.0.0.0/0)":"TSi, TSr: הכול (0.0.0.0/0)","0 (not used)":"0 (לא בשימוש)","ESP checks its own contents, so ESP carried in UDP leaves this at zero.":"ESP בודק את התוכן שלו בעצמו, ולכן ESP שעובר בתוך UDP משאיר כאן אפס.","Which tunnel (security association) this belongs to; the receiving side chose it during IKE_AUTH.":"לאיזו מנהרה (Security Association) זה שייך; הצד המקבל בחר בה במהלך IKE_AUTH.","Different for every packet.":"שונה בכל חבילה.","The whole inner packet, then padding, the pad length and the next header (4: an IPv4 packet).":"כל החבילה הפנימית, ואחריה ריפוד, אורך הריפוד והכותרת הבאה (4: חבילת IPv4).","then padding, pad length and next header (4)":"ואחריה ריפוד, אורך הריפוד והכותרת הבאה (4)","Shows any change to the packet.":"חושף כל שינוי בחבילה.","The laptop sent it with 128; the gateway took 1 when it passed it on.":"המחשב הנייד שלח אותה עם 128; השער הוריד 1 כשהעביר אותה הלאה.","HTTP/3 over QUIC":"HTTP/3 מעל QUIC","QUIC is a newer transport that runs over UDP and has TLS 1.3 built in. Its first packets do the transport and the encryption handshakes together, so a page request can leave after one round trip. It carries many streams at once, so one lost packet doesn’t hold up the rest, and it survives a change of network. HTTP/3 is HTTP running over QUIC.":"QUIC הוא פרוטוקול תעבורה חדש יותר שרץ מעל UDP ו־TLS 1.3 מובנה בו. החבילות הראשונות שלו מבצעות יחד את לחיצת היד של התעבורה ושל ההצפנה, כך שבקשה לדף יכולה לצאת אחרי הלוך ושוב אחד. הוא נושא זרמים רבים בבת אחת, כך שחבילה אבודה לא מעכבת את השאר, והוא שורד החלפת רשת. HTTP/3 הוא HTTP שרץ מעל QUIC.","Runs over":"רץ מעל","UDP, port 443":"UDP, פורט 443","TLS 1.3, always":"TLS 1.3, תמיד","1 round trip (0 when returning)":"1 הלוך ושוב (0 בביקור חוזר)",Streams:"זרמים","Many, independent":"רבים, בלתי תלויים","One round trip, then the request":"הלוך ושוב אחד, ואז הבקשה","QUIC folded the transport and TLS handshakes into one round trip, so the request left 36 ms after the first packet; over TCP and TLS it would have waited twice as long. Everything after the first packets was encrypted, even most of each packet’s header. Press REPLAY to watch it again.":"QUIC איחד את לחיצות היד של התעבורה ושל TLS להלוך ושוב אחד, כך שהבקשה יצאה 36 ms אחרי החבילה הראשונה; מעל TCP ו־TLS היא הייתה מחכה פי שניים. כל מה שאחרי החבילות הראשונות היה מוצפן, אפילו רוב הכותרת של כל חבילה. לחצו על ״שוב״ כדי לצפות שוב.","1 before the request (TCP + TLS: 2)":"1 לפני הבקשה (TCP + TLS: 2)","Lost packet":"חבילה אבודה","Holds up one stream only":"מעכבת רק זרם אחד","Choosing HTTP/3":"בחירה ב־HTTP/3","An earlier visit said it can":"ביקור קודם אמר שאפשר",'On an earlier visit the server answered with Alt-Svc: h3=":443", meaning it also speaks HTTP/3 on UDP port 443 (DNS can say the same in an HTTPS record). So this time the browser skips TCP and talks QUIC.':'בביקור קודם השרת ענה עם Alt-Svc: h3=":443", כלומר הוא מדבר גם HTTP/3 בפורט UDP 443 (גם DNS יכול לומר את זה ברשומת HTTPS). לכן הפעם הדפדפן מדלג על TCP ומדבר QUIC.',"Learned from":"נודע מתוך","Alt-Svc header, or DNS":"כותרת Alt-Svc, או DNS","QUIC over UDP 443":"QUIC מעל UDP 443","TLS 1.3, built in":"TLS 1.3, מובנה","Initial Packets":"חבילות Initial","The Client Hello, straight away":"ה־Client Hello, מיד","There is no separate TCP handshake: the very first packets carry the TLS Client Hello. With its post-quantum key share it is 1,880 bytes, too big for one packet, so it fills two Initial packets. Each datagram is padded to at least 1,200 bytes; a server may send back only three times what it has received, so a forged sender address can’t turn it into an amplifier.":"אין לחיצת יד נפרדת של TCP: כבר החבילות הראשונות נושאות את ה־TLS Client Hello. עם חלק המפתח הפוסט־קוונטי הוא שוקל 1,880 בתים, יותר מדי לחבילה אחת, ולכן הוא ממלא שתי חבילות Initial. כל דאטגרם מרופד לפחות ל־1,200 בתים; שרת רשאי לשלוח בחזרה רק פי שלושה ממה שקיבל, כדי שכתובת שולח מזויפת לא תהפוך אותו למגבר.","2 × 1,250 bytes":"2 × 1,250 בתים","The TLS Client Hello":"ה־TLS Client Hello","Readable?":"קריא?","Yes (Initial keys are public)":"כן (מפתחות Initial ציבוריים)","Client Hello, part 1":"Client Hello, חלק 1","Client Hello, part 2":"Client Hello, חלק 2",padding:"ריפוד","Then the certificate, encrypted":"ואז התעודה, מוצפנת","The server answers with its Server Hello in an Initial packet. Both sides can now work out handshake keys, so the rest (the certificate, its signature and Finished) comes in Handshake packets that only the laptop can read. Four datagrams, well under three times what the laptop sent.":"השרת עונה ב־Server Hello שלו בחבילת Initial. עכשיו שני הצדדים יכולים לחשב מפתחות לחיצת יד, ולכן השאר (התעודה, החתימה עליה ו־Finished) מגיע בחבילות Handshake שרק המחשב הנייד יכול לקרוא. ארבעה דאטגרמים, הרבה מתחת לפי שלושה ממה שהמחשב הנייד שלח.","Certificate, signature, Finished":"תעודה, חתימה, Finished","Server limit":"מגבלת השרת","3× the bytes received":"3× הבתים שהתקבלו","certificate, Finished":"תעודה, Finished","The request, one round trip in":"הבקשה, אחרי הלוך ושוב אחד","The laptop checks the certificate and sends its Finished, and in the same moment its first HTTP/3 request in a 1-RTT packet: a HEADERS frame on stream 0, its headers compressed with QPACK. One round trip after the first packet, the request is on its way; TCP and TLS together would need two.":"המחשב הנייד בודק את התעודה ושולח את ה־Finished שלו, ובאותו רגע את בקשת ה־HTTP/3 הראשונה בחבילת 1-RTT: מסגרת HEADERS בזרם 0, והכותרות דחוסות ב־QPACK. הלוך ושוב אחד אחרי החבילה הראשונה הבקשה כבר בדרך; TCP ו־TLS יחד היו צריכים שניים.","1 (TCP + TLS: 2)":"1 (TCP + TLS: 2)","HEADERS on stream 0":"HEADERS בזרם 0",Headers:"כותרות","Compressed (QPACK)":"דחוסות (QPACK)","HTTP/3, stream 0":"HTTP/3, זרם 0","The Response":"התשובה","On its own stream":"בזרם משלה","The server confirms the handshake is over (HANDSHAKE_DONE) and answers on stream 0: headers, then the page. Every request gets its own stream, so a lost packet holds up only the stream it belonged to. Over TCP one missing segment stalls everything behind it.":"השרת מאשר שלחיצת היד הסתיימה (HANDSHAKE_DONE) ועונה בזרם 0: כותרות, ואז הדף. לכל בקשה יש זרם משלה, כך שחבילה אבודה מעכבת רק את הזרם שאליו השתייכה. ב־TCP מקטע אחד חסר עוצר את כל מה שאחריו.","Frames on QUIC streams":"מסגרות בזרמי QUIC","Holds up one stream":"מעכבת זרם אחד","All but a few header bits":"הכול חוץ מכמה ביטים בכותרת","the page":"הדף","New Network":"רשת חדשה","Known by ID, not by address":"מזוהה לפי מזהה, לא לפי כתובת","A QUIC connection is known by its connection IDs, not by addresses and ports. If the laptop moves from Wi-Fi to a phone’s hotspot, its address changes but the connection carries on: the server checks the new path and continues. And on the next visit the browser can send its request in its very first packets (0-RTT).":"חיבור QUIC מזוהה לפי מזהי החיבור שלו, לא לפי כתובות ופורטים. אם המחשב הנייד עובר מ־Wi-Fi לנקודה חמה של טלפון, הכתובת שלו משתנה אבל החיבור ממשיך: השרת בודק את המסלול החדש וממשיך. ובביקור הבא הדפדפן יכול לשלוח את הבקשה כבר בחבילות הראשונות שלו (0-RTT).","Known by":"מזוהה לפי","Connection ID":"מזהה חיבור","New address":"כתובת חדשה","The connection carries on":"החיבור ממשיך","Next visit":"הביקור הבא","0-RTT: request at once":"0-RTT: בקשה מיד","SAME CONNECTION ON ANY NETWORK":"אותו חיבור בכל רשת","Initial, CRYPTO (Client Hello, part 1)":"Initial, CRYPTO (Client Hello, חלק 1)","Initial, CRYPTO (Client Hello, part 2), PADDING":"Initial, CRYPTO (Client Hello, חלק 2), PADDING","Handshake, CRYPTO (Certificate, part 1)":"Handshake, CRYPTO (תעודה, חלק 1)","Handshake, CRYPTO (Certificate, part 2)":"Handshake, CRYPTO (תעודה, חלק 2)","Initial packet":"חבילת Initial","Header type":"סוג כותרת","long header, Initial":"כותרת ארוכה, Initial","The top bits say what kind of packet this is; the last bits are disguised (header protection).":"הביטים העליונים אומרים איזה סוג חבילה זו; הביטים האחרונים מוסווים (הגנת כותרת).","Destination connection ID":"מזהה חיבור יעד","Which connection this belongs to. Each side picks its own ID; the other writes it here.":"לאיזה חיבור זה שייך. כל צד בוחר מזהה משלו; הצד השני כותב אותו כאן.","Source connection ID":"מזהה חיבור מקור","Token length":"אורך האסימון","No token: the server hasn’t asked this client to prove its address first.":"אין אסימון: השרת לא ביקש מהלקוח הזה להוכיח קודם את הכתובת שלו.","The packet number and payload. Whatever follows is another packet in the same datagram.":"מספר החבילה והמטען. מה שבא אחריהם הוא חבילה נוספת באותו דאטגרם.","Packet number":"מספר חבילה","Hidden by header protection, so nobody on the way can read or change it.":"מוסתר בהגנת הכותרת, כך שאף אחד בדרך לא יכול לקרוא או לשנות אותו.","Encrypted with keys anyone can work out from the connection ID, so it stops accidents, not eavesdroppers: the Client Hello inside can be read on the way.":"מוצפן במפתחות שכל אחד יכול לחשב ממזהה החיבור, ולכן זה מונע תקלות, לא מצותתים: את ה־Client Hello שבפנים אפשר לקרוא בדרך.","CRYPTO: Client Hello, bytes 1–1,203 of 1,880":"CRYPTO: Client Hello, בתים 1–1,203 מתוך 1,880","SNI www.example.com, ALPN h3, X25519MLKEM768 key share":"SNI www.example.com, ALPN h3, חלק מפתח X25519MLKEM768","CRYPTO: Client Hello, bytes 1,204–1,880":"CRYPTO: Client Hello, בתים 1,204–1,880","PADDING, up to 1,250 bytes":"PADDING, עד 1,250 בתים","ACK: packets 0–1 arrived":"ACK: חבילות 0–1 הגיעו","CRYPTO: Server Hello, with its half of the key (1,120 bytes)":"CRYPTO: Server Hello, עם החצי שלו מהמפתח (1,120 בתים)","Handshake packet":"חבילת Handshake","long header, Handshake":"כותרת ארוכה, Handshake","Encrypted with keys from the key exchange so far.":"מוצפן במפתחות מהחלפת המפתחות עד כה.","CRYPTO: Encrypted Extensions, Certificate (start)":"CRYPTO: Encrypted Extensions, Certificate (התחלה)","CRYPTO: Certificate (continued)":"CRYPTO: Certificate (המשך)","CRYPTO: Certificate Verify, Finished":"CRYPTO: Certificate Verify, Finished","ACK: the server’s Initial arrived":"ACK: ה־Initial של השרת הגיע","ACK: the Handshake packets arrived":"ACK: חבילות ה־Handshake הגיעו","1-RTT packet":"חבילת 1-RTT","short header":"כותרת קצרה","Only the receiver’s ID, and no length: it knows how long its own IDs are. It stays the same if the laptop changes network.":"רק המזהה של המקבל, ובלי אורך: הוא יודע מה אורך המזהים שלו. הוא נשאר זהה גם אם המחשב הנייד מחליף רשת.","Encrypted with the session keys.":"מוצפן במפתחות הסשן.","STREAM 2: SETTINGS (the control stream)":"STREAM 2: SETTINGS (זרם הבקרה)","STREAM 0: HEADERS, GET / (QPACK-compressed)":"STREAM 0: HEADERS, GET / (דחוס ב־QPACK)","HANDSHAKE_DONE: the handshake is over":"HANDSHAKE_DONE: לחיצת היד הסתיימה","STREAM 0: HEADERS 200, then DATA: the page (1,000 bytes)":"STREAM 0: HEADERS 200, ואז DATA: הדף (1,000 בתים)","ACK: the response arrived":"ACK: התשובה הגיעה","Address Setup":"הגדרת כתובת","No IPv6 address":"אין כתובת IPv6","IPv6: SLAAC and neighbour discovery":"IPv6: SLAAC וגילוי שכנים","IPv6 addresses are 128 bits long, enough for every device to have its own. A device can usually set itself up with no DHCP server: it makes a link-local address, asks for a router, and builds its global address from the prefix the router advertises (SLAAC). Neighbour discovery, part of ICMPv6, finds MAC addresses and does the work ARP does for IPv4.":"כתובות IPv6 הן באורך 128 ביט, מספיק כדי שלכל מכשיר תהיה כתובת משלו. בדרך כלל מכשיר יכול להגדיר את עצמו בלי שרת DHCP: הוא יוצר כתובת link-local, שואל על נתב ובונה את הכתובת הגלובלית שלו מהקידומת שהנתב מכריז עליה (SLAAC). גילוי שכנים, חלק מ־ICMPv6, מוצא כתובות MAC ועושה את העבודה ש־ARP עושה ב־IPv4.","128 bits":"128 ביט",Addresses:"כתובות","SLAAC: no server needed":"SLAAC: בלי שרת","Replaces ARP":"מחליף את ARP","Neighbour discovery":"גילוי שכנים",Optional:"אופציונלי","Two addresses, no DHCP":"שתי כתובות, בלי DHCP","Made by the laptop itself":"נוצרו בידי המחשב הנייד עצמו","The laptop made a link-local address and a global one, checked that nobody else had either, and learned its router, MTU and DNS server from a single advertisement. When packets came for it, neighbour discovery found its MAC address. Press REPLAY to watch it again.":"המחשב הנייד יצר כתובת link-local וכתובת גלובלית, בדק שלאף אחד אחר אין אף אחת מהן, ולמד את הנתב, את ה־MTU ואת שרת ה־DNS שלו מהכרזה אחת. כשהגיעו אליו חבילות, גילוי שכנים מצא את כתובת ה־MAC שלו. לחצו על ״שוב״ כדי לצפות שוב.","Link-local":"Link-local",Global:"גלובלית","2001:db8:1234:5678::/64 + its own ID":"2001:db8:1234:5678::/64 + מזהה משלו","Router, DNS":"נתב, DNS","From one advertisement":"מהכרזה אחת","6, all ICMPv6":"6, כולן ICMPv6","Link-Local First":"קודם link-local","Every IPv6 interface gets a link-local address, usable only on its own network. The laptop makes one from fe80:: and a random-looking 64-bit interface ID. First it checks nobody already has it: a Neighbor Solicitation asking for that address, sent from :: because it can’t use the address yet. Nobody answers, so it’s the laptop’s.":"כל ממשק IPv6 מקבל כתובת link-local, שמתאימה רק לרשת שלו. המחשב הנייד יוצר אחת מ־fe80:: וממזהה ממשק של 64 ביט שנראה אקראי. קודם הוא בודק שלאף אחד אין אותה כבר: Neighbor Solicitation ששואל על הכתובת הזו, נשלח מ־:: כי הוא עוד לא יכול להשתמש בכתובת. אף אחד לא עונה, אז היא של המחשב הנייד.",Check:"בדיקה","Duplicate address detection":"זיהוי כתובות כפולות","None: the address is free":"אין: הכתובת פנויה","IS IT TAKEN?":"תפוסה?","from ::":"מ־::","target fe80::8d2e:4f61:a9b0:7c13":"יעד fe80::8d2e:4f61:a9b0:7c13","NO ANSWER: ADDRESS IS FREE":"אין תשובה: הכתובת פנויה","Any Routers?":"יש נתבים?","A Router Solicitation":"Router Solicitation","Link-local addresses can’t reach the internet. The laptop sends a Router Solicitation to ff02::2, the address every router on the network listens to, with its own MAC address attached.":"כתובות link-local לא מגיעות לאינטרנט. המחשב הנייד שולח Router Solicitation אל ff02::2, הכתובת שכל נתב ברשת מאזין לה, ומצרף את כתובת ה־MAC שלו.","ff02::2 (all routers)":"ff02::2 (כל הנתבים)",Includes:"כולל","ROUTERS?":"נתבים?","Router Answers":"הנתב עונה","Prefix, MTU and DNS in one message":"קידומת, MTU ו־DNS בהודעה אחת","The router answers to ff02::1, every device on the network, with a Router Advertisement: use me as your way out for 30 minutes, here is my MAC address, the MTU is 1500, the network’s prefix is 2001:db8:1234:5678::/64 and you may make your own address in it, and ask 2001:4860:4860::8888 for DNS. Routers also send these on their own every few minutes.":"הנתב עונה אל ff02::1, כל המכשירים ברשת, ב־Router Advertisement: השתמשו בי כיציאה במשך 30 דקות, זו כתובת ה־MAC שלי, ה־MTU הוא 1500, הקידומת של הרשת היא 2001:db8:1234:5678::/64 ומותר לכם ליצור בה כתובת משלכם, ושאלו את 2001:4860:4860::8888 על DNS. נתבים גם שולחים הכרזות כאלה מעצמם כל כמה דקות.",Prefix:"קידומת","Make your own":"ליצור כתובת משלך","Yes (flag A)":"כן (דגל A)",ADVERTISEMENT:"הכרזה","prefix 2001:db8:1234:5678::/64":"קידומת 2001:db8:1234:5678::/64","A Global Address":"כתובת גלובלית","Prefix + interface ID":"קידומת + מזהה ממשק","The laptop joins the prefix and its interface ID into a global address, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, and checks it the same way. Windows also makes a temporary address with a random ID that changes every day, used for outgoing connections so websites can’t follow one device by its address.":"המחשב הנייד מחבר את הקידומת ואת מזהה הממשק שלו לכתובת גלובלית, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, ובודק אותה באותה דרך. Windows גם יוצרת כתובת זמנית עם מזהה אקראי שמשתנה כל יום, שמשמשת לחיבורים יוצאים כדי שאתרים לא יוכלו לעקוב אחרי מכשיר לפי הכתובת שלו.","Also made":"נוצרה גם","A temporary address":"כתובת זמנית","target the global address":"היעד הוא הכתובת הגלובלית","Neighbour Lookup":"חיפוש שכן","Who has this address? (ARP’s job)":"למי יש את הכתובת הזו? (התפקיד של ARP)","A reply from the internet arrives at the router for the laptop’s global address. To deliver it, the router needs the MAC address that goes with it: it sends a Neighbor Solicitation to the address’s solicited-node group, so only devices whose address ends the same way even look. The laptop answers with a Neighbor Advertisement carrying its MAC address.":"תשובה מהאינטרנט מגיעה לנתב עבור הכתובת הגלובלית של המחשב הנייד. כדי למסור אותה, הנתב צריך את כתובת ה־MAC המתאימה: הוא שולח Neighbor Solicitation לקבוצת ה־solicited-node של הכתובת, כך שרק מכשירים שהכתובת שלהם מסתיימת באותו אופן בכלל מסתכלים. המחשב הנייד עונה ב־Neighbor Advertisement שנושא את כתובת ה־MAC שלו.","Asked to":"נשאל אל","Instead of":"במקום","ARP broadcasts to everyone":"שידור ARP לכולם","WHO HAS?":"למי יש?","the global address":"הכתובת הגלובלית","Ready, No DHCP":"מוכן, בלי DHCP","And no NAT either":"וגם בלי NAT","The laptop is on the internet with its own global address, and no NAT changes it on the way: the address a website sees is the laptop’s. The home router’s firewall still turns away connections nobody inside asked for. Networks that want to hand out addresses centrally can use DHCPv6 instead.":"המחשב הנייד מחובר לאינטרנט עם כתובת גלובלית משלו, ואף NAT לא משנה אותה בדרך: הכתובת שאתר רואה היא של המחשב הנייד. חומת האש של הנתב הביתי עדיין דוחה חיבורים שאף אחד מבפנים לא ביקש. רשתות שרוצות לחלק כתובות באופן מרכזי יכולות להשתמש ב־DHCPv6 במקום.","Not needed":"לא נדרש",Incoming:"נכנסים","Blocked by the firewall":"נחסמים בחומת האש","Optional (flags M, O)":"אופציונלי (דגלים M, O)","ONLINE OVER IPv6":"מחובר דרך IPv6","A multicast MAC address: 33:33, then the last four bytes of the IPv6 address.":"כתובת MAC של multicast: 33:33, ואחריה ארבעת הבתים האחרונים של כתובת ה־IPv6.","Version, class, flow":"גרסה, מחלקה, זרימה","IPv6, ordinary traffic, no flow label.":"IPv6, תעבורה רגילה, בלי תווית זרימה.","Payload length":"אורך המטען","What follows this 40-byte header.":"מה שבא אחרי הכותרת הזו בת 40 הבתים.","Next header":"הכותרת הבאה","Hop limit":"מגבלת קפיצות","Neighbour discovery must arrive with 255, proof that no router passed it on: it came from this network.":"גילוי שכנים חייב להגיע עם 255, הוכחה שאף נתב לא העביר אותו: הוא בא מהרשת הזו.","Unspecified: the laptop has no address it may use yet.":"לא מוגדרת: למחשב הנייד עוד אין כתובת שמותר לו להשתמש בה.","Solicited-node multicast: only devices whose address ends in the same 24 bits are listening.":"multicast של solicited-node: מאזינים רק מכשירים שהכתובת שלהם מסתיימת באותם 24 ביט.","Covers the message and both IPv6 addresses.":"מכסה את ההודעה ואת שתי כתובות ה־IPv6.",Target:"יעד","The address the laptop wants to use. If anyone answers, it’s taken.":"הכתובת שהמחשב הנייד רוצה להשתמש בה. אם מישהו עונה, היא תפוסה.","A link-local address: usable only on this network.":"כתובת link-local: מתאימה רק לרשת הזו.","Every router on this network.":"כל נתב ברשת הזו.","Source link-layer address":"כתובת שכבת הקו של המקור","The sender’s MAC address, so nobody has to ask for it.":"כתובת ה־MAC של השולח, כדי שאף אחד לא יצטרך לשאול עליה.","Every device on this network.":"כל מכשיר ברשת הזו.","The hop limit devices here should put on their packets.":"מגבלת הקפיצות שמכשירים כאן צריכים לשים על החבילות שלהם.","M: take addresses from DHCPv6. O: take other settings from DHCPv6. Both off: this advertisement has everything.":"M: לקחת כתובות מ־DHCPv6. O: לקחת הגדרות אחרות מ־DHCPv6. שניהם כבויים: בהכרזה הזו יש הכול.","Router lifetime":"משך חיי הנתב","How long the laptop may use this router as its way out.":"כמה זמן המחשב הנייד רשאי להשתמש בנתב הזה כיציאה.","Reachable time":"זמן נגישות","0 (not set)":"0 (לא מוגדר)","Retransmit timer":"טיימר שידור חוזר","The largest packet this network carries.":"החבילה הגדולה ביותר שהרשת הזו נושאת.","2001:db8:1234:5678::/64, valid 86,400 s, preferred 14,400 s":"2001:db8:1234:5678::/64, תקפה 86,400 s, מועדפת 14,400 s","Flags L and A: addresses in this prefix are on this network, and devices may make their own (SLAAC).":"דגלים L ו־A: הכתובות בקידומת הזו נמצאות ברשת הזו, ומכשירים יכולים ליצור כתובת משלהם (SLAAC).","2001:4860:4860::8888, for 3,600 s":"2001:4860:4860::8888, למשך 3,600 s","Recursive DNS server: which resolver to ask, so no DHCP is needed for that either.":"שרת DNS רקורסיבי: איזה מפענח לשאול, כך שגם לזה לא צריך DHCP.","Whose MAC address is wanted.":"של מי כתובת ה־MAC המבוקשת.","The device this frame is for.":"המכשיר שהמסגרת הזו מיועדת לו.","0x60000000: solicited, override":"0x60000000: מבוקש, דריסה","Solicited: this answers a question. Override: replace any older entry for this address.":"מבוקש: זו תשובה לשאלה. דריסה: להחליף כל רשומה ישנה יותר לכתובת הזו.","Target link-layer address":"כתובת שכבת הקו של היעד","The answer: the MAC address that goes with the target.":"התשובה: כתובת ה־MAC ששייכת ליעד.","Setting the Clock":"כיוון השעון","Computer clocks drift by seconds a week, and a lot depends on them: certificates have dates, logins and payments expire, logs from different machines must line up. NTP sets a clock from a time server over the internet. One small request and answer carry four timestamps, enough to work out how far off the clock is and how long the network took.":"שעוני מחשבים סוטים בשניות בכל שבוע, והרבה תלוי בהם: לתעודות יש תאריכים, התחברויות ותשלומים פגים, ויומנים ממכונות שונות צריכים להתאים. NTP מכוון שעון לפי שרת זמן דרך האינטרנט. בקשה קטנה ותשובתה נושאות ארבע חותמות זמן, מספיק כדי לחשב בכמה השעון סוטה וכמה זמן לקחה הרשת.",Accuracy:"דיוק","A few milliseconds online":"כמה אלפיות שנייה דרך האינטרנט","Clock set":"השעון מכוון","Four timestamps, one answer":"ארבע חותמות זמן, תשובה אחת","One request and one answer gave four timestamps. From them the laptop worked out that its clock was 0.25 s slow and that the network took 24 ms there and back, and it began easing its clock into line. Press REPLAY to watch it again.":"בקשה אחת ותשובה אחת נתנו ארבע חותמות זמן. מהן המחשב הנייד חישב שהשעון שלו מאחר ב־0.25 s ושהרשת לקחה 24 ms הלוך וחזור, והתחיל להתאים את השעון בהדרגה. לחצו על ״שוב״ כדי לצפות שוב.",Offset:"היסט","250.0 ms (slow)":"250.0 ms (מאחר)","Stratum 2":"שכבה 2","Next check":"הבדיקה הבאה","Minutes to days later":"בעוד דקות עד ימים","Clocks Drift":"שעונים סוטים","The laptop’s clock is a little slow":"השעון של המחשב הנייד מאחר מעט","A computer keeps time with a quartz crystal that runs a little fast or slow, so clocks drift apart by seconds a week. This laptop’s clock is a quarter of a second behind. Windows sets it from time.windows.com, whose address it has already looked up by DNS.":"מחשב שומר על הזמן בעזרת גביש קוורץ שרץ מעט מהר או לאט, ולכן שעונים מתרחקים זה מזה בשניות בכל שבוע. השעון של המחשב הנייד הזה מאחר ברבע שנייה. Windows מכוונת אותו לפי time.windows.com, שאת הכתובת שלו היא כבר שאלה ב־DNS.","Laptop clock":"שעון המחשב הנייד","0.25 s slow":"מאחר ב־0.25 s","Time server":"שרת זמן","Why it matters":"למה זה חשוב","Certificates, logins, logs":"תעודות, התחברויות, יומנים","CLOCK 0.250 s SLOW":"השעון מאחר ב־0.250 s","Ask for the Time":"לשאול מה השעה","T1: when the request leaves":"T1: כשהבקשה יוצאת","The laptop sends a 48-byte request to port 123. It writes in the time by its own clock as the request leaves: T1, 09:40:59.750. Everything else is empty.":"המחשב הנייד שולח בקשה של 48 בתים לפורט 123. הוא כותב בה את השעה לפי השעון שלו ברגע שהבקשה יוצאת: T1, 09:40:59.750. כל השאר ריק.","T1 (laptop)":"T1 (מחשב נייד)",Mode:"מצב","3 (client)":"3 (לקוח)","The Answer":"התשובה","T2 and T3 from the server, T4 on arrival":"T2 ו־T3 מהשרת, T4 בהגעה","The server copies T1 back, adds T2, when the request arrived, and T3, when its answer leaves, both by its own accurate clock. When the answer arrives, the laptop notes T4 by its own clock. The server is stratum 2: it sets its clock from a stratum 1 server, which has a GPS receiver or an atomic clock.":"השרת מעתיק את T1 בחזרה ומוסיף את T2, מתי הבקשה הגיעה, ואת T3, מתי התשובה שלו יוצאת, שניהם לפי השעון המדויק שלו. כשהתשובה מגיעה, המחשב הנייד רושם את T4 לפי השעון שלו. השרת הוא בשכבה 2: הוא מכוון את השעון שלו לפי שרת בשכבה 1, שיש לו מקלט GPS או שעון אטומי.","T4 (laptop)":"T4 (מחשב נייד)",Stratum:"שכבה","The Offset":"ההיסט","Four times, two answers":"ארבעה זמנים, שתי תשובות","The time on the network, there and back, is (T4 − T1) − (T3 − T2) = 24.0 ms. The offset assumes the trip takes as long each way: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. The laptop’s clock is a quarter of a second slow. An uneven route (slower one way than the other) would skew the result by up to half the difference.":"הזמן ברשת, הלוך וחזור, הוא (T4 − T1) − (T3 − T2) = 24.0 ms. ההיסט מניח שהדרך לוקחת אותו זמן בכל כיוון: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. השעון של המחשב הנייד מאחר ברבע שנייה. מסלול לא שווה (איטי יותר בכיוון אחד) היה מעוות את התוצאה עד מחצית ההפרש.",Assumes:"מניח","Equal time each way":"אותו זמן בכל כיוון","OFFSET +250.0 ms":"היסט +250.0 ms","Ease It In":"התאמה הדרגתית","No jumps backwards":"בלי קפיצות לאחור","A small error is not fixed in one jump: the clock is run slightly fast until it catches up, so time never stops or goes backwards for running programs. Only a big error is set straight away. As a clock settles, an NTP client asks less often, from every 64 seconds up to every 17 minutes or so; Windows on its own checks time.windows.com far less often, every several hours or less.":"שגיאה קטנה לא מתוקנת בקפיצה אחת: השעון רץ מעט מהר יותר עד שהוא משיג את הזמן, כדי שהזמן לא ייעצר ולא יחזור אחורה לתוכנות שרצות. רק שגיאה גדולה מתוקנת מיד. ככל שהשעון מתייצב, לקוח NTP שואל לעיתים רחוקות יותר, מכל 64 שניות ועד בערך כל 17 דקות; Windows לבדה פונה ל־time.windows.com הרבה פחות, כל כמה שעות או פחות.","Small offsets":"היסטים קטנים","Eased in gradually":"מותאמים בהדרגה","Large offsets":"היסטים גדולים","Set at once":"מכוונים מיד","Asks again":"שואל שוב","Less often as it settles":"פחות ככל שמתייצב","CLOCK IN STEP":"השעון מדויק","Leap, version, mode":"Leap, גרסה, מצב","Mode 3: a client asking for the time.":"מצב 3: לקוח ששואל מה השעה.",Poll:"מרווח תשאול","How often the client means to ask (2 to the power 6 seconds). It grows as the clock settles.":"באיזו תדירות הלקוח מתכוון לשאול (2 בחזקת 6 שניות). הוא גדל ככל שהשעון מתייצב.",Precision:"רזולוציה","How finely this clock can be read.":"באיזו עדינות אפשר לקרוא את השעון הזה.","Root delay":"השהיית שורש","Root dispersion":"פיזור שורש","Reference ID":"מזהה ייחוס","Reference time":"זמן ייחוס","Origin time":"זמן מקור","Receive time":"זמן קבלה","Transmit time":"זמן שליחה","T1: when the request left, by the laptop’s own (wrong) clock.":"T1: מתי הבקשה יצאה, לפי השעון (השגוי) של המחשב הנייד.","Mode 4: an answer from a server.":"מצב 4: תשובה משרת.","Two steps from a reference clock: it follows a stratum 1 server, which has its own GPS or atomic clock.":"שני צעדים משעון ייחוס: הוא עוקב אחרי שרת בשכבה 1, שיש לו GPS או שעון אטומי משלו.","Round-trip time from this server to the reference clock.":"זמן הלוך וחזור מהשרת הזה לשעון הייחוס.","How far off this server could be, at most.":"בכמה השרת הזה יכול לסטות לכל היותר.","192.0.2.123 (its own time source)":"192.0.2.123 (מקור הזמן שלו)","When this server last set its own clock.":"מתי השרת הזה כיוון לאחרונה את השעון שלו.","T1, copied from the request: the client can match the answer to its question.":"T1, מועתק מהבקשה: הלקוח יכול להתאים את התשובה לשאלה שלו.","T2: when the request arrived, by the server’s clock.":"T2: מתי הבקשה הגיעה, לפי שעון השרת.","T3: when this answer left.":"T3: מתי התשובה הזו יצאה.",Private:"פרטי","Plain DNS":"DNS לא מוצפן","DNS inside HTTPS":"DNS בתוך HTTPS","DNS queries inside HTTPS":"שאילתות DNS בתוך HTTPS","Ordinary DNS travels in the clear: anyone on the same Wi-Fi, and your internet provider, can read every name you look up and even change the answers. DNS over HTTPS (DoH) sends the same DNS messages inside an encrypted HTTPS connection to the resolver, so on the way they look like any other web traffic. Browsers and operating systems can turn it on.":"DNS רגיל עובר גלוי: כל מי שנמצא באותה Wi-Fi, וספק האינטרנט שלכם, יכולים לקרוא כל שם שאתם מחפשים ואפילו לשנות את התשובות. DNS over HTTPS (DoH) שולח את אותן הודעות DNS בתוך חיבור HTTPS מוצפן אל המפענח, כך שבדרך הן נראות כמו כל תעבורת אינטרנט. דפדפנים ומערכות הפעלה יכולים להפעיל את זה.","Ordinary DNS messages":"הודעות DNS רגילות",Hides:"מסתיר","Which names you look up":"אילו שמות אתם מחפשים",Similar:"דומה","DNS over TLS (port 853)":"DNS over TLS (פורט 853)","Looked up in private":"חיפוש פרטי","Same question, sealed":"אותה שאלה, חתומה","The plain lookup could be read by anyone on the path. Over HTTPS the same DNS message was sealed inside TLS, readable only by the resolver. The resolver still sees every question, so the trust moves to it, and the site you then visit can still be seen by its address. Press REPLAY to watch it again.":"את החיפוש הלא מוצפן יכול היה לקרוא כל מי שבדרך. דרך HTTPS אותה הודעת DNS נחתמה בתוך TLS, קריאה רק למפענח. המפענח עדיין רואה כל שאלה, כך שהאמון עובר אליו, והאתר שאתם מבקרים בו אחר כך עדיין נראה לפי הכתובת שלו. לחצו על ״שוב״ כדי לצפות שוב.","On the way":"בדרך","Only “HTTPS to dns.google”":"רק ״HTTPS אל dns.google״","The resolver":"המפענח","Still sees every name":"עדיין רואה כל שם","The site’s address you then visit":"כתובת האתר שאתם מבקרים בו אחר כך","Can’t be changed on the way":"אי אפשר לשנות בדרך","Readable by anyone on the way":"קריא לכל מי שבדרך","This is the lookup from the other lessons: a UDP packet to port 53 asking for www.example.com, and the answer. Neither is encrypted, so everyone on the café’s Wi-Fi, and the internet provider, can see which names the laptop looks up, and could even answer with a false address.":"זה החיפוש מהשיעורים האחרים: חבילת UDP לפורט 53 ששואלת על www.example.com, והתשובה. אף אחת מהן לא מוצפנת, ולכן כל מי שב־Wi-Fi של בית הקפה, וספק האינטרנט, יכולים לראות אילו שמות המחשב הנייד מחפש, ואפילו לענות בכתובת מזויפת.","UDP port 53":"פורט UDP 53","Can be changed":"אפשר לשנות","Yes, on the way":"כן, בדרך",readable:"קריא","ANYONE HERE CAN READ IT":"כל אחד כאן יכול לקרוא את זה","An HTTPS Link":"קישור HTTPS","TCP and TLS to dns.google":"TCP ו־TLS אל dns.google","With DNS over HTTPS on, the browser opens an HTTPS connection to the resolver instead: TCP to port 443 and a TLS handshake for dns.google. It keeps this connection open and sends every lookup down it.":"כש־DNS over HTTPS מופעל, הדפדפן פותח במקום זאת חיבור HTTPS אל המפענח: TCP לפורט 443 ולחיצת יד של TLS ל־dns.google. הוא משאיר את החיבור הזה פתוח ושולח דרכו כל חיפוש.","dns.google (8.8.8.8)":"dns.google (8.8.8.8)","443, like any website":"443, כמו כל אתר","Kept open":"נשאר פתוח","For every lookup":"לכל חיפוש","Sealed Question":"שאלה חתומה","A DNS message in an HTTP request":"הודעת DNS בבקשת HTTP","The question is the same DNS message as before. It goes in an HTTP/2 request, GET /dns-query?dns= followed by the message in base64url, asking for an answer in the type application/dns-message. Inside TLS, nobody on the way can read it.":"השאלה היא אותה הודעת DNS כמו קודם. היא נשלחת בבקשת HTTP/2, GET /dns-query?dns= ואחריו ההודעה ב־base64url, ומבקשת תשובה מסוג application/dns-message. בתוך TLS אף אחד בדרך לא יכול לקרוא אותה.",Format:"פורמט","application/dns-message":"application/dns-message","Encrypted (TLS)":"מוצפנת (TLS)","DoH QUERY":"שאילתת DoH","inside: GET /dns-query?dns=…":"בפנים: GET /dns-query?dns=…","Sealed Answer":"תשובה חתומה","The DNS answer in an HTTP response":"תשובת ה־DNS בתשובת HTTP","The resolver answers 200 with a body of type application/dns-message: the same DNS answer as the plain lookup, A 203.0.113.10. Because it arrives through TLS from dns.google, nobody on the way could have changed it.":"המפענח עונה 200 עם גוף מסוג application/dns-message: אותה תשובת DNS כמו בחיפוש הלא מוצפן, A 203.0.113.10. מכיוון שהיא מגיעה דרך TLS מ־dns.google, אף אחד בדרך לא יכול היה לשנות אותה.","200, application/dns-message":"200, application/dns-message","The DNS answer (49 bytes)":"תשובת ה־DNS (49 בתים)",Tampering:"שיבוש","Impossible on the way":"בלתי אפשרי בדרך","DoH ANSWER":"תשובת DoH","inside: A 203.0.113.10":"בפנים: A 203.0.113.10","What Still Shows":"מה עדיין נראה","Hidden on the way, not from the resolver":"מוסתר בדרך, לא מהמפענח","On the way, the lookups now look like any HTTPS traffic to dns.google. But the resolver itself reads every question, so you are trusting it instead of whoever runs your network. And the site you then visit is still seen by its IP address, and by its name in the TLS Client Hello unless it supports Encrypted Client Hello. DNS over TLS does the same job on port 853.":"בדרך, החיפושים נראים עכשיו כמו כל תעבורת HTTPS אל dns.google. אבל המפענח עצמו קורא כל שאלה, כך שאתם סומכים עליו במקום על מי שמפעיל את הרשת שלכם. והאתר שאתם מבקרים בו אחר כך עדיין נראה לפי כתובת ה־IP שלו, ולפי השם שלו ב־TLS Client Hello, אלא אם הוא תומך ב־Encrypted Client Hello. DNS over TLS עושה את אותה עבודה בפורט 853.","Sees every name":"רואה כל שם","Then visible":"נראה אחר כך","The site’s IP, maybe its name":"ה־IP של האתר, אולי גם השם",Alternative:"חלופה","TRUST MOVES TO THE RESOLVER":"האמון עובר למפענח","Application Data (HTTP/2: DNS query)":"Application Data (HTTP/2: שאילתת DNS)","Application Data (HTTP/2: DNS answer)":"Application Data (HTTP/2: תשובת DNS)","HTTP/2: the connection preface and settings, then the request":"HTTP/2: פתיח החיבור וההגדרות, ואז הבקשה","HTTP/2: settings, the response headers, then the DNS answer":"HTTP/2: הגדרות, כותרות התשובה, ואז תשובת ה־DNS","Signed Answers":"תשובות חתומות","Question and answer":"שאלה ותשובה","To the name servers":"אל שרתי השמות","Signed answers":"תשובות חתומות","DNS Security Extensions":"הרחבות אבטחה ל־DNS","Plain DNS answers can be forged: whoever answers first, or sits in the middle, can send a false address. DNSSEC lets a resolver check that an answer really comes from the domain’s owner. Every set of records is signed; each zone’s key is vouched for by its parent, up to the root, whose key resolvers have built in. DNSSEC proves answers are genuine; it doesn’t hide them.":"אפשר לזייף תשובות DNS רגילות: מי שעונה ראשון, או יושב באמצע, יכול לשלוח כתובת מזויפת. DNSSEC מאפשר למפענח לבדוק שתשובה באמת באה מבעל הדומיין. כל קבוצת רשומות חתומה; לכל אזור יש מפתח שאזור האב ערב לו, וכך עד השורש, שהמפתח שלו מובנה במפענחים. DNSSEC מוכיח שתשובות אמיתיות; הוא לא מסתיר אותן.","Adds records":"מוסיף רשומות","Checked by":"נבדק על ידי","Trust anchor":"עוגן אמון","The root’s key (built in)":"המפתח של השורש (מובנה)","Hides queries":"מסתיר שאילתות","No (that’s DoH)":"לא (זה התפקיד של DoH)","Answer checked":"התשובה נבדקה","A chain of signatures to the root":"שרשרת חתימות עד השורש","The resolver followed a chain: the address was signed by example.com’s key, that key by its key-signing key, which .com vouched for with a signed DS record, and .com’s key is vouched for by the root, whose key the resolver has built in. A forged answer would have broken the chain. Press REPLAY to watch it again.":"המפענח עקב אחרי שרשרת: הכתובת נחתמה במפתח של example.com, המפתח הזה במפתח חתימת המפתחות שלו, ש־.com ערב לו ברשומת DS חתומה, ולמפתח של .com ערב השורש, שהמפתח שלו מובנה במפענח. תשובה מזויפת הייתה שוברת את השרשרת. לחצו על ״שוב״ כדי לצפות שוב.","Signatures checked":"חתימות שנבדקו","3 here (plus cached ones)":"3 כאן (ועוד אלה שבמטמון)","The AD flag":"דגל AD","Forged answer":"תשובה מזויפת","Fails the check":"נכשלת בבדיקה","Ask as Usual":"לשאול כרגיל","The laptop’s question doesn’t change":"השאלה של המחשב הנייד לא משתנה","The laptop asks its resolver for www.example.com as always. The checking happens at the resolver, which asks the name servers with the DNSSEC OK flag set: send the signatures too.":"המחשב הנייד שואל את המפענח שלו על www.example.com כמו תמיד. הבדיקה נעשית במפענח, ששואל את שרתי השמות עם דגל DNSSEC OK דלוק: שלחו גם את החתימות.","Checking done by":"הבדיקה נעשית על ידי","The resolver (8.8.8.8)":"המפענח (8.8.8.8)","Resolver sets":"המפענח מדליק","Signed Answer":"תשובה חתומה","An RRSIG comes with the A record":"RRSIG מגיע עם רשומת A","The resolver already knows example.com’s name server from earlier lookups. That server sends the address with an RRSIG record: a signature over the A record, made with the zone’s private key. The RRSIG says which key signed it (key 47362, the zone-signing key) and when the signature expires. To check it the resolver needs that key.":"המפענח כבר מכיר את שרת השמות של example.com מחיפושים קודמים. השרת הזה שולח את הכתובת עם רשומת RRSIG: חתימה על רשומת ה־A, שנעשתה במפתח הפרטי של האזור. ה־RRSIG אומר איזה מפתח חתם (מפתח 47362, מפתח חתימת האזור) ומתי החתימה פגה. כדי לבדוק אותה המפענח צריך את המפתח הזה.","RRSIG by key 47362":"RRSIG של מפתח 47362",Valid:"בתוקף","31 Oct to 21 Nov 2026":"31 באוק׳ עד 21 בנוב׳ 2026","signed by key 47362":"חתום במפתח 47362","The Zone’s Keys":"המפתחות של האזור","DNSKEY records, signed too":"רשומות DNSKEY, גם הן חתומות","The resolver asks for example.com’s keys. There are two: the zone-signing key (flags 256) that signed the A record, and the key-signing key (flags 257), which signs only the set of keys. With them the resolver checks both signatures. But who says these keys belong to example.com?":"המפענח מבקש את המפתחות של example.com. יש שניים: מפתח חתימת האזור (דגלים 256) שחתם על רשומת ה־A, ומפתח חתימת המפתחות (דגלים 257), שחותם רק על קבוצת המפתחות. בעזרתם המפענח בודק את שתי החתימות. אבל מי אמר שהמפתחות האלה שייכים ל־example.com?","47362, zone-signing (256)":"47362, חתימת אזור (256)","61845, key-signing (257)":"61845, חתימת מפתחות (257)","Keys signed by":"המפתחות חתומים על ידי","The key-signing key":"מפתח חתימת המפתחות","two keys":"שני מפתחות","signed by key 61845":"חתום במפתח 61845","Vouched by .com":".com ערב לו","The parent’s DS record":"רשומת ה־DS של אזור האב","The parent zone answers that. The .com servers hold a DS record for example.com: a hash of its key-signing key, signed with .com’s own key. If the hash matches key 61845, the keys are example.com’s, as far as .com is concerned.":"על זה עונה אזור האב. שרתי .com מחזיקים רשומת DS ל־example.com: גיבוב של מפתח חתימת המפתחות שלו, חתום במפתח של .com עצמו. אם הגיבוב תואם למפתח 61845, המפתחות שייכים ל־example.com, מבחינת .com.","Hash of key 61845":"גיבוב של מפתח 61845","Signed by":"חתום על ידי",".com (key 19718)":".com (מפתח 19718)",Matches:"תואם ל־","hash of key 61845":"גיבוב של מפתח 61845","signed by .com":"חתום על ידי .com","Up to the Root":"עד השורש","Where the chain ends":"איפה השרשרת נגמרת","The same goes on above: .com’s keys are vouched for by a DS record in the root zone, signed by the root’s key, and that key is built into every validating resolver: the trust anchor. The resolver had those links cached, so the chain is complete: root → .com → example.com → the address.":"אותו דבר ממשיך למעלה: למפתחות של .com ערבה רשומת DS באזור השורש, חתומה במפתח של השורש, והמפתח הזה מובנה בכל מפענח שמאמת: זה עוגן האמון. החוליות האלה היו במטמון של המפענח, כך שהשרשרת שלמה: שורש → .com → example.com → הכתובת.",".com’s key":"המפתח של .com","Vouched for by the root":"השורש ערב לו","Root’s key":"המפתח של השורש","Built in (trust anchor)":"מובנה (עוגן אמון)","Root → .com → example.com":"שורש → .com → example.com","CHAIN OF TRUST CHECKED":"שרשרת האמון נבדקה","A Checked Answer":"תשובה שנבדקה","With the AD flag":"עם דגל AD","The resolver answers the laptop with the address and the AD flag: authenticated data. Had any signature failed, the laptop would have got an error (SERVFAIL) instead of a forged address. DNSSEC doesn’t hide the question or the answer; for that there is DNS over HTTPS.":"המפענח עונה למחשב הנייד עם הכתובת ועם דגל AD: נתונים מאומתים. אילו חתימה כלשהי נכשלה, המחשב הנייד היה מקבל שגיאה (SERVFAIL) במקום כתובת מזויפת. DNSSEC לא מסתיר את השאלה או את התשובה; בשביל זה יש DNS over HTTPS.",Flag:"דגל","AD (authenticated data)":"AD (נתונים מאומתים)","Bad signature":"חתימה פגומה","SERVFAIL, no address":"SERVFAIL, בלי כתובת","AD: checked":"AD: נבדקה","UDP size 1232, DNSSEC OK = 1":"גודל UDP 1232, DNSSEC OK = 1","Says how big a UDP answer can be, and DNSSEC OK: send the signatures too.":"אומר כמה גדולה יכולה להיות תשובת UDP, ו־DNSSEC OK: שלחו גם את החתימות.","www.example.com RRSIG A, signed by example.com key 47362, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"www.example.com RRSIG A, חתום במפתח 47362 של example.com, בתוקף 2026-10-31 עד 2026-11-21 (TTL 3,600 s)","A signature over the records above it, made with the zone’s private key.":"חתימה על הרשומות שמעליה, שנעשתה במפתח הפרטי של האזור.","example.com, type DNSKEY, class IN":"example.com, סוג DNSKEY, מחלקה IN","example.com DNSKEY 256 (zone-signing key 47362), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 256 (מפתח חתימת אזור 47362), ECDSA P-256 (TTL 3,600 s)","One of the zone’s public keys; whoever checks a signature needs it.":"אחד המפתחות הציבוריים של האזור; מי שבודק חתימה צריך אותו.","example.com DNSKEY 257 (key-signing key 61845), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 257 (מפתח חתימת מפתחות 61845), ECDSA P-256 (TTL 3,600 s)","example.com RRSIG DNSKEY, signed by example.com key 61845, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"example.com RRSIG DNSKEY, חתום במפתח 61845 של example.com, בתוקף 2026-10-31 עד 2026-11-21 (TTL 3,600 s)","example.com, type DS, class IN":"example.com, סוג DS, מחלקה IN","example.com DS key 61845, SHA-256 digest (TTL 86,400 s)":"example.com DS מפתח 61845, תקציר SHA-256 (TTL 86,400 s)","A hash of the child zone’s key-signing key, kept and signed by the parent zone.":"גיבוב של מפתח חתימת המפתחות של אזור הבן, שאזור האב שומר וחותם.","example.com RRSIG DS, signed by com key 19718, valid 2026-10-31 to 2026-11-21 (TTL 86,400 s)":"example.com RRSIG DS, חתום במפתח 19718 של com, בתוקף 2026-10-31 עד 2026-11-21 (TTL 86,400 s)","0x81a0: response, RD (recursion desired), RA (recursion available), AD (authenticated data)":"0x81a0: תשובה, RD (רקורסיה רצויה), RA (רקורסיה זמינה), AD (נתונים מאומתים)","Wi-Fi Logins":"התחברות ל־Wi-Fi","EAP over Wi-Fi":"EAP דרך Wi-Fi","RADIUS Server":"שרת RADIUS","RADIUS and 802.1X (Enterprise Wi-Fi)":"RADIUS ו־802.1X (Wi-Fi ארגוני)","At home everyone shares one Wi-Fi password. Offices, universities and eduroam use WPA2- or WPA3-Enterprise instead: each person or device logs in with its own account or certificate, checked by a RADIUS server. The access point knows no passwords. It passes the login, a series of EAP messages, between the laptop and the server, and lets the laptop in only when the server says yes.":"בבית כולם חולקים סיסמת Wi-Fi אחת. משרדים, אוניברסיטאות ו־eduroam משתמשים במקום זאת ב־WPA2- או WPA3-Enterprise: כל אדם או מכשיר מתחבר עם חשבון או תעודה משלו, ששרת RADIUS בודק. נקודת הגישה לא מכירה אף סיסמה. היא מעבירה את ההתחברות, סדרה של הודעות EAP, בין המחשב הנייד לשרת, ומכניסה את המחשב הנייד רק כשהשרת אומר כן.","EAP (here EAP-TLS)":"EAP (כאן EAP-TLS)",Keys:"מפתחות","Different for every login":"שונים בכל התחברות","Let in":"הוכנס","Its own login, its own keys":"התחברות משלו, מפתחות משלו","The laptop proved who it was with its certificate. The RADIUS server checked it and told the access point to let it in, on VLAN 20, with a key for this login alone. The access point never saw a password: it only passed the messages on. Press REPLAY to watch it again.":"המחשב הנייד הוכיח מי הוא בעזרת התעודה שלו. שרת ה־RADIUS בדק אותה ואמר לנקודת הגישה להכניס אותו, ל־VLAN 20, עם מפתח להתחברות הזו בלבד. נקודת הגישה לא ראתה אף פעם סיסמה: היא רק העבירה את ההודעות. לחצו על ״שוב״ כדי לצפות שוב.","EAP-TLS (certificates)":"EAP-TLS (תעודות)","17, then the 4-way handshake":"17, ואז לחיצת היד בארבעה שלבים","20 (staff)":"20 (צוות)","A user leaves":"מישהו עוזב","Disable one account":"משביתים חשבון אחד","Who Are You?":"מי אתם?","The access point asks for an identity":"נקודת הגישה מבקשת זהות","The laptop has joined “Office”, a WPA2-Enterprise network, but until it has logged in the access point passes on nothing except login messages. It asks who the laptop is with an EAP Identity request, and the laptop answers alex@example.org. The access point knows no accounts: it will pass the answer on to the RADIUS server.":"המחשב הנייד הצטרף ל־״Office״, רשת WPA2-Enterprise, אבל עד שהוא מתחבר נקודת הגישה לא מעבירה שום דבר מלבד הודעות התחברות. היא שואלת מי המחשב הנייד בבקשת EAP Identity, והמחשב הנייד עונה alex@example.org. נקודת הגישה לא מכירה אף חשבון: היא תעביר את התשובה לשרת ה־RADIUS.","Before login":"לפני ההתחברות","Only EAP gets through":"רק EAP עובר","IDENTITY?":"זהות?","EAP Identity request":"בקשת EAP Identity",IDENTITY:"זהות","Ask RADIUS":"לשאול את RADIUS","The login goes to the server":"ההתחברות עוברת לשרת","The access point copies the EAP message into a RADIUS Access-Request and sends it to the RADIUS server on UDP port 1812, with the laptop’s MAC address and the network’s name. A secret that only the two of them share protects every packet. The server answers with an Access-Challenge: the next message for the laptop, which is “start EAP-TLS”.":"נקודת הגישה מעתיקה את הודעת ה־EAP לתוך RADIUS Access-Request ושולחת אותו לשרת ה־RADIUS בפורט UDP 1812, עם כתובת ה־MAC של המחשב הנייד ושם הרשת. סוד ששניהם בלבד חולקים מגן על כל חבילה. השרת עונה ב־Access-Challenge: ההודעה הבאה למחשב הנייד, שהיא ״התחל EAP-TLS״.","RADIUS server, UDP 1812":"שרת RADIUS, UDP 1812","A shared secret":"סוד משותף","from the access point":"מנקודת הגישה","EAP-TLS start":"התחלת EAP-TLS","TLS START":"התחלת TLS","TLS Inside EAP":"TLS בתוך EAP","The server proves who it is":"השרת מוכיח מי הוא","The laptop and the server now run a TLS 1.3 handshake inside EAP; the access point repacks each message, EAPOL over the air and RADIUS on the wire. The server sends its certificate and asks for the laptop’s. The laptop checks that it was issued by the company’s own certificate authority to radius.example.org. That check is what stops a fake access point from catching the login.":"המחשב הנייד והשרת מבצעים עכשיו לחיצת יד של TLS 1.3 בתוך EAP; נקודת הגישה אורזת מחדש כל הודעה, EAPOL באוויר ו־RADIUS בכבל. השרת שולח את התעודה שלו ומבקש את זו של המחשב הנייד. המחשב הנייד בודק שהיא הונפקה על ידי רשות התעודות של החברה עצמה ל־radius.example.org. הבדיקה הזו היא שמונעת מנקודת גישה מזויפת ללכוד את ההתחברות.","TLS 1.3, inside EAP":"TLS 1.3, בתוך EAP","Its certificate":"התעודה שלו","Laptop checks":"המחשב הנייד בודק","Issuer and name":"מנפיק ושם","TLS inside EAP":"TLS בתוך EAP","certificate (encrypted)":"תעודה (מוצפנת)","Laptop’s Proof":"ההוכחה של המחשב הנייד","Its own certificate":"התעודה שלו עצמו","The laptop answers with its own certificate, which the company issued for this user, and a signature made with its private key; the key never leaves the laptop. No password is involved. The server checks the certificate and the signature and looks up the account. Many networks, eduroam among them, use a password instead, sent inside the TLS tunnel (PEAP or EAP-TTLS).":"המחשב הנייד עונה בתעודה שלו, שהחברה הנפיקה למשתמש הזה, ובחתימה שנעשתה במפתח הפרטי שלו; המפתח אף פעם לא יוצא מהמחשב הנייד. אין שום סיסמה. השרת בודק את התעודה ואת החתימה ומחפש את החשבון. רשתות רבות, ביניהן eduroam, משתמשות במקום זאת בסיסמה, שנשלחת בתוך מנהרת ה־TLS (PEAP או EAP-TTLS).","Its certificate, a signature":"התעודה שלו, חתימה","None with EAP-TLS":"אין ב־EAP-TLS","Or instead":"או במקום זה","PEAP: a password in TLS":"PEAP: סיסמה בתוך TLS",CERTIFICATE:"תעודה","laptop’s certificate":"התעודה של המחשב הנייד","Handshake Done":"לחיצת היד הסתיימה","Nothing more to send":"אין יותר מה לשלוח","With TLS 1.3 the server then sends one tiny encrypted message, a single zero byte, to say the handshake is over, and the laptop answers with an empty EAP message. Both ends now hold the same 64 bytes of key material, worked out during the handshake. Nobody on the way has seen it, not even the access point.":"ב־TLS 1.3 השרת שולח אז הודעה מוצפנת זעירה, בית אפס יחיד, כדי לומר שלחיצת היד הסתיימה, והמחשב הנייד עונה בהודעת EAP ריקה. לשני הצדדים יש עכשיו אותם 64 בתים של חומר מפתח, שחושבו במהלך לחיצת היד. אף אחד בדרך לא ראה אותו, אפילו לא נקודת הגישה.","Server sends":"השרת שולח","One encrypted 0 byte":"בית 0 מוצפן אחד","An empty EAP-TLS reply":"תשובת EAP-TLS ריקה","Both hold":"לשניהם יש","64 bytes of key material":"64 בתים של חומר מפתח","handshake over":"לחיצת היד הסתיימה","one encrypted byte":"בית מוצפן אחד",EMPTY:"ריק","nothing more":"אין יותר","empty EAP-TLS":"EAP-TLS ריק","And a key for the access point":"ומפתח לנקודת הגישה","The server answers Access-Accept. Inside are EAP Success for the laptop; the first 32 bytes of the key material for the access point, encrypted with the shared secret (MS-MPPE-Recv-Key); and VLAN 20, so this user lands on the staff network. The same access point could put another user on another VLAN.":"השרת עונה Access-Accept. בפנים יש EAP Success למחשב הנייד; את 32 הבתים הראשונים של חומר המפתח לנקודת הגישה, מוצפנים בסוד המשותף (MS-MPPE-Recv-Key); ו־VLAN 20, כדי שהמשתמש הזה יגיע לרשת הצוות. אותה נקודת גישה יכולה לשים משתמש אחר ב־VLAN אחר.","AP gets":"נקודת הגישה מקבלת","The key (MS-MPPE-Recv-Key)":"המפתח (MS-MPPE-Recv-Key)","key, VLAN 20":"מפתח, VLAN 20","4-Way Handshake":"לחיצת יד בארבעה שלבים","As at home, from a different key":"כמו בבית, ממפתח אחר","The access point and the laptop now hold the same 32-byte key, the PMK. What follows is the 4-way handshake from the Wi-Fi lesson; only the PMK’s origin differs. At home it comes from the shared password, here from this one login, so every user gets different keys.":"לנקודת הגישה ולמחשב הנייד יש עכשיו אותו מפתח של 32 בתים, ה־PMK. מה שבא אחר כך הוא לחיצת היד בארבעה שלבים משיעור ה־Wi-Fi; רק המקור של ה־PMK שונה. בבית הוא בא מהסיסמה המשותפת, כאן מההתחברות הזו בלבד, כך שכל משתמש מקבל מפתחות שונים.","PMK from":"PMK מתוך","This login":"ההתחברות הזו","At home":"בבית","From the shared password":"מהסיסמה המשותפת","Encrypted data (CCMP)":"נתונים מוצפנים (CCMP)","group key, MIC":"מפתח קבוצה, MIC","Why Enterprise":"למה Enterprise","One account per person":"חשבון אחד לכל אדם","When someone leaves, their account is disabled and nobody else changes a password. Every login gets its own keys, so users can’t read each other’s traffic, and the RADIUS server records who connected and when. eduroam works the same way: a visitor’s login for user@their-university is passed from RADIUS server to RADIUS server until it reaches their own university.":"כשמישהו עוזב, משביתים את החשבון שלו ואף אחד אחר לא צריך להחליף סיסמה. כל התחברות מקבלת מפתחות משלה, כך שמשתמשים לא יכולים לקרוא זה את התעבורה של זה, ושרת ה־RADIUS רושם מי התחבר ומתי. eduroam עובד באותה דרך: ההתחברות של אורח בתור user@their-university מועברת משרת RADIUS לשרת RADIUS עד שהיא מגיעה לאוניברסיטה שלו.","Different for every user":"שונים לכל משתמש",eduroam:"eduroam","Login passed home":"ההתחברות מועברת הביתה","ONE ACCOUNT PER PERSON":"חשבון אחד לכל אדם","Access-Challenge id=82: Server Hello, certificate":"Access-Challenge id=82: Server Hello, תעודה","Request, TLS EAP: Server Hello, encrypted handshake":"Request, TLS EAP: Server Hello, לחיצת יד מוצפנת","Response, TLS EAP: encrypted handshake":"Response, TLS EAP: לחיצת יד מוצפנת","Access-Request id=83: encrypted handshake":"Access-Request id=83: לחיצת יד מוצפנת","0 (EAP packet)":"0 (חבילת EAP)","Carries an EAP message. The access point copies it into a RADIUS packet for the server, and back.":"נושא הודעת EAP. נקודת הגישה מעתיקה אותה לחבילת RADIUS בשביל השרת, ובחזרה.","A response carries the same number as the request it answers.":"תשובה נושאת את אותו מספר כמו הבקשה שהיא עונה לה.","Who are you?":"מי אתם?","Who is logging in. The realm after the @ tells the RADIUS server (or the servers that pass requests on) where the account lives.":"מי מתחבר. ה־realm שאחרי ה־@ אומר לשרת ה־RADIUS (או לשרתים שמעבירים בקשות) איפה החשבון נמצא.","Seen on the office network":"נראה ברשת המשרד","The server. It is on the same network, so the frame goes straight to it, not through the router.":"השרת. הוא באותה רשת, כך שהמסגרת הולכת ישר אליו, לא דרך הנתב.","The access point’s wired port.":"הפורט החוטי של נקודת הגישה.","Should this device be let in?":"להכניס את המכשיר הזה?","A reply carries the number of the request it answers.":"תשובה נושאת את המספר של הבקשה שהיא עונה לה.",Authenticator:"מאמת","Random, new in every request.":"אקראי, חדש בכל בקשה.",Attributes:"תכונות","An HMAC-MD5 of the whole packet, keyed with the shared secret. Every packet that carries EAP must have one; since the Blast-RADIUS attack of 2024, it goes first.":"HMAC-MD5 של כל החבילה, עם הסוד המשותף כמפתח. כל חבילה שנושאת EAP חייבת לכלול אחד; מאז מתקפת Blast-RADIUS ב־2024 הוא בא ראשון.","The identity the laptop gave.":"הזהות שהמחשב הנייד מסר.","The access point asking.":"נקודת הגישה ששואלת.","The access point’s MAC address and the network’s name.":"כתובת ה־MAC של נקודת הגישה ושם הרשת.","The laptop’s MAC address.":"כתובת ה־MAC של המחשב הנייד.","Keep each EAP message small enough for one frame.":"לשמור כל הודעת EAP קטנה מספיק למסגרת אחת.","The EAP packet, passed on unchanged.":"חבילת ה־EAP, מועברת ללא שינוי.","The server’s network card.":"כרטיס הרשת של השרת.","Not yet: here is the next message for the device.":"עוד לא: הנה ההודעה הבאה למכשיר.","A hash of this reply, the request’s authenticator and the shared secret: only the real server could have made it.":"גיבוב של התשובה הזו, של המאמת של הבקשה ושל הסוד המשותף: רק השרת האמיתי יכול היה ליצור אותו.","A TLS handshake, carried inside EAP.":"לחיצת יד של TLS, שעוברת בתוך EAP.","0x20 (start)":"0x20 (התחלה)","Start: the server is ready for the laptop’s Client Hello.":"התחלה: השרת מוכן ל־Client Hello של המחשב הנייד.","The server’s bookmark for this login: the access point sends it back with the next request.":"הסימנייה של השרת להתחברות הזו: נקודת הגישה שולחת אותה בחזרה עם הבקשה הבאה.","0x80 (length included)":"0x80 (כולל אורך)","TLS length":"אורך TLS","Longer TLS messages are split into pieces of about 1,000 bytes, each one acknowledged.":"הודעות TLS ארוכות יותר מחולקות לחלקים של כ־1,000 בתים, וכל אחד מקבל אישור.","TLS records":"רשומות TLS","The same TLS records as over TCP, only carried in EAP.":"אותן רשומות TLS כמו מעל TCP, רק שהן עוברות ב־EAP.","Client Hello: TLS 1.3, the laptop’s key share":"Client Hello: TLS 1.3, חלק המפתח של המחשב הנייד","The EAP packet (1,008 bytes), split over 4 attributes of up to 253 bytes.":"חבילת ה־EAP (1,008 בתים), מפוצלת ל־4 תכונות של עד 253 בתים.","EAP-Message, continued":"EAP-Message, המשך","TLS records, continued":"רשומות TLS, המשך","Server Hello: TLS 1.3, the server’s key share":"Server Hello: TLS 1.3, חלק המפתח של השרת","Encrypted: certificate for radius.example.org, a request for the laptop’s certificate, signature, Finished":"מוצפן: תעודה ל־radius.example.org, בקשה לתעודה של המחשב הנייד, חתימה, Finished","Encrypted: the laptop’s certificate (for alex@example.org), its signature, Finished":"מוצפן: התעודה של המחשב הנייד (ל־alex@example.org), החתימה שלו, Finished","The EAP packet (822 bytes), split over 4 attributes of up to 253 bytes.":"חבילת ה־EAP (822 בתים), מפוצלת ל־4 תכונות של עד 253 בתים.","Encrypted: one 0 byte, the “commitment message”: no more handshake messages":"מוצפן: בית 0 אחד, ״הודעת ההתחייבות״: אין יותר הודעות לחיצת יד","0x00 (no data)":"0x00 (בלי נתונים)","Nothing to send: an empty answer that keeps the conversation going.":"אין מה לשלוח: תשובה ריקה שמשאירה את השיחה בתנועה.","Yes: let it in.":"כן: להכניס.","Put this device on VLAN 20, the staff network.":"לשים את המכשיר הזה ב־VLAN 20, רשת הצוות.","The first 32 bytes of the key material that both ends of the TLS handshake worked out. The access point uses it as the PMK, the starting key for the 4-way handshake.":"32 הבתים הראשונים של חומר המפתח ששני הצדדים של לחיצת היד של TLS חישבו. נקודת הגישה משתמשת בהם כ־PMK, מפתח ההתחלה של לחיצת היד בארבעה שלבים.","Salt, encrypted key":"מלח, מפתח מוצפן","Encrypted with the shared secret, so only the access point can read the key.":"מוצפן בסוד המשותף, כך שרק נקודת הגישה יכולה לקרוא את המפתח.","The next 32 bytes of the key material. Wi-Fi doesn’t need them.":"32 הבתים הבאים של חומר המפתח. ה־Wi-Fi לא צריך אותם.","The RADIUS server accepted the login.":"שרת ה־RADIUS קיבל את ההתחברות.","1: 802.1X (logins checked by a RADIUS server)":"1: 802.1X (התחברויות ששרת RADIUS בודק)","Shared Folders":"תיקיות משותפות",Responses:"תשובות","nas (File Server)":"nas (שרת קבצים)","Server Message Block (SMB 3)":"Server Message Block (SMB 3)","SMB is how Windows shares files and printers: \\\\server\\share in File Explorer, a mapped network drive, a NAS at home. macOS and Linux speak it too. Over one TCP connection to port 445 the client agrees on a version, logs in and connects to a share, then opens, reads, writes and closes files with numbered requests.":"SMB הוא הדרך שבה Windows משתפת קבצים ומדפסות: \\\\server\\share בסייר הקבצים, כונן רשת ממופה, NAS בבית. גם macOS ו־Linux מדברים אותו. דרך חיבור TCP אחד לפורט 445 הלקוח מסכים על גרסה, מתחבר ומתחבר לשיתוף, ואז פותח, קורא, כותב וסוגר קבצים בבקשות ממוספרות.","TCP 445":"TCP 445","NTLM or Kerberos":"NTLM או Kerberos",Protection:"הגנה","Signing, optional encryption":"חתימה, הצפנה אופציונלית","File read":"הקובץ נקרא","Seven requests, one connection":"שבע בקשות, חיבור אחד","Over one TCP connection the laptop agreed on SMB 3.1.1, logged in with NTLM without sending its password, connected to the share and read a 240 KB file with a single request. Every message after the login was signed. Press REPLAY to watch it again.":"דרך חיבור TCP אחד המחשב הנייד הסכים על SMB 3.1.1, התחבר עם NTLM בלי לשלוח את הסיסמה, התחבר לשיתוף וקרא קובץ של 240 KB בבקשה אחת. כל הודעה אחרי ההתחברות הייתה חתומה. לחצו על ״שוב״ כדי לצפות שוב.","7 on one connection":"7 בחיבור אחד","NTLMv2, no password sent":"NTLMv2, בלי לשלוח סיסמה","240 KB in 169 segments":"240 KB ב־169 מקטעים",Signed:"חתומות","Every message after login":"כל הודעה אחרי ההתחברות","Port 445":"פורט 445","A TCP connection to the NAS":"חיבור TCP ל־NAS","The laptop opens \\\\nas\\Documents, a shared folder on the NAS. It finds nas’s address with a local name lookup and opens a TCP connection to port 445. The packets pass through the home router to the NAS and never leave the home network.":"המחשב הנייד פותח את \\\\nas\\Documents, תיקייה משותפת ב־NAS. הוא מוצא את הכתובת של nas בחיפוש שם מקומי ופותח חיבור TCP לפורט 445. החבילות עוברות דרך הנתב הביתי אל ה־NAS ואף פעם לא יוצאות מהרשת הביתית.","nas, 192.168.1.20":"nas, 192.168.1.20",Stays:"נשאר","On the home network":"ברשת הביתית",Negotiate:"משא ומתן","Agree on a version":"להסכים על גרסה","The laptop lists every SMB version it speaks, from 2.0.2 to 3.1.1, and says it requires signing. The NAS picks 3.1.1, the newest. Both sides keep a SHA-512 hash of everything exchanged from here until the login is done. It goes into the keys, so if anyone changed these messages on the way, to force an older version for instance, the login would fail.":"המחשב הנייד מונה כל גרסת SMB שהוא מדבר, מ־2.0.2 עד 3.1.1, ואומר שהוא דורש חתימה. ה־NAS בוחר ב־3.1.1, החדשה ביותר. שני הצדדים שומרים גיבוב SHA-512 של כל מה שמוחלף מכאן ועד סוף ההתחברות. הוא נכנס למפתחות, כך שאם מישהו ישנה את ההודעות האלה בדרך, למשל כדי לכפות גרסה ישנה יותר, ההתחברות תיכשל.",Chosen:"נבחר","Tamper check":"בדיקת שיבוש","SHA-512 of the exchange":"SHA-512 של החילוף","signing required":"חתימה נדרשת","NTLM Challenge":"אתגר NTLM","The NAS sends a random number":"ה־NAS שולח מספר אקראי","A home NAS has no domain, so there is no Kerberos: the laptop logs in with NTLM. Its first SESSION_SETUP says it wants to log in, and the NAS answers “more processing required” with a challenge of 8 random bytes. It also gives this login a session ID.":"ל־NAS ביתי אין דומיין, ולכן אין Kerberos: המחשב הנייד מתחבר עם NTLM. ה־SESSION_SETUP הראשון שלו אומר שהוא רוצה להתחבר, וה־NAS עונה ״נדרש עיבוד נוסף״ עם אתגר של 8 בתים אקראיים. הוא גם נותן להתחברות הזו מזהה סשן.","NTLMv2 (in a domain: Kerberos)":"NTLMv2 (בדומיין: Kerberos)",Challenge:"אתגר","More processing required":"נדרש עיבוד נוסף","NTLM: let me log in":"NTLM: תן לי להתחבר","a session ID":"מזהה סשן","NTLM Response":"תשובת NTLM","Proof, not the password":"הוכחה, לא הסיסמה","The laptop answers with the user name, alex, and an NTLMv2 response: an HMAC of the challenge and a few other values, keyed with a hash of the password. The NAS has the same hash and works out the same value. The password itself never crosses the network, and both sides now have a session key to sign messages with.":"המחשב הנייד עונה עם שם המשתמש, alex, ותשובת NTLMv2: HMAC של האתגר ועוד כמה ערכים, עם גיבוב של הסיסמה כמפתח. ל־NAS יש אותו גיבוב והוא מחשב אותו ערך. הסיסמה עצמה אף פעם לא עוברת ברשת, ולשני הצדדים יש עכשיו מפתח סשן לחתימת הודעות.",User:"משתמש",alex:"alex",Sends:"שולח","An HMAC of the challenge":"HMAC של האתגר","Never sent":"אף פעם לא נשלחת","user alex":"משתמש alex","NTLMv2 response":"תשובת NTLMv2","LOGGED IN":"מחובר",signed:"חתום","Connect a Share":"התחברות לשיתוף","\\\\nas\\Documents":"\\\\nas\\Documents","TREE_CONNECT asks for the share by its full name, \\\\nas\\Documents. The answer gives it a tree ID and says what this user may do there. Every message is now signed: each carries a tag over the whole message, made with a key from the login, so a changed or forged message would be caught.":"TREE_CONNECT מבקש את השיתוף בשמו המלא, \\\\nas\\Documents. התשובה נותנת לו מזהה עץ ואומרת מה המשתמש הזה רשאי לעשות שם. מעכשיו כל הודעה חתומה: כל אחת נושאת תג על כל ההודעה, שנעשה במפתח מההתחברות, כך שהודעה ששונתה או זויפה תיתפס.",Share:"שיתוף","Every message":"כל הודעה","Signed (AES-GMAC)":"חתומה (AES-GMAC)","tree ID 0x2a51":"מזהה עץ 0x2a51","Open the File":"פתיחת הקובץ","With CREATE":"עם CREATE","SMB opens files with CREATE, which can also make new ones. This one opens report.pdf to read it, and fails if it doesn’t exist. The answer gives the file’s size and dates, and a file ID that the read and the close will use.":"SMB פותח קבצים עם CREATE, שיכול גם ליצור קבצים חדשים. הבקשה הזו פותחת את report.pdf לקריאה, ונכשלת אם הוא לא קיים. התשובה נותנת את הגודל ואת התאריכים של הקובץ, ומזהה קובץ שהקריאה והסגירה ישתמשו בו.",Handle:"ידית","A 16-byte file ID":"מזהה קובץ של 16 בתים","open to read":"פתיחה לקריאה","file ID":"מזהה קובץ","Read It":"קריאה","The whole file in one request":"כל הקובץ בבקשה אחת","One READ asks for the whole file, 245,760 bytes from offset 0. It costs 4 credits, one for every 64 KB. The answer is 80 bytes of headers and then the file, in 169 TCP segments. A bigger file is read with several requests, many on their way at once, as far as the credits allow.":"READ אחד מבקש את כל הקובץ, 245,760 בתים מהיסט 0. הוא עולה 4 קרדיטים, אחד לכל 64 KB. התשובה היא 80 בתים של כותרות ואחריהם הקובץ, ב־169 מקטעי TCP. קובץ גדול יותר נקרא בכמה בקשות, רבות מהן בדרך בבת אחת, ככל שהקרדיטים מרשים.","245,760 bytes from 0":"245,760 בתים מ־0",Credits:"קרדיטים","4 (one per 64 KB)":"4 (אחד לכל 64 KB)","Arrives in":"מגיע ב־","from offset 0":"מהיסט 0","Close the File":"סגירת הקובץ","And keep 445 at home":"ולהשאיר את 445 בבית","CLOSE hands the file ID back; the connection stays open for the next file. SMB 3 can also encrypt every message with AES-GCM, for one share or a whole server. Here only signing protects the messages, so anyone on the network could read the file as it passed. Port 445 should never be reachable from the internet: the WannaCry worm (2017) spread through a flaw in the old SMB1.":"CLOSE מחזיר את מזהה הקובץ; החיבור נשאר פתוח לקובץ הבא. SMB 3 יכול גם להצפין כל הודעה ב־AES-GCM, לשיתוף אחד או לשרת שלם. כאן רק החתימה מגינה על ההודעות, כך שכל מי שברשת יכול היה לקרוא את הקובץ כשעבר. פורט 445 לא אמור להיות נגיש מהאינטרנט לעולם: התולעת WannaCry (2017) התפשטה דרך פרצה ב־SMB1 הישן.","SMB 3: AES-GCM, optional":"SMB 3: AES-GCM, אופציונלי","Switched off: old, unsafe":"כבוי: ישן, לא בטוח","Never open to the internet":"לעולם לא פתוח לאינטרנט",done:"סיום","KEEP PORT 445 OFF THE INTERNET":"להרחיק את פורט 445 מהאינטרנט","On port 445 every SMB message starts with its length, a leftover from NetBIOS.":"בפורט 445 כל הודעת SMB מתחילה באורך שלה, שארית מ־NetBIOS.",'0xFE "SMB" (SMB2 or 3)':'0xFE "SMB" (SMB2 או 3)','SMB1 messages started 0xFF "SMB". SMB1 is switched off in Windows today.':'הודעות SMB1 התחילו ב־0xFF "SMB". היום SMB1 כבוי ב־Windows.',"Header size":"גודל הכותרת","Credit charge":"עלות בקרדיטים","Channel sequence":"רצף ערוץ","Credits asked for":"קרדיטים מבוקשים","Credits limit how many requests the laptop may have waiting at once. The server hands them out.":"קרדיטים מגבילים כמה בקשות המחשב הנייד יכול להחזיק בהמתנה בבת אחת. השרת מחלק אותם.","Next command":"הפקודה הבאה","0 (none chained)":"0 (אין שרשור)","Counts up with each request; the response carries the same number.":"עולה בכל בקשה; התשובה נושאת את אותו מספר.","0 (no share yet)":"0 (עדיין אין שיתוף)","Session ID":"מזהה סשן","0 (not logged in yet)":"0 (עדיין לא מחובר)","zeros (not signed)":"אפסים (לא חתום)","Structure size":"גודל המבנה","Dialect count":"מספר דיאלקטים","Security mode":"מצב אבטחה","0x0002 (signing required)":"0x0002 (חתימה נדרשת)","Recent versions of Windows 11 require signing by default.":"גרסאות עדכניות של Windows 11 דורשות חתימה כברירת מחדל.","DFS, leases, large reads and writes, multichannel, persistent handles, directory leases, encryption.":"DFS, חכירות, קריאות וכתיבות גדולות, ריבוי ערוצים, ידיות קבועות, חכירות תיקיות, הצפנה.","Client GUID":"GUID של הלקוח","A random ID for this computer.":"מזהה אקראי של המחשב הזה.","Negotiate contexts":"הקשרי משא ומתן","at offset 112, 4 of them":"בהיסט 112, 4 מהם",Dialects:"דיאלקטים","Every version the laptop speaks. The server picks the newest it also knows.":"כל גרסה שהמחשב הנייד מדבר. השרת בוחר בחדשה ביותר שגם הוא מכיר.",Contexts:"הקשרים","SMB 3.1.1 extras, each in its own small block.":"תוספות של SMB 3.1.1, כל אחת בבלוק קטן משלה.","Pre-authentication integrity: SHA-512, and a 32-byte random salt":"שלמות לפני אימות: SHA-512, ומלח אקראי של 32 בתים","Encryption: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM":"הצפנה: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM","Signing: AES-GMAC, AES-CMAC, HMAC-SHA256":"חתימה: AES-GMAC, AES-CMAC, HMAC-SHA256","The server’s name: nas":"שם השרת: nas","Credits granted":"קרדיטים שהוענקו","0x00000001 (response)":"0x00000001 (תשובה)","0x0001 (signing enabled)":"0x0001 (חתימה מופעלת)",Dialect:"דיאלקט","The newest version both sides speak.":"הגרסה החדשה ביותר ששני הצדדים מדברים.","Context count":"מספר הקשרים","Server GUID":"GUID של השרת","Leases, large reads and writes.":"חכירות, קריאות וכתיבות גדולות.","Largest read, write":"הקריאה והכתיבה הגדולות ביותר","8 MB each":"8 MB כל אחת","The most data one request may carry: transactions, reads and writes.":"הכי הרבה נתונים שבקשה אחת יכולה לשאת: טרנזקציות, קריאות וכתיבות.","System time":"שעון המערכת","7 Nov 2026, 09:41:00":"7 בנוב׳ 2026, 09:41:00","Security buffer":"מאגר אבטחה","Context offset":"היסט ההקשרים","Security blob":"Blob אבטחה","GSS-API and SPNEGO wrapping, around NTLMSSP.":"עטיפת GSS-API ו־SPNEGO סביב NTLMSSP.","The login methods the server accepts: NTLMSSP":"שיטות ההתחברות שהשרת מקבל: NTLMSSP","Pre-authentication integrity: SHA-512, and the server’s own salt":"שלמות לפני אימות: SHA-512, והמלח של השרת עצמו","Encryption: AES-128-GCM":"הצפנה: AES-128-GCM","Signing: AES-GMAC":"חתימה: AES-GMAC","0x02 (signing required)":"0x02 (חתימה נדרשת)","Previous session":"סשן קודם","NTLMSSP NEGOTIATE: the NTLM options the laptop supports":"NTLMSSP NEGOTIATE: אפשרויות ה־NTLM שהמחשב הנייד תומך בהן","Not an error: the login needs another round.":"לא שגיאה: ההתחברות צריכה עוד סבב.","The server’s number for this login, from now on in every message.":"המספר של השרת להתחברות הזו, מעכשיו בכל הודעה.","Session flags":"דגלי סשן","NTLMSSP CHALLENGE: an 8-byte random challenge":"NTLMSSP CHALLENGE: אתגר אקראי של 8 בתים","The NAS’s names and its clock":"השמות של ה־NAS והשעון שלו","NTLMSSP AUTH: user alex, computer ALEX-PC":"NTLMSSP AUTH: משתמש alex, מחשב ALEX-PC","NTLMv2 response: an HMAC of the challenge, keyed with a hash of the password":"תשובת NTLMv2: HMAC של האתגר, עם גיבוב של הסיסמה כמפתח","A key for signing, encrypted":"מפתח לחתימה, מוצפן","0x00000009 (response, signed)":"0x00000009 (תשובה, חתומה)","AES-GMAC over the whole message, with a key from the login: a changed or forged message would be caught.":"AES-GMAC על כל ההודעה, עם מפתח מההתחברות: הודעה ששונתה או זויפה תיתפס.","The login is complete.":"ההתחברות הושלמה.","0x00000008 (signed)":"0x00000008 (חתום)","Server and share name, in UTF-16.":"שם השרת והשיתוף, ב־UTF-16.","The number for this share; later requests carry it.":"המספר של השיתוף הזה; הבקשות הבאות נושאות אותו.","Share type":"סוג שיתוף","1 (disk)":"1 (דיסק)","Share flags":"דגלי שיתוף","Encryption not required for this share; signing still protects every message.":"לשיתוף הזה לא נדרשת הצפנה; החתימה עדיין מגינה על כל הודעה.","0x001f01ff (full control)":"0x001f01ff (שליטה מלאה)","What this user may do in the share.":"מה המשתמש הזה רשאי לעשות בשיתוף.","Oplock, impersonation":"Oplock, התחזות","none, 2 (impersonation)":"אין, 2 (התחזות)","Desired access":"גישה מבוקשת","0x00120089 (read)":"0x00120089 (קריאה)","Read the data, its attributes and its permissions.":"לקרוא את הנתונים, את התכונות שלהם ואת ההרשאות שלהם.","File attributes":"תכונות הקובץ","Share access":"גישה משותפת","0x00000001 (read)":"0x00000001 (קריאה)","Others may read the file while it is open, but not change it.":"אחרים יכולים לקרוא את הקובץ כל עוד הוא פתוח, אבל לא לשנות אותו.",Disposition:"אופן פתיחה","1 (open, fail if missing)":"1 (לפתוח, להיכשל אם חסר)","0x00000040 (a file, not a folder)":"0x00000040 (קובץ, לא תיקייה)",Name:"שם","Create contexts":"הקשרי יצירה","File name":"שם הקובץ","Relative to the share.":"יחסית לשיתוף.","Oplock, flags":"Oplock, דגלים","none, 0":"אין, 0",Action:"פעולה","1 (opened)":"1 (נפתח)",Times:"זמנים","created, accessed, written, changed":"יצירה, גישה, כתיבה, שינוי","Windows FILETIME: 100-nanosecond steps since 1601.":"FILETIME של Windows: צעדים של 100 ננו־שניות מאז 1601.","Allocation size":"גודל מוקצה","File size":"גודל הקובץ","0x00000020 (archive)":"0x00000020 (ארכיון)","File ID":"מזהה קובץ","The handle for the open file: reads and the close name it.":"הידית של הקובץ הפתוח: הקריאות והסגירה מציינות אותה.","A big read costs one credit per 64 KB.":"קריאה גדולה עולה קרדיט אחד לכל 64 KB.","Padding, flags":"ריפוד, דגלים","Where the server should put the data in its answer: 80 bytes in, right after the headers.":"איפה השרת צריך לשים את הנתונים בתשובה שלו: 80 בתים פנימה, מיד אחרי הכותרות.","The whole file in one request.":"כל הקובץ בבקשה אחת.","Minimum, channel, remaining":"מינימום, ערוץ, נותר","Channel info":"מידע על הערוץ","Data offset":"היסט הנתונים","Data length":"אורך הנתונים","Remaining, flags":"נותר, דגלים","The file itself; its contents are not part of the lesson.":"הקובץ עצמו; התוכן שלו אינו חלק מהשיעור.","The laptop didn’t ask for the file’s details, so the rest is zeros.":"המחשב הנייד לא ביקש את פרטי הקובץ, ולכן השאר אפסים.","Times, sizes, attributes":"זמנים, גדלים, תכונות","Talking to a PLC":"לדבר עם PLC",Switch:"מתג","Plant network":"רשת המפעל","Modbus/TCP, for industrial control":"Modbus/TCP, לבקרה תעשייתית","Modbus is one of the oldest and most widely used protocols in industrial control (OT, operational technology): PLCs, sensors, motor drives and meters in factories, water works and buildings speak it. A client reads and writes numbered registers and coils on a device. Modbus/TCP carries the same small messages over TCP port 502, with no login and no encryption.":"Modbus הוא אחד הפרוטוקולים הוותיקים והנפוצים ביותר בבקרה תעשייתית (OT, טכנולוגיה תפעולית): בקרי PLC, חיישנים, ממירי מנועים ומונים במפעלים, במתקני מים ובבניינים מדברים אותו. לקוח קורא וכותב רגיסטרים וסלילים ממוספרים במכשיר. Modbus/TCP נושא את אותן הודעות קטנות בפורט TCP 502, בלי התחברות ובלי הצפנה.","1979, by Modicon":"1979, מאת Modicon","16-bit registers, on/off coils":"רגיסטרים של 16 ביט, סלילי הפעלה/כיבוי","None built in":"אין מובנית","Modbus.org specifications":"המפרטים של Modbus.org","Pump running":"המשאבה פועלת","Simple, and wide open":"פשוט, ופרוץ לגמרי","The laptop read four registers, changed a setpoint and started a pump, each with a 12-byte request and a short answer. No message carried a password and none was encrypted: Modbus trusts whoever can reach it, so the network around it has to do the protecting. Press REPLAY to watch it again.":"המחשב הנייד קרא ארבעה רגיסטרים, שינה נקודת קביעה והפעיל משאבה, כל פעם בבקשה של 12 בתים ובתשובה קצרה. אף הודעה לא נשאה סיסמה ואף אחת לא הייתה מוצפנת: Modbus סומך על כל מי שמגיע אליו, ולכן הרשת שסביבו צריכה להגן עליו. לחצו על ״שוב״ כדי לצפות שוב.","4 requests, 4 answers":"4 בקשות, 4 תשובות",Biggest:"הגדולה ביותר","17 bytes (the read answer)":"17 בתים (תשובת הקריאה)","Protect with":"הגנה בעזרת","Separate networks":"רשתות נפרדות","Port 502":"פורט 502","A TCP connection to the PLC":"חיבור TCP ל־PLC","A PLC (programmable logic controller) runs a small pumping station: it reads the sensors and switches the pumps. An engineer’s laptop on the plant network talks to it in Modbus/TCP, so it opens a TCP connection to port 502. In Modbus terms the laptop is the client and the PLC the server.":"PLC (בקר לוגי מתוכנת) מפעיל תחנת שאיבה קטנה: הוא קורא את החיישנים ומדליק ומכבה את המשאבות. המחשב הנייד של מהנדס ברשת המפעל מדבר איתו ב־Modbus/TCP, ולכן הוא פותח חיבור TCP לפורט 502. במונחי Modbus המחשב הנייד הוא הלקוח וה־PLC הוא השרת.",Roles:"תפקידים","Client asks, server answers":"הלקוח שואל, השרת עונה","Read Registers":"קריאת רגיסטרים","Function 3: four numbers":"פונקציה 3: ארבעה מספרים","The laptop asks for 4 holding registers starting at address 0, with function code 3. The PLC answers with 8 bytes: four 16-bit numbers. What they mean (the tank level in centimetres, the temperature in tenths of a degree) is written only in the PLC’s documentation; the message carries no names and no units. An HMI screen sends reads like this every second or so.":"המחשב הנייד מבקש 4 רגיסטרי החזקה החל מכתובת 0, עם קוד פונקציה 3. ה־PLC עונה ב־8 בתים: ארבעה מספרים של 16 ביט. מה הם אומרים (גובה המיכל בסנטימטרים, הטמפרטורה בעשיריות מעלה) כתוב רק בתיעוד של ה־PLC; ההודעה לא נושאת שמות ולא יחידות. מסך HMI שולח קריאות כאלה בערך כל שנייה.",Function:"פונקציה","4 registers from 0":"4 רגיסטרים מ־0","function 3":"פונקציה 3","registers 0–3":"רגיסטרים 0–3",VALUES:"ערכים","Write a Setpoint":"כתיבת נקודת קביעה","Function 6: one register":"פונקציה 6: רגיסטר אחד","The engineer raises the tank’s level setpoint from 4.50 m to 5.00 m: function 6, write single register, register 3, value 500. The PLC answers by repeating the request, which means done. From now on its program keeps the tank fuller.":"המהנדס מעלה את נקודת הקביעה של גובה המיכל מ־4.50 m ל־5.00 m: פונקציה 6, כתיבת רגיסטר בודד, רגיסטר 3, ערך 500. ה־PLC עונה בחזרה על הבקשה, וזה אומר שזה בוצע. מעכשיו התוכנית שלו שומרת על המיכל מלא יותר.","Register 3":"רגיסטר 3","The request, repeated":"הבקשה, חוזרת",WRITE:"כתיבה","register 3 = 500":"רגיסטר 3 = 500","Start a Pump":"הפעלת משאבה","Function 5: a coil":"פונקציה 5: סליל","Coils are single on/off outputs. Function 5 writes one: coil 0, pump 2, value 0xFF00, which means on. The PLC switches the pump on and echoes the request. In a real plant the PLC’s own program usually decides this, with safety interlocks.":"סלילים הם יציאות הפעלה/כיבוי בודדות. פונקציה 5 כותבת אחת: סליל 0, משאבה 2, ערך 0xFF00, כלומר הפעלה. ה־PLC מדליק את המשאבה ומחזיר את הבקשה. במפעל אמיתי את זה מחליטה בדרך כלל התוכנית של ה־PLC עצמו, עם נעילות בטיחות.","Coil 0":"סליל 0","Pump 2: on":"משאבה 2: מופעלת","0xFF00 (off: 0x0000)":"0xFF00 (כיבוי: 0x0000)","COIL ON":"סליל מופעל","coil 0: pump 2":"סליל 0: משאבה 2","pump 2 on":"משאבה 2 מופעלת","PUMP 2 RUNNING":"משאבה 2 פועלת","An Exception":"חריגה","No such register":"אין רגיסטר כזה","A request for registers that don’t exist, here 100 and 101, gets an exception: the function code with its top bit set (3 + 128 = 131) and exception code 2, illegal data address. Other codes say the function isn’t supported or the device is busy.":"בקשה לרגיסטרים שלא קיימים, כאן 100 ו־101, מקבלת חריגה: קוד הפונקציה עם הביט העליון דלוק (3 + 128 = 131) וקוד חריגה 2, כתובת נתונים לא חוקית. קודים אחרים אומרים שהפונקציה לא נתמכת או שהמכשיר עסוק.",Exception:"חריגה",Means:"משמעות","No register there":"אין שם רגיסטר","registers 100–101":"רגיסטרים 100–101",EXCEPTION:"חריגה","code 2: no such register":"קוד 2: אין רגיסטר כזה","No Security":"בלי אבטחה","Anyone who can reach it":"כל מי שמגיע אליו","Nothing in these messages says who sent them: Modbus, from 1979, has no login and no encryption, so any device that can reach port 502 can read the values and start the pump. Plants protect it with separate networks, firewalls between office and plant, lists of who may talk to each PLC, and monitoring. Modbus/TCP Security wraps the same messages in TLS, on port 802.":"שום דבר בהודעות האלה לא אומר מי שלח אותן: ב־Modbus, משנת 1979, אין התחברות ואין הצפנה, ולכן כל מכשיר שמגיע לפורט 502 יכול לקרוא את הערכים ולהפעיל את המשאבה. מפעלים מגינים עליו ברשתות נפרדות, בחומות אש בין המשרד למפעל, ברשימות של מי רשאי לדבר עם כל PLC ובניטור. Modbus/TCP Security עוטף את אותן הודעות ב־TLS, בפורט 802.","Separate networks, TLS":"רשתות נפרדות, TLS","NO LOGIN, NO ENCRYPTION":"בלי התחברות, בלי הצפנה","Seen on the plant network":"נראה ברשת המפעל","Picked by the client; the answer carries the same number.":"הלקוח בוחר; התשובה נושאת את אותו מספר.","Protocol ID":"מזהה פרוטוקול","The unit ID and everything after it.":"מזהה היחידה וכל מה שאחריו.","Unit ID":"מזהה יחידה","Which device. It matters when a gateway passes requests on to devices on a serial line.":"איזה מכשיר. זה חשוב כששער מעביר בקשות למכשירים בקו טורי.","Function code":"קוד פונקציה","Starting address":"כתובת התחלה","Modbus counts from 0, though manuals often number the same register 40001 and up.":"Modbus סופר מ־0, אף שמדריכים ממספרים לעיתים קרובות את אותו רגיסטר מ־40001 והלאה.",Quantity:"כמות","Modbus/TCP · Read Holding Registers, answer":"Modbus/TCP · Read Holding Registers, תשובה","The same number as the request.":"אותו מספר כמו בבקשה.","Byte count":"מספר בתים","Register 0":"רגיסטר 0","412 (tank level, 4.12 m)":"412 (גובה המיכל, 4.12 m)","Plain 16-bit numbers. What each one means is written in the PLC’s documentation, not in the message.":"מספרים פשוטים של 16 ביט. המשמעות של כל אחד כתובה בתיעוד של ה־PLC, לא בהודעה.","Register 1":"רגיסטר 1","183 (temperature, 18.3 °C)":"183 (טמפרטורה, 18.3 °C)","Register 2":"רגיסטר 2","1450 (pump speed, 1,450 rpm)":"1450 (מהירות המשאבה, 1,450 סל״ד)","450 (level setpoint, 4.50 m)":"450 (נקודת קביעת גובה, 4.50 m)","Register address":"כתובת הרגיסטר","3 (level setpoint)":"3 (נקודת קביעת גובה)",Value:"ערך","Modbus/TCP · Write Single Register, answer":"Modbus/TCP · Write Single Register, תשובה","The answer repeats the request: done.":"התשובה חוזרת על הבקשה: בוצע.","Coil address":"כתובת הסליל","0 (pump 2)":"0 (משאבה 2)","A coil is a single on/off output. 0xFF00 switches it on.":"סליל הוא יציאת הפעלה/כיבוי בודדת. 0xFF00 מדליק אותו.","Modbus/TCP · Write Single Coil, answer":"Modbus/TCP · Write Single Coil, תשובה","Modbus/TCP · exception":"Modbus/TCP · חריגה","131 (3 + 128: an exception)":"131 (3 + 128: חריגה)","The top bit set: the request failed.":"הביט העליון דלוק: הבקשה נכשלה.","Exception code":"קוד חריגה","There is no register at that address.":"אין רגיסטר בכתובת הזו.","Internet Routes":"נתיבים באינטרנט",Routes:"נתיבים","The laptop’s packets":"החבילות של המחשב הנייד","Border Gateway Protocol":"פרוטוקול שער הגבול","The internet is a network of networks: tens of thousands of them, run by internet providers, clouds, universities and companies, each with its own AS number. BGP is how their border routers tell each other which addresses they can reach. Every router passes on what it learns with its own number added, so each network builds its own map of the paths to every address on the internet.":"האינטרנט הוא רשת של רשתות: עשרות אלפים מהן, שמפעילים ספקי אינטרנט, עננים, אוניברסיטאות וחברות, ולכל אחת מספר AS משלה. BGP הוא הדרך שבה נתבי הגבול שלהן אומרים זה לזה לאילו כתובות הם יכולים להגיע. כל נתב מעביר הלאה את מה שהוא לומד בתוספת המספר שלו, כך שכל רשת בונה מפה משלה של הנתיבים לכל כתובת באינטרנט.",Between:"בין","Networks (ASes)":"רשתות (AS)",Table:"טבלה","About a million IPv4 routes":"כמיליון נתיבי IPv4","Path choice":"בחירת נתיב","Policy, then shortest":"מדיניות, ואז הקצר ביותר","Route learned":"הנתיב נלמד","Announced, passed on, used":"הוכרז, הועבר, נוצל","The hosting network announced its addresses, the transit network passed them on with its own number added, and the ISP’s router used that path for the laptop’s packets. When the route was withdrawn, the news spread the same way. There is no central map: every network builds its own from what its neighbours say. Press REPLAY to watch it again.":"רשת האחסון הכריזה על הכתובות שלה, רשת המעבר העבירה אותן הלאה בתוספת המספר שלה, והנתב של ספק האינטרנט השתמש בנתיב הזה לחבילות של המחשב הנייד. כשהנתיב בוטל, הידיעה התפשטה באותה דרך. אין מפה מרכזית: כל רשת בונה מפה משלה ממה שהשכנות שלה אומרות. לחצו על ״שוב״ כדי לצפות שוב.",Map:"מפה","Each network makes its own":"כל רשת בונה משלה","RPKI and filters":"RPKI ומסננים","Many Networks":"הרבה רשתות","Each with its own number":"לכל אחת מספר משלה","The internet is more than 75,000 separate networks, called autonomous systems (ASes): internet providers, clouds, universities, big companies, each with a number. Here are three: the laptop’s ISP (AS 64500), a transit network that carries others’ traffic (AS 64510), and the hosting network of www.example.com (AS 64511). BGP is how their routers tell each other where every address can be reached.":"האינטרנט הוא יותר מ־75,000 רשתות נפרדות, שנקראות מערכות אוטונומיות (AS): ספקי אינטרנט, עננים, אוניברסיטאות, חברות גדולות, ולכל אחת מספר. כאן יש שלוש: ספק האינטרנט של המחשב הנייד (AS 64500), רשת מעבר שנושאת תעבורה של אחרים (AS 64510), ורשת האחסון של www.example.com (AS 64511). BGP הוא הדרך שבה הנתבים שלהן אומרים זה לזה איפה אפשר להגיע לכל כתובת.",Networks:"רשתות","More than 75,000 ASes":"יותר מ־75,000 AS",Here:"כאן","3 ASes, a router each":"3 AS, נתב בכל אחת",Numbers:"מספרים","TCP to port 179":"TCP לפורט 179","BGP routers don’t discover each other: engineers at both ends set each other up as neighbours. The ISP’s router opens a TCP connection to the transit router on port 179. They are directly connected, so their packets go out with a TTL of 1: they can’t cross even one more router, so the session only works between direct neighbours.":"נתבי BGP לא מגלים זה את זה לבד: מהנדסים בשני הקצוות מגדירים אותם כשכנים. הנתב של ספק האינטרנט פותח חיבור TCP לנתב המעבר בפורט 179. הם מחוברים ישירות, ולכן החבילות שלהם יוצאות עם TTL של 1: הן לא יכולות לעבור אפילו עוד נתב אחד, כך שהסשן עובד רק בין שכנים ישירים.",Neighbours:"שכנים","Set up by hand":"מוגדרים ידנית","1: the next router only":"1: רק הנתב הבא","OPEN, then KEEPALIVE":"OPEN, ואז KEEPALIVE","Each router sends an OPEN: its AS number, a hold time of 180 seconds, its router ID and what it supports, such as 4-byte AS numbers. Each answers with a KEEPALIVE, and the session is established. From now on a KEEPALIVE goes every 60 seconds when there’s nothing else to send; after 180 silent seconds the session would be dropped.":"כל נתב שולח OPEN: מספר ה־AS שלו, זמן החזקה של 180 שניות, מזהה הנתב שלו ומה שהוא תומך בו, כמו מספרי AS של 4 בתים. כל אחד עונה ב־KEEPALIVE, והסשן נוצר. מעכשיו יוצא KEEPALIVE כל 60 שניות כשאין שום דבר אחר לשלוח; אחרי 180 שניות של שקט הסשן היה מנותק.","AS, hold time, ID":"AS, זמן החזקה, מזהה","KEEPALIVE: established":"KEEPALIVE: נוצר","Hold time":"זמן החזקה","hold 180 s":"החזקה 180 s","SESSION ESTABLISHED":"הסשן נוצר","Announce a Route":"הכרזה על נתיב","The hosting network: “I have these”":"רשת האחסון: ״אלה אצלי״","The hosting network’s router announces 203.0.113.0/24, the 256 addresses that include www.example.com, to the transit network, which it pays to carry its traffic. The UPDATE says how to get there: AS_PATH 64511, only its own network so far, and NEXT_HOP, its own address on the link between them.":"הנתב של רשת האחסון מכריז על 203.0.113.0/24, 256 הכתובות שכוללות את www.example.com, לרשת המעבר, שהוא משלם לה כדי שתישא את התעבורה שלו. ה־UPDATE אומר איך מגיעים לשם: AS_PATH 64511, בינתיים רק הרשת שלו, ו־NEXT_HOP, הכתובת שלו על הקישור ביניהם.","path 64511":"נתיב 64511","Passed On":"הועבר הלאה","Each network adds its number":"כל רשת מוסיפה את המספר שלה","The transit router accepts the route and passes it to its other neighbours, the ISP among them, with its own number added to the front: AS_PATH 64510 64511, and itself as the next hop. The ISP’s router may hear of the same prefix from several neighbours. It picks one by its own policy first (routes through paying customers before others, say), then by the shortest AS path.":"נתב המעבר מקבל את הנתיב ומעביר אותו לשכנים האחרים שלו, ביניהם ספק האינטרנט, כשהמספר שלו נוסף בהתחלה: AS_PATH 64510 64511, והוא עצמו כקפיצה הבאה. הנתב של הספק עשוי לשמוע על אותה קידומת מכמה שכנים. הוא בוחר אחד קודם לפי המדיניות שלו (נגיד, נתיבים דרך לקוחות משלמים לפני אחרים), ואז לפי ה־AS_PATH הקצר ביותר.","Best path":"הנתיב הטוב ביותר","path 64510 64511":"נתיב 64510 64511","ROUTE TO 203.0.113.0/24":"נתיב ל־203.0.113.0/24","Follow the Route":"בעקבות הנתיב","Packets go where BGP said":"החבילות הולכות לאן ש־BGP אמר","When the laptop connects to www.example.com (its address found by DNS as usual), its packets reach the ISP, whose router now sends anything for 203.0.113.0/24 to the transit router, and the transit router sends it on to the hosting network. The answer comes back by whatever route the hosting network chose towards the laptop’s ISP: on the internet the way back is often different from the way there.":"כשהמחשב הנייד מתחבר אל www.example.com (שכתובתו נמצאה ב־DNS כרגיל), החבילות שלו מגיעות לספק האינטרנט, שהנתב שלו שולח עכשיו כל מה שמיועד ל־203.0.113.0/24 לנתב המעבר, ונתב המעבר מעביר אותו הלאה לרשת האחסון. התשובה חוזרת בנתיב שרשת האחסון בחרה לכיוון ספק האינטרנט של המחשב הנייד: באינטרנט, הדרך חזרה שונה לא פעם מהדרך הלוך.","Way back":"הדרך חזרה","Chosen separately":"נבחרת בנפרד","the way back":"הדרך חזרה",Withdrawn:"בוטל","Routes can be taken back":"אפשר לבטל נתיבים","Later the hosting network takes the prefix back, as it would if a link failed: an UPDATE listing it under withdrawn routes. The transit router passes it on, and within seconds to minutes networks everywhere forget the path. A session that goes quiet past its hold time loses all its routes at once. In 2021 Facebook withdrew the routes to its own DNS servers and vanished from the internet for six hours.":"מאוחר יותר רשת האחסון מבטלת את הקידומת, כמו שהייתה עושה אם קישור היה נופל: הודעת UPDATE שמונה אותה בין הנתיבים המבוטלים. נתב המעבר מעביר אותה הלאה, ותוך שניות עד דקות רשתות בכל מקום שוכחות את הנתיב. סשן ששותק יותר מזמן ההחזקה שלו מאבד את כל הנתיבים שלו בבת אחת. ב־2021 ביטלה Facebook את הנתיבים לשרתי ה־DNS שלה ונעלמה מהאינטרנט לשש שעות.","Spreads in":"מתפשט תוך","Seconds to minutes":"שניות עד דקות","Session lost":"אם הסשן אבד","All its routes go":"כל הנתיבים שלו נעלמים",WITHDRAW:"ביטול","Trust Problems":"בעיות אמון","BGP believes its neighbours":"BGP מאמין לשכנים שלו","A router accepts what its neighbours announce. A network that announces addresses that aren’t its own, by mistake or on purpose, pulls their traffic towards it: in 2008 a Pakistani ISP took YouTube offline worldwide this way. With RPKI the holder of a prefix signs which AS may announce it, and routers that check drop any other. Filters on what each neighbour may announce do the rest.":"נתב מקבל את מה שהשכנים שלו מכריזים. רשת שמכריזה על כתובות שאינן שלה, בטעות או בכוונה, מושכת אליה את התעבורה שלהן: ב־2008 ספק אינטרנט פקיסטני הוריד כך את YouTube בכל העולם. עם RPKI בעל הקידומת חותם איזה AS רשאי להכריז עליה, ונתבים שבודקים זורקים כל AS אחר. מסננים על מה שכל שכן רשאי להכריז עושים את השאר.",Risk:"סיכון","Hijacks and leaks":"חטיפות ודליפות","Signed: who may announce":"חתום: מי רשאי להכריז",Also:"וגם","Filters per neighbour":"מסננים לכל שכן","CHECK WHO MAY ANNOUNCE":"בדקו מי רשאי להכריז","UPDATE Message: withdrawn 203.0.113.0/24":"UPDATE Message: בוטל 203.0.113.0/24",Marker:"סמן","16 bytes of 0xFF":"16 בתים של 0xFF","All ones: where a message starts.":"הכול אחדות: כאן מתחילה הודעה.","The first message on a session: who this router is and what it supports.":"ההודעה הראשונה בסשן: מי הנתב הזה ובמה הוא תומך.","This router’s network. (A 4-byte AS number goes in the capability below, with 23456 here.)":"הרשת של הנתב הזה. (מספר AS של 4 בתים נכנס ביכולת שלמטה, וכאן 23456.)","If nothing at all arrives for this long, the session is dropped. Both sides use the lower offer.":"אם לא מגיע שום דבר במשך זמן כזה, הסשן מנותק. שני הצדדים משתמשים בהצעה הנמוכה.","BGP identifier":"מזהה BGP","The router’s ID, usually one of its addresses.":"המזהה של הנתב, בדרך כלל אחת הכתובות שלו.","Optional parameters":"פרמטרים אופציונליים","parameter 2, 14 bytes":"פרמטר 2, 14 בתים","What this router can do beyond the basics.":"מה הנתב הזה יודע לעשות מעבר לבסיס.",Multiprotocol:"ריבוי פרוטוקולים","Which kinds of routes it will exchange on this session.":"אילו סוגי נתיבים הוא יחליף בסשן הזה.","Route refresh":"רענון נתיבים","It can ask the other side to send all its routes again.":"הוא יכול לבקש מהצד השני לשלוח שוב את כל הנתיבים שלו.","4-byte AS numbers":"מספרי AS של 4 בתים","2-byte AS numbers ran short, so newer ones are 4 bytes long.":"מספרי ה־AS של 2 בתים אזלו, לכן החדשים באורך 4 בתים.","Only the header: “still here”. Sent when there’s nothing else to say, every third of the hold time.":"רק הכותרת: ״עדיין כאן״. נשלחת כשאין שום דבר אחר לומר, בכל שליש מזמן ההחזקה.","Routes: paths to new addresses, and ones taken back.":"נתיבים: דרכים לכתובות חדשות, ונתיבים שבוטלו.","Withdrawn routes":"נתיבים מבוטלים","Path attributes":"מאפייני נתיב","0 (IGP: from inside the network that announced it)":"0 (IGP: מתוך הרשת שהכריזה עליו)","Every network the route has passed through, the latest first. Other things being equal, the shorter path wins; a router that finds its own number here drops the route, so routes can’t loop.":"כל רשת שהנתיב עבר דרכה, האחרונה ראשונה. כשכל השאר שווה, הנתיב הקצר מנצח; נתב שמוצא כאן את המספר שלו זורק את הנתיב, כך שנתיבים לא יכולים להסתובב בלולאה.","Send packets for these addresses to this router.":"שלחו חבילות לכתובות האלה לנתב הזה.",Reachable:"ניתנות להשגה","The addresses this route leads to: a prefix, here 256 addresses.":"הכתובות שהנתיב הזה מוביל אליהן: קידומת, כאן 256 כתובות.","BGP · UPDATE (withdrawal)":"BGP · UPDATE (ביטול)","These addresses can no longer be reached through this router.":"כבר אי אפשר להגיע לכתובות האלה דרך הנתב הזה.","A Video Call":"שיחת וידאו",Signalling:"איתות","STUN and ICE":"STUN ו־ICE",Media:"מדיה","STUN Server":"שרת STUN","Sam’s Router":"הנתב של Sam","Sam’s Laptop":"המחשב הנייד של Sam","Web Real-Time Communication":"תקשורת ווב בזמן אמת","WebRTC lets two browsers call each other, with audio, video and data going straight between them, not through a server. A server only introduces them: they swap descriptions of what they can send and where they can be reached (signalling), find a way through both home routers with ICE and STUN, encrypt with DTLS, and send the media over UDP as SRTP.":"WebRTC מאפשר לשני דפדפנים להתקשר זה לזה, כשהשמע, הווידאו והנתונים עוברים ישירות ביניהם ולא דרך שרת. שרת רק מכיר ביניהם: הם מחליפים תיאורים של מה שהם יכולים לשלוח ואיפה אפשר להשיג אותם (איתות), מוצאים מעבר דרך שני הנתבים הביתיים עם ICE ו־STUN, מצפינים עם DTLS ושולחים את המדיה על גבי UDP כ־SRTP.","Media over":"מדיה על גבי","Always on":"תמיד פועל","Works in":"נתמך","Every major browser":"בכל הדפדפנים הגדולים","W3C; RFC 8825 and others":"W3C; RFC 8825 ועוד","On the call":"בשיחה","Introduced by a server, then direct":"שרת הכיר, ואז ישירות","The signalling server passed the offer and the answer between the two browsers, a STUN server told the laptop its public address, and an ICE check found a way through both home routers. After a DTLS handshake, encrypted audio and video went straight from one laptop to the other. Press REPLAY to watch it again.":"שרת האיתות העביר את ההצעה ואת התשובה בין שני הדפדפנים, שרת STUN אמר למחשב הנייד מה הכתובת הציבורית שלו, ובדיקת ICE מצאה מעבר דרך שני הנתבים הביתיים. אחרי לחיצת יד של DTLS, שמע ווידאו מוצפנים עברו ישירות ממחשב נייד אחד לשני. לחצו על ״שוב״ כדי לצפות שוב.","Via call.example.com":"דרך call.example.com","Media path":"נתיב המדיה","Direct, through 2 NATs":"ישירות, דרך 2 NAT","DTLS, then SRTP":"DTLS, ואז SRTP","If blocked":"אם חסום","A TURN relay":"ממסר TURN","Join the Call":"הצטרפות לשיחה","Through a signalling server":"דרך שרת איתות","The laptop opens a call page on call.example.com, and the page keeps a WebSocket open to the server, inside TLS. It joins room 42, where Sam is already waiting. The server will pass messages between the two browsers. WebRTC doesn’t say how: every app does this signalling its own way.":"המחשב הנייד פותח דף שיחה ב־call.example.com, והדף מחזיק WebSocket פתוח אל השרת, בתוך TLS. הוא מצטרף לחדר 42, שבו Sam כבר בהמתנה. השרת יעביר הודעות בין שני הדפדפנים. WebRTC לא קובע איך: כל אפליקציה עושה את האיתות הזה בדרך משלה.","The app’s own server":"השרת של האפליקציה עצמה","A WebSocket in TLS":"WebSocket בתוך TLS",Room:"חדר","42, with Sam":"42, עם Sam",JOIN:"הצטרפות","room 42":"חדר 42","SAM IS HERE":"Sam כאן","peer: Sam":"צד שני: Sam","Public Address?":"כתובת ציבורית?","Ask a STUN server":"לשאול שרת STUN","Behind its home router the laptop knows only its private address, 192.168.1.10, which nobody on the internet can reach. So it asks a STUN server named in the call page’s settings, with one small UDP request. The answer says where the request seemed to come from, 198.51.100.7 port 61022: the router’s public address and the port its NAT opened for this conversation.":"מאחורי הנתב הביתי, המחשב הנייד מכיר רק את הכתובת הפרטית שלו, 192.168.1.10, שאף אחד באינטרנט לא יכול להגיע אליה. לכן הוא שואל שרת STUN שמופיע בהגדרות של דף השיחה, בבקשת UDP קטנה אחת. התשובה אומרת מאיפה הבקשה נראתה מגיעה, 198.51.100.7 פורט 61022: הכתובת הציבורית של הנתב והפורט שה־NAT שלו פתח לשיחה הזו.",Public:"ציבורית","what is my address?":"מה הכתובת שלי?","YOUR ADDRESS":"הכתובת שלך","The Offer":"ההצעה","An SDP description, via the server":"תיאור SDP, דרך השרת","The browser writes an offer in SDP: the media it wants to send (Opus audio; video in VP8, H.264 and others), the fingerprint of its DTLS certificate, its ICE user name and password, and its candidates, the addresses it might be reached at. Its private address is hidden behind a random .local name. The signalling server passes the offer on to Sam.":"הדפדפן כותב הצעה ב־SDP: המדיה שהוא רוצה לשלוח (שמע Opus; וידאו ב־VP8, ב־H.264 ובאחרים), טביעת האצבע של תעודת ה־DTLS שלו, שם המשתמש והסיסמה של ICE, והמועמדים שלו, הכתובות שאולי אפשר להשיג אותו בהן. הכתובת הפרטית שלו מוסתרת מאחורי שם .local אקראי. שרת האיתות מעביר את ההצעה אל Sam.","SDP, in a JSON message":"SDP, בהודעת JSON",Candidates:"מועמדים",".local name, 198.51.100.7":"שם .local, 198.51.100.7","About 4.7 KB":"כ־4.7 KB","SDP: audio, video":"SDP: שמע, וידאו",candidates:"מועמדים","to Sam":"אל Sam","Sam’s browser replies":"הדפדפן של Sam עונה","Sam accepts the call. Sam’s browser answers with SDP of its own: the codecs it picked from the offer, its certificate fingerprint, its ICE user name and password, and its candidates, including its public address, 198.51.100.200 port 49170, which it learned from a STUN server the same way. It also says it will start the encryption handshake. Now each browser knows where the other might be reached.":"השיחה מתקבלת אצל Sam. הדפדפן של Sam עונה ב־SDP משלו: המקודדים שבחר מתוך ההצעה, טביעת האצבע של התעודה שלו, שם המשתמש והסיסמה של ICE, והמועמדים שלו, ובהם הכתובת הציבורית שלו, 198.51.100.200 פורט 49170, שלמד משרת STUN באותה דרך. הוא גם מודיע שהוא יתחיל את לחיצת היד של ההצפנה. עכשיו כל דפדפן יודע איפה אולי אפשר להשיג את השני.",Codecs:"מקודדים","Sam’s address":"הכתובת של Sam","Starts DTLS":"מתחיל DTLS","Sam’s browser":"הדפדפן של Sam","from Sam":"מ־Sam","Punch Through":"לפרוץ דרך","Checks straight to each other":"בדיקות ישירות זה לזה","Now the browsers try pairs of addresses with STUN checks sent straight to each other (ICE). Each check also opens a way back through the sender’s own router, so once both sides have sent one, checks get through both NATs. This one is answered: the direct path works. The laptop then repeats the check with USE-CANDIDATE, choosing this pair for the call.":"עכשיו הדפדפנים מנסים זוגות כתובות עם בדיקות STUN שנשלחות ישירות זה לזה (ICE). כל בדיקה פותחת גם דרך חזרה דרך הנתב של השולח עצמו, כך שברגע ששני הצדדים שלחו בדיקה, הבדיקות עוברות את שני ה־NAT. על הבדיקה הזו מגיעה תשובה: הנתיב הישיר עובד. אז המחשב הנייד חוזר על הבדיקה עם USE-CANDIDATE ובוחר את הזוג הזה לשיחה.",Checks:"בדיקות","STUN, peer to peer":"STUN, בין העמיתים","The ICE password":"סיסמת ה־ICE","A direct path":"נתיב ישיר",CHECK:"בדיקה","IT WORKS":"עובד","direct path":"נתיב ישיר","THROUGH BOTH ROUTERS":"דרך שני הנתבים","DTLS Handshake":"לחיצת יד DTLS","Keys for the media":"מפתחות למדיה","Over the same path the browsers run a DTLS handshake: TLS for UDP. Their certificates are self-signed, so each checks the other’s against the fingerprint in the SDP, which came through the signalling server inside TLS. The handshake also agrees the keys for SRTP, which encrypts the audio and video. WebRTC never sends media unencrypted.":"באותו נתיב הדפדפנים מבצעים לחיצת יד DTLS, כלומר TLS ל־UDP. התעודות שלהם חתומות בחתימה עצמית, לכן כל אחד בודק את התעודה של השני מול טביעת האצבע ב־SDP, שהגיעה דרך שרת האיתות בתוך TLS. לחיצת היד גם מסכמת את המפתחות ל־SRTP, שמצפין את השמע והווידאו. WebRTC אף פעם לא שולח מדיה לא מוצפנת.","1.2, TLS over UDP":"1.2, TLS על גבי UDP","Checked by fingerprint":"נבדקות לפי טביעת אצבע",Gives:"מספקת","The SRTP keys":"מפתחות SRTP",certificate:"תעודה","Media Flows":"המדיה זורמת","Audio and video, direct":"שמע ווידאו, ישירות","Audio goes in an SRTP packet every 20 ms, and video as frames split over several packets. Each packet has a readable RTP header (sequence number, timestamp, stream ID) and encrypted media. None of it passes through call.example.com. Both browsers watch delay and loss and adjust the video quality to suit, and a data channel for chat or files can share the same path.":"השמע נשלח בחבילת SRTP כל 20 ms, והווידאו כפריימים שמפוצלים על פני כמה חבילות. לכל חבילה יש כותרת RTP קריאה (מספר רצף, חותמת זמן, מזהה זרם) ומדיה מוצפנת. שום דבר מזה לא עובר דרך call.example.com. שני הדפדפנים עוקבים אחרי ההשהיה והאובדן ומתאימים את איכות הווידאו בהתאם, וערוץ נתונים לצ׳אט או לקבצים יכול לחלוק את אותו נתיב.","Opus, a packet per 20 ms":"Opus, חבילה כל 20 ms",Video:"וידאו","VP8, adapts to the network":"VP8, מסתגל לרשת","None of it":"שום דבר מזה",AUDIO:"שמע","Opus, every 20 ms":"Opus, כל 20 ms",VIDEO:"וידאו","VP8, a frame in 3 packets":"VP8, פריים ב־3 חבילות","Peer to Peer":"עמית לעמית","And when it can’t be":"וכשאי אפשר","The server helped the two browsers find each other, then stepped aside: the call goes straight between the two homes. When a network won’t let direct packets through (some company firewalls, some mobile networks), ICE falls back to a TURN server that relays the encrypted media without being able to read it. Group calls usually send media through a server too, called an SFU.":"השרת עזר לשני הדפדפנים למצוא זה את זה, ואז זז הצידה: השיחה עוברת ישירות בין שני הבתים. כשרשת לא מעבירה חבילות ישירות (חלק מחומות האש בחברות, חלק מהרשתות הסלולריות), ICE עובר לשרת TURN שמעביר את המדיה המוצפנת בלי יכולת לקרוא אותה. גם שיחות קבוצתיות שולחות בדרך כלל את המדיה דרך שרת, שנקרא SFU.","Laptop to laptop":"ממחשב נייד למחשב נייד",Fallback:"חלופה","TURN relay (encrypted)":"ממסר TURN (מוצפן)","Group calls":"שיחות קבוצתיות","Usually via an SFU":"בדרך כלל דרך SFU","NO SERVER IN THE MIDDLE":"בלי שרת באמצע","A WebSocket text message":"הודעת טקסט של WebSocket","The attributes; the 20-byte header isn’t counted.":"המאפיינים; הכותרת של 20 בתים לא נספרת.","Always this value: tells STUN apart from the other traffic on the same port.":"תמיד הערך הזה: מבדיל את STUN משאר התעבורה באותו פורט.","Random; the response carries the same ID.":"אקראי; התשובה נושאת את אותו מזהה.","Where the request came from, as the server saw it: the home router’s public address, and the port its NAT picked for this conversation.":"מאיפה הבקשה הגיעה, כפי שהשרת ראה אותה: הכתובת הציבורית של הנתב הביתי, והפורט שה־NAT שלו בחר לשיחה הזו.","Their internet provider’s router, the next hop.":"הנתב של ספק האינטרנט של Sam, הקפיצה הבאה.","Their router’s internet-facing port.":"הפורט של הנתב של Sam שפונה לאינטרנט.","The ICE user names from the offer and the answer, the other side’s first: proves the check belongs to this call.":"שמות המשתמש של ICE מההצעה ומהתשובה, של הצד השני קודם: מוכיח שהבדיקה שייכת לשיחה הזו.","The priority a new candidate found by this check would get.":"העדיפות שהייתה מקבל מועמד חדש שהבדיקה הזו מגלה.","This side, the caller, makes the final choice of path. The random number settles a tie.":"הצד הזה, המתקשר, קובע את הבחירה הסופית של הנתיב. המספר האקראי מכריע בתיקו.","HMAC-SHA1 of the message, keyed with an ICE password swapped through the signalling server, so a stranger can’t fake a check or its answer.":"HMAC-SHA1 של ההודעה, עם מפתח שהוא סיסמת ICE שהוחלפה דרך שרת האיתות, כך שזר לא יכול לזייף בדיקה או את התשובה עליה.","A CRC-32 of the message: marks it clearly as STUN.":"CRC-32 של ההודעה: מסמן אותה בבירור כ־STUN.","Where the check came from, as the other laptop saw it: the home router’s public address and port.":"מאיפה הבדיקה הגיעה, כפי שהמחשב הנייד השני ראה אותה: הכתובת הציבורית והפורט של הנתב הביתי.",Epoch:"תקופה","Counts this side’s records, so repeats and stale ones can be spotted.":"סופר את הרשומות של הצד הזה, כדי שאפשר יהיה לזהות כפולות וישנות.","Message length":"אורך ההודעה","Message sequence":"רצף ההודעה","Handshake messages are numbered, so they can be put back in order.":"הודעות לחיצת היד ממוספרות, כדי שאפשר יהיה להחזיר אותן לסדר.",Fragment:"קטע","Cipher suites: ECDHE-ECDSA with AES-GCM, and others":"חבילות הצפנה: ECDHE-ECDSA עם AES-GCM, ועוד","use_srtp: the SRTP protection it supports":"use_srtp: הגנת ה־SRTP שהוא תומך בה","Chosen: ECDHE-ECDSA-AES128-GCM-SHA256":"נבחרה: ECDHE-ECDSA-AES128-GCM-SHA256","A self-signed certificate the browser made; its fingerprint was in the offer":"תעודה בחתימה עצמית שהדפדפן יצר; טביעת האצבע שלה הופיעה בהצעה","Its half of an X25519 key exchange, signed":"החצי שלו בהחלפת מפתחות X25519, חתום","Asks Sam’s browser for its certificate too":"מבקש גם מהדפדפן של Sam את התעודה שלו","Sam’s self-signed certificate; its fingerprint was in the answer":"התעודה בחתימה עצמית של Sam; טביעת האצבע שלה הופיעה בתשובה","Its half of the X25519 key exchange":"החצי שלו בהחלפת מפתחות X25519","A signature that proves it holds the certificate’s key":"חתימה שמוכיחה שהמפתח של התעודה בידיו","From the next record on, this side encrypts.":"מהרשומה הבאה והלאה, הצד הזה מצפין.","Finished (encrypted)":"Finished (מוצפנת)","Epoch 1: protected with the keys just agreed.":"תקופה 1: מוגן במפתחות שסוכמו זה עתה.","An 8-byte nonce, the Finished message and a 16-byte tag (AES-128-GCM).":"מספר חד־פעמי של 8 בתים, הודעת Finished ותג של 16 בתים (AES-128-GCM).","SRTP · audio":"SRTP · שמע","2, no padding, extension, no CSRCs":"2, בלי ריפוד, עם הרחבה, בלי CSRC","X set: a header extension follows the fixed header.":"X דלוק: אחרי הכותרת הקבועה באה הרחבת כותרת.","One more for each packet, so a lost or late one shows.":"גדל באחד בכל חבילה, כך שחבילה שאבדה או איחרה בולטת.","Audio clock, 48,000 ticks a second: +960 per 20 ms.":"שעון שמע, 48,000 תקתוקים בשנייה: +960 כל 20 ms.","Which stream this is; announced in the SDP.":"איזה זרם זה; מוכרז ב־SDP.","Header extension":"הרחבת כותרת","0xbede, 2 words":"0xbede, 2 מילים","One-byte elements: an ID (from the SDP’s a=extmap lines) and a length.":"רכיבים של בית אחד: מזהה (משורות a=extmap ב־SDP) ואורך.","Audio level":"עוצמת שמע","How loud this packet is, so a group call can show who is talking without decrypting.":"כמה חזקה החבילה הזו, כדי ששיחה קבוצתית תוכל להראות מי מדבר בלי לפענח.","Transport sequence":"רצף תעבורה","Numbers every packet of the call; the receiver reports what arrived when, for congestion control.":"ממספר כל חבילה בשיחה; המקבל מדווח מה הגיע ומתי, לצורך בקרת עומס.","Encrypted media":"מדיה מוצפנת","20 ms of Opus audio, encrypted with keys from the DTLS handshake (AES-128-GCM).":"20 ms של שמע Opus, מוצפנים במפתחות מלחיצת היד של DTLS (AES-128-GCM).","Authentication tag":"תג אימות","Proves the packet came from the other side unchanged; the header is covered too.":"מוכיח שהחבילה הגיעה מהצד השני בלי שינוי; גם הכותרת מכוסה.","SRTP · video":"SRTP · וידאו","Video clock, 90,000 ticks a second: +3,000 per frame at 30 frames a second.":"שעון וידאו, 90,000 תקתוקים בשנייה: +3,000 לכל פריים ב־30 פריימים בשנייה.","Absolute send time":"זמן שליחה מוחלט","When the packet was sent, so the receiver can tell when the network is filling up.":"מתי החבילה נשלחה, כדי שהמקבל יבין מתי הרשת מתחילה להתמלא.","1 byte":"1 בית","Part of a VP8 video frame, encrypted with keys from the DTLS handshake (AES-128-GCM).":"חלק מפריים וידאו של VP8, מוצפן במפתחות מלחיצת היד של DTLS (AES-128-GCM).","Marker set: the last packet of a video frame.":"Marker דלוק: החבילה האחרונה של פריים וידאו.","8 ports":"8 פורטים","Frames and switches":"מסגרות ומתגים","Broadband logins":"התחברות לפס רחב","The laptop sent it with 128; the router took 1 when it passed it on.":"המחשב הנייד שלח אותה עם 128; הנתב הוריד 1 כשהעביר אותה הלאה.","Frames & Switches":"מסגרות ומתגים","To the NAS":"אל ה-NAS","To the internet":"אל האינטרנט","Ethernet and Switches":"אתרנט ומתגים","Ethernet carries almost every wired network, and Wi-Fi access points pass their traffic on to it. Every network card has a 48-bit MAC address. A frame says which card it is for and which card sent it, and a switch delivers it: it learns which port each address is behind from the frames it sees, and sends each frame only where it needs to go.":"אתרנט נושא כמעט כל רשת קווית, ונקודות גישה של Wi-Fi מעבירות אליו את התעבורה שלהן. לכל כרטיס רשת יש כתובת MAC בת 48 סיביות. מסגרת אומרת לאיזה כרטיס היא מיועדת ואיזה כרטיס שלח אותה, והמתג מוסר אותה: הוא לומד מהמסגרות שהוא רואה מאחורי איזה פורט נמצאת כל כתובת, ושולח כל מסגרת רק לאן שהיא צריכה להגיע.","48-bit MAC":"MAC בן 48 סיביות","14 bytes, plus a 4-byte FCS":"14 בתים, ועוד FCS של 4 בתים","Frame size":"גודל מסגרת","64 to 1,518 bytes":"64 עד 1,518 בתים",Speeds:"מהירויות",Switched:"מותג","Learned, flooded, forwarded":"למד, הציף, העביר","The switch learned where the laptop and the NAS were from the frames they sent, flooded only the broadcast, and sent every other frame out of just the port it needed. MAC addresses carried each frame across one link; at the router the packet moved into a new frame. Press REPLAY to watch it again.":"המתג למד איפה המחשב הנייד וה-NAS מהמסגרות ששלחו, הציף רק את השידור לכולם, ושלח כל מסגרת אחרת רק דרך הפורט הדרוש. כתובות ה-MAC נשאו כל מסגרת על פני קישור אחד; בנתב עברה החבילה למסגרת חדשה. לחצו על ״שוב״ כדי לצפות שוב.",Learned:"נלמד","2 addresses, 2 ports":"2 כתובות, 2 פורטים",Flooded:"הוצף","Only the broadcast":"רק השידור לכולם",Frame:"מסגרת","14-byte header, 4-byte FCS":"כותרת 14 בתים, FCS של 4","Forgets after":"שוכח אחרי","5 minutes unused":"5 דקות בלי שימוש","Who Has the NAS?":"למי יש את ה-NAS?","A broadcast asks for a MAC address":"שידור לכולם שואל על כתובת MAC","The laptop wants to reach the NAS at 192.168.1.20. On a local network, frames are delivered by MAC address, and the laptop doesn’t know the NAS’s yet. So it sends an ARP request to ff:ff:ff:ff:ff:ff, the broadcast address, into port 1 of the switch.":"המחשב הנייד רוצה להגיע ל-NAS בכתובת 192.168.1.20. ברשת מקומית מסגרות נמסרות לפי כתובת MAC, והמחשב עוד לא מכיר את זו של ה-NAS. לכן הוא שולח בקשת ARP אל ff:ff:ff:ff:ff:ff, כתובת השידור לכולם, לתוך פורט 1 של המתג.","Looking for":"מחפש","ff:ff:ff:ff:ff:ff (all)":"ff:ff:ff:ff:ff:ff (כולם)",Into:"נכנס דרך","Switch port 1":"פורט 1 במתג","who has 192.168.1.20?":"למי יש 192.168.1.20?","Learn, Then Flood":"ללמוד, ואז להציף","The switch notes where the laptop is":"המתג רושם איפה המחשב הנייד","A switch reads each frame’s source address and notes it in its MAC table: 00:00:5e:00:53:10 is on port 1. A broadcast is for everyone, so it sends a copy out of every other port: to the NAS on port 2 and the router on port 8. Frames for unknown addresses are flooded too.":"המתג קורא את כתובת המקור של כל מסגרת ורושם אותה בטבלת ה-MAC שלו: ‎00:00:5e:00:53:10 נמצא בפורט 1. שידור לכולם מיועד לכולם, ולכן הוא שולח עותק דרך כל פורט אחר: ל-NAS בפורט 2 ולנתב בפורט 8. גם מסגרות לכתובות לא מוכרות מוצפות.","…:53:10 is on port 1":"‎…:53:10 בפורט 1",Copies:"עותקים","Out of every other port":"דרך כל פורט אחר","Unknown address":"כתובת לא מוכרת","Flooded the same way":"מוצפת באותו אופן","…:53:10 IS ON PORT 1":"‎…:53:10 בפורט 1","copies out of ports 2 and 8":"עותקים דרך פורטים 2 ו-8","Only the NAS Answers":"רק ה-NAS עונה","The reply goes to one port":"התשובה הולכת לפורט אחד","Every device reads the request, but only the NAS has 192.168.1.20, so only it answers, straight to the laptop’s MAC; the router ignores it. The switch learns that 00:00:5e:00:53:20 is on port 2. It already knows where the laptop is, so the reply leaves by port 1 alone.":"כל מכשיר קורא את הבקשה, אבל רק ל-NAS יש 192.168.1.20, ולכן רק הוא עונה, ישר ל-MAC של המחשב הנייד; הנתב מתעלם ממנה. המתג לומד ש-‎00:00:5e:00:53:20 נמצא בפורט 2. הוא כבר יודע איפה המחשב, ולכן התשובה יוצאת רק דרך פורט 1.","To the laptop only":"רק למחשב הנייד","…:53:20 is on port 2":"‎…:53:20 בפורט 2","Out of":"יוצא דרך","Port 1":"פורט 1","…:53:20 IS ON PORT 2":"‎…:53:20 בפורט 2","port 1 only":"רק פורט 1","Port to Port":"מפורט לפורט","Frames go only where they must":"מסגרות הולכות רק לאן שצריך","The laptop connects to the NAS. Each frame starts with the NAS’s MAC, then its own, then a type: 0x0800, an IPv4 packet. After the packet, the card adds a 4-byte checksum. The switch looks up the destination and sends each frame out of port 2 only. The router never sees them.":"המחשב הנייד מתחבר ל-NAS. כל מסגרת מתחילה ב-MAC של ה-NAS, אחר כך ב-MAC שלו, ואז בסוג: 0x0800, חבילת IPv4. אחרי החבילה הכרטיס מוסיף סכום ביקורת של 4 בתים. המתג מחפש את היעד ושולח כל מסגרת רק דרך פורט 2. הנתב אף פעם לא רואה אותן.","To, from, type: 14 bytes":"אל, מאת, סוג: 14 בתים","4 bytes, added by the card":"4 בתים, הכרטיס מוסיף","Router sees":"הנתב רואה",Nothing:"כלום","type 0x0800 (IPv4)":"סוג 0x0800 (IPv4)","out of port 2 only":"רק דרך פורט 2","Off the Network":"מחוץ לרשת","A frame for the router":"מסגרת לנתב","Next the laptop opens a website at 203.0.113.10. That address isn’t on the local network, so the frame goes to the router: the router’s MAC, known from an earlier ARP, is the destination, while the packet inside still names 203.0.113.10. The switch sends it out of port 8.":"עכשיו המחשב הנייד פותח אתר בכתובת 203.0.113.10. הכתובת הזו לא ברשת המקומית, ולכן המסגרת הולכת לנתב: היעד הוא ה-MAC של הנתב, שידוע מ-ARP קודם, בעוד שהחבילה בפנים עדיין מציינת 203.0.113.10. המתג שולח אותה דרך פורט 8.","Frame to":"מסגרת אל","The router’s MAC":"ה-MAC של הנתב","Packet to":"חבילה אל","Port 8":"פורט 8","IP packet to 203.0.113.10":"חבילת IP אל 203.0.113.10","out of port 8":"דרך פורט 8","A New Frame":"מסגרת חדשה","Every hop rewraps the packet":"כל קפיצה עוטפת את החבילה מחדש","The router takes the packet out of the frame, lowers its TTL and swaps in its public address (NAT). Then it puts the packet in a new frame for its next link: its internet-side MAC as the source, the provider’s router as the destination. MAC addresses only ever cross one link.":"הנתב מוציא את החבילה מהמסגרת, מוריד את ה-TTL ומכניס את הכתובת הציבורית שלו (NAT). אחר כך הוא שם את החבילה במסגרת חדשה לקישור הבא: ה-MAC שלו בצד האינטרנט כמקור, והנתב של הספק כיעד. כתובות MAC אף פעם לא חוצות יותר מקישור אחד.","The router’s internet port":"פורט האינטרנט של הנתב","The provider’s router":"הנתב של הספק","Still 203.0.113.10":"עדיין 203.0.113.10","NEW FRAME":"מסגרת חדשה","from the router’s internet port":"מפורט האינטרנט של הנתב","IP still to 203.0.113.10":"ה-IP עדיין אל 203.0.113.10","In port 1 · Who has 192.168.1.20? Tell 192.168.1.10":"נכנס בפורט 1 · Who has 192.168.1.20? Tell 192.168.1.10","Out port 2 (flooded) · Who has 192.168.1.20?":"יוצא בפורט 2 (הצפה) · Who has 192.168.1.20?","Out port 8 (flooded) · Who has 192.168.1.20?":"יוצא בפורט 8 (הצפה) · Who has 192.168.1.20?","In port 2 · 192.168.1.20 is at 00:00:5e:00:53:20":"נכנס בפורט 2 · 192.168.1.20 is at 00:00:5e:00:53:20","Out port 1 only · 192.168.1.20 is at 00:00:5e:00:53:20":"יוצא רק בפורט 1 · 192.168.1.20 is at 00:00:5e:00:53:20","In port 1 · 50532 → 445 [SYN]":"נכנס בפורט 1 · 50532 → 445 [SYN]","Out port 2 · 50532 → 445 [SYN]":"יוצא בפורט 2 · 50532 → 445 [SYN]","In port 2 · 445 → 50532 [SYN, ACK]":"נכנס בפורט 2 · 445 → 50532 [SYN, ACK]","Out port 1 · 445 → 50532 [SYN, ACK]":"יוצא בפורט 1 · 445 → 50532 [SYN, ACK]","In port 1 · 52344 → 443 [SYN] (frame to the router)":"נכנס בפורט 1 · 52344 → 443 [SYN] (מסגרת לנתב)","Out port 8 · 52344 → 443 [SYN]":"יוצא בפורט 8 · 52344 → 443 [SYN]","TTL 127 · 40112 → 443 [SYN] (new frame, after NAT)":"TTL 127 · 40112 → 443 [SYN] (מסגרת חדשה, אחרי NAT)","Seen going into the switch, port 1":"נצפתה נכנסת למתג, פורט 1","Seen leaving the switch, port 2":"נצפתה יוצאת מהמתג, פורט 2","Seen leaving the switch, port 8":"נצפתה יוצאת מהמתג, פורט 8","Seen going into the switch, port 2":"נצפתה נכנסת למתג, פורט 2","Seen leaving the switch, port 1":"נצפתה יוצאת מהמתג, פורט 1","Broadband Logins":"התחברות לפס רחב",Discovery:"גילוי","PPP setup":"הקמת PPP","Home Router":"נתב ביתי","Access Server":"שרת גישה","Point-to-Point Protocol over Ethernet":"פרוטוקול נקודה לנקודה על גבי אתרנט","Many DSL and fibre providers make the home router log in before it gets online. PPPoE is how: the router finds the provider’s access server and opens a session with it, then runs PPP inside, agreeing on the link’s settings, logging in with the username and password from the provider and receiving its public IP address. Every packet then carries an 8-byte PPPoE header.":"ספקי DSL וסיבים רבים מחייבים את הנתב הביתי להתחבר לפני שהוא יוצא לאינטרנט. PPPoE הוא הדרך: הנתב מוצא את שרת הגישה של הספק ופותח איתו הפעלה, ואז מריץ בתוכה PPP, מסכים על הגדרות הקישור, מתחבר עם שם המשתמש והסיסמה מהספק ומקבל את כתובת ה-IP הציבורית שלו. מכאן והלאה כל חבילה נושאת כותרת PPPoE של 8 בתים.","CHAP or PAP":"CHAP או PAP","From IPCP":"מ-IPCP","8 bytes (MTU 1,492)":"8 בתים (MTU 1,492)","Logged in":"מחובר","Found, agreed, checked, addressed":"נמצא, סוכם, נבדק, קיבל כתובת","The router found the provider’s access server, got a session, agreed on the link’s settings, proved its password without sending it and was given its public address. Every packet now travels inside that session, until a PADT ends it. Press REPLAY to watch it again.":"הנתב מצא את שרת הגישה של הספק, קיבל הפעלה, הסכים על הגדרות הקישור, הוכיח את הסיסמה בלי לשלוח אותה וקיבל את הכתובת הציבורית שלו. כעת כל חבילה עוברת בתוך ההפעלה הזו, עד ש-PADT יסיים אותה. לחצו על ״שוב״ כדי לצפות שוב.","17 to get online":"17 עד שמתחברים","Public IP":"IP ציבורי","8 bytes per packet":"8 בתים לכל חבילה","Anyone There?":"יש מישהו?","The router looks for an access server":"הנתב מחפש שרת גישה","The home router is plugged into the provider’s fibre or DSL line. Before it can log in, it has to find the provider’s access server, so it broadcasts a PADI: “PPPoE Active Discovery Initiation”. An access server answers with a PADO, an offer that names it: bng-1.example.net.":"הנתב הביתי מחובר לקו הסיבים או ה-DSL של הספק. לפני שיוכל להתחבר עליו למצוא את שרת הגישה של הספק, ולכן הוא משדר לכולם PADI: ‏“PPPoE Active Discovery Initiation”. שרת גישה עונה ב-PADO, הצעה שמציינת את שמו: bng-1.example.net.","PADI, to everyone":"PADI, לכולם","PADO, from the server":"PADO, מהשרת","Ethernet type":"סוג אתרנט","0x8863 (discovery)":"0x8863 (גילוי)","is there an access server?":"יש שרת גישה?","and a cookie":"ועוגייה","Pick a Server":"בחירת שרת","A session number for the line":"מספר הפעלה לקו","If several servers answered, the router picks one and asks it directly with a PADR, sending back the cookie it was given. The server replies with a PADS carrying a session ID, 0x2f1c. From now on every frame between the two of them carries that number.":"אם כמה שרתים ענו, הנתב בוחר אחד ומבקש ממנו ישירות ב-PADR, ומחזיר את העוגייה שקיבל. השרת עונה ב-PADS שנושא מזהה הפעלה, 0x2f1c. מעכשיו כל מסגרת ביניהם נושאת את המספר הזה.",Confirmed:"אושר","this server, please":"השרת הזה, בבקשה","with its cookie":"עם העוגייה שלו","session ID 0x2f1c":"מזהה הפעלה 0x2f1c","SESSION 0x2F1C":"הפעלה 0x2F1C","Link Settings":"הגדרות הקישור","LCP agrees on size and login":"LCP מסכם גודל והתחברות","Now PPP runs inside the session, starting with LCP. Each side asks for its settings: packets of at most 1,492 bytes, since PPPoE’s 8 bytes have to fit in Ethernet’s 1,500, and a random magic number to spot loops. The server also asks for a CHAP login. Both agree.":"עכשיו PPP רץ בתוך ההפעלה, ומתחיל ב-LCP. כל צד מבקש את ההגדרות שלו: חבילות של 1,492 בתים לכל היותר, כי 8 הבתים של PPPoE צריכים להיכנס ב-1,500 של אתרנט, ומספר קסם אקראי כדי לזהות לולאות. השרת מבקש גם התחברות ב-CHAP. שני הצדדים מסכימים.","Largest packet":"החבילה הגדולה ביותר","1,492 bytes (MRU)":"1,492 בתים (MRU)","CHAP with MD5":"CHAP עם MD5","0x8864 (session)":"0x8864 (הפעלה)","LCP REQUEST":"בקשת LCP","magic number":"מספר קסם","MRU 1492, log in with CHAP":"MRU 1492, התחברות ב-CHAP","LCP ACK":"LCP ACK","A password check without the password":"בדיקת סיסמה בלי הסיסמה","The server sends a random challenge. The router answers with its username, alex@fibre.example, and an MD5 hash of the challenge and its password, so the password itself never crosses the line. The server checks the answer with the provider’s RADIUS server, then says Success.":"השרת שולח אתגר אקראי. הנתב עונה עם שם המשתמש שלו, alex@fibre.example, ועם גיבוב MD5 של האתגר והסיסמה, כך שהסיסמה עצמה אף פעם לא חוצה את הקו. השרת בודק את התשובה מול שרת ה-RADIUS של הספק, ואז עונה Success.",Username:"שם משתמש","A hash, not the password":"גיבוב, לא הסיסמה","The provider’s RADIUS":"ה-RADIUS של הספק","MD5(id, password, challenge)":"MD5(מזהה, סיסמה, אתגר)","CHECKED WITH RADIUS":"נבדק מול RADIUS","Get an Address":"קבלת כתובת","IPCP hands out the public IP":"IPCP מחלק את ה-IP הציבורי","The server first tells the router its own end, 198.51.100.1. The router asks for an address and DNS servers, offering 0.0.0.0: “anything”. The server says no and suggests 198.51.100.7 and two DNS servers. The router asks again with those, and the server agrees.":"קודם השרת מודיע לנתב על הקצה שלו, 198.51.100.1. הנתב מבקש כתובת ושרתי DNS ומציע 0.0.0.0: ״כל דבר״. השרת מסרב ומציע 198.51.100.7 ושני שרתי DNS. הנתב מבקש שוב עם הערכים האלה, והשרת מסכים.","Other end":"הקצה השני","IPCP REQUEST":"בקשת IPCP","my end: 198.51.100.1":"הקצה שלי: 198.51.100.1","address? 0.0.0.0":"כתובת? 0.0.0.0","IPCP ACK":"IPCP ACK","IPCP NAK":"IPCP NAK","use 198.51.100.7":"קח 198.51.100.7","198.51.100.7, please":"‎198.51.100.7, בבקשה",agreed:"מוסכם","Every packet in an 8-byte wrapper":"כל חבילה בעטיפה של 8 בתים","The laptop opens a website. The router swaps in its public address (NAT) and sends the packet inside the session: a 6-byte PPPoE header, then 2 bytes saying “IPv4”. It also lowers the MSS the laptop offered from 1460 to 1452, so the replies fit in 1,492 bytes.":"המחשב הנייד פותח אתר. הנתב מכניס את הכתובת הציבורית שלו (NAT) ושולח את החבילה בתוך ההפעלה: כותרת PPPoE של 6 בתים, ואחריה 2 בתים שאומרים ״IPv4״. הוא גם מוריד את ה-MSS שהמחשב הציע מ-1460 ל-1452, כדי שהתשובות ייכנסו ב-1,492 בתים.",Wrapper:"עטיפה","6 + 2 bytes":"6 + 2 בתים","1460 → 1452 (clamped)":"1460 → 1452 (מוגבל)","in session 0x2f1c":"בהפעלה 0x2f1c","MSS now 1452":"MSS עכשיו 1452","Seen on the router’s line to the provider":"נצפתה על הקו של הנתב אל הספק","PPPoE PADI · 18 bytes":"PPPoE PADI · 18 בתים","PADI, 2 tags":"PADI, 2 תגיות","Broadcast: everything on the line receives it.":"שידור לכולם: כל מה שעל הקו מקבל אותה.","0x8863 (PPPoE discovery)":"0x8863 (גילוי PPPoE)","Version, type":"גרסה, סוג","Active Discovery Initiation: is there an access server out there?":"Active Discovery Initiation: יש שם בחוץ שרת גישה?","0 (none yet)":"0 (עוד אין)","What follows this header.":"מה שבא אחרי הכותרת הזו.","The service the router wants; empty means any.":"השירות שהנתב רוצה; ריק פירושו כל שירות.","Type, length":"סוג, אורך","A value the router made up. Answers carry it back, so the router can match them to its request.":"ערך שהנתב המציא. התשובות מחזירות אותו, כדי שהנתב יוכל להתאים אותן לבקשה שלו.","PPPoE PADO · 59 bytes":"PPPoE PADO · 59 בתים","PADO, 4 tags":"PADO, 4 תגיות","The access server’s port.":"הפורט של שרת הגישה.","Active Discovery Offer: an access server answers.":"Active Discovery Offer: שרת גישה עונה.","The access server’s name.":"השם של שרת הגישה.","A value the server will recognise when the router asks for it again, so floods of fake requests cost it nothing.":"ערך שהשרת יזהה כשהנתב יבקש אותו שוב, כך ששטף של בקשות מזויפות לא עולה לו כלום.","PPPoE PADR · 38 bytes":"PPPoE PADR · 38 בתים","PADR, 3 tags":"PADR, 3 תגיות","The access server that answered.":"שרת הגישה שענה.","Active Discovery Request: the router picks this server.":"Active Discovery Request: הנתב בוחר בשרת הזה.","PPPoE PADS · 18 bytes":"PPPoE PADS · 18 בתים","PADS, 2 tags":"PADS, 2 תגיות","Active Discovery Session-confirmation: here is the session ID.":"Active Discovery Session-confirmation: הנה מזהה ההפעלה.","Given by the server in its PADS; every frame of the session carries it.":"ניתן על ידי השרת ב-PADS שלו; כל מסגרת בהפעלה נושאת אותו.","PPPoE · 6 bytes":"PPPoE · 6 בתים","PPP LCP Configure-Request · 16 bytes":"PPP LCP Configure-Request · 16 בתים","0x8864 (PPPoE session)":"0x8864 (הפעלת PPPoE)","0x00 (Session)":"0x00 (הפעלה)","Session data: one PPP packet.":"נתוני הפעלה: חבילת PPP אחת.","Link Control Protocol: the link’s settings.":"Link Control Protocol: הגדרות הקישור.","The settings this side wants.":"ההגדרות שהצד הזה רוצה.","The answer carries the same number.":"התשובה נושאת את אותו מספר.","The largest packet this side will take: 1,500 bytes of Ethernet minus PPPoE’s 8.":"החבילה הגדולה ביותר שהצד הזה יקבל: 1,500 בתים של אתרנט פחות 8 של PPPoE.","Random. Seeing its own number come back would mean the line loops back on itself.":"אקראי. אם המספר של עצמו חוזר אליו, סימן שהקו חוזר אל עצמו בלולאה.","PPP LCP Configure-Request · 21 bytes":"PPP LCP Configure-Request · 21 בתים","How the server wants the router to log in.":"איך השרת רוצה שהנתב יתחבר.","PPP LCP Configure-Ack · 16 bytes":"PPP LCP Configure-Ack · 16 בתים","Every setting accepted, exactly as asked.":"כל ההגדרות התקבלו, בדיוק כפי שהתבקשו.","The number of the request this answers.":"מספר הבקשה שעליה זה עונה.","PPP LCP Configure-Ack · 21 bytes":"PPP LCP Configure-Ack · 21 בתים","PPP CHAP Challenge · 40 bytes":"PPP CHAP Challenge · 40 בתים","Challenge Handshake Authentication Protocol: the login.":"Challenge Handshake Authentication Protocol: ההתחברות.","A random value for the router to prove its password with.":"ערך אקראי שבעזרתו הנתב מוכיח את הסיסמה שלו.","The response must carry the same number.":"התשובה חייבת לשאת את אותו מספר.","Value size":"גודל הערך","Random, new for every login.":"אקראי, חדש בכל התחברות.","The server’s name.":"השם של השרת.","PPP CHAP Response · 41 bytes":"PPP CHAP Response · 41 בתים","The proof, and who is logging in.":"ההוכחה, ומי מתחבר.","The number of the challenge this answers.":"מספר האתגר שעליו זה עונה.","MD5 of the identifier, the password and the challenge: it proves the password without sending it.":"MD5 של המזהה, הסיסמה והאתגר: מוכיח את הסיסמה בלי לשלוח אותה.","The username the provider gave.":"שם המשתמש שהספק נתן.","PPP CHAP Success · 13 bytes":"PPP CHAP Success · 13 בתים","The login worked.":"ההתחברות הצליחה.","Text for people to read; any words will do.":"טקסט לקריאה של בני אדם; כל מילים יתאימו.","PPP IPCP Configure-Request · 12 bytes":"PPP IPCP Configure-Request · 12 בתים","IP Control Protocol: the IP address and DNS servers.":"IP Control Protocol: כתובת ה-IP ושרתי ה-DNS.","The address of the server’s end of the link.":"הכתובת של קצה השרת בקישור.","PPP IPCP Configure-Request · 24 bytes":"PPP IPCP Configure-Request · 24 בתים","Zero: “please give me an address”.":"אפס: ״תן לי כתובת, בבקשה״.","Zero: “which DNS server should I use?”":"אפס: ״באיזה שרת DNS להשתמש?״","PPP IPCP Configure-Ack · 12 bytes":"PPP IPCP Configure-Ack · 12 בתים","PPP IPCP Configure-Nak · 24 bytes":"PPP IPCP Configure-Nak · 24 בתים","Not these values: here are ones that would be accepted.":"לא הערכים האלה: הנה ערכים שיתקבלו.","The address for the router.":"הכתובת בשביל הנתב.","PPP IPCP Configure-Ack · 24 bytes":"PPP IPCP Configure-Ack · 24 בתים","PPP · 2 bytes":"PPP · 2 בתים","An IPv4 packet follows.":"אחריו באה חבילת IPv4.","Lowered from 1460 by the router, so packets back fit in the 1,492 bytes PPPoE leaves.":"הנתב הוריד אותו מ-1460, כדי שחבילות חוזרות ייכנסו ב-1,492 הבתים ש-PPPoE משאיר.","Internet phone calls":"שיחות טלפון באינטרנט","IP camera streams":"שידורי מצלמות IP","Live streaming upload":"העלאת שידור חי","Multicast and TV channels":"ריבוי שידור וערוצי טלוויזיה","IP Camera":"מצלמת IP","TV Box":"ממיר טלוויזיה",Camera:"מצלמה","Internet Phone Calls":"שיחות טלפון באינטרנט","Voice (RTP)":"קול (RTP)","SIP Server":"שרת SIP","Bob’s Router":"הנתב של Bob","Session Initiation Protocol":"פרוטוקול ייזום הפעלה","SIP sets up phone calls over the internet: office desk phones, phone apps and the providers behind them. A phone signs in with its provider’s SIP server. To call someone it sends an INVITE; the other phone rings and answers, and the two agree on how to send the voice, which then flows as RTP. The messages are plain text, a lot like HTTP.":"SIP מקים שיחות טלפון דרך האינטרנט: טלפונים שולחניים במשרד, אפליקציות טלפון והספקים שמאחוריהם. טלפון נכנס לשרת ה-SIP של הספק שלו. כדי להתקשר למישהו הוא שולח INVITE; הטלפון השני מצלצל ועונה, ושניהם מסכימים איך לשלוח את הקול, שזורם אחר כך כ-RTP. ההודעות הן טקסט פשוט, דומה מאוד ל-HTTP.","UDP or TCP 5060":"UDP או TCP 5060","Call setup":"הקמת השיחה",Voice:"קול","RTP, described by SDP":"RTP, מתואר ב-SDP","Codec here":"הקודק כאן","Call ended":"השיחה הסתיימה","Signed in, rang, talked, hung up":"נרשם, צלצל, דיבר, ניתק","Alice’s phone signed in with a password it never sent, invited Bob’s phone through the SIP server, heard it ring, and talked over RTP until Bob hung up with a BYE. SIP only set the call up and took it down; the voice travelled as packets of its own. Press REPLAY to watch it again.":"הטלפון של Alice נכנס עם סיסמה שמעולם לא שלח, הזמין את הטלפון של Bob דרך שרת ה-SIP, שמע אותו מצלצל ודיבר ב-RTP עד ש-Bob ניתק עם BYE. SIP רק הקים את השיחה וסיים אותה; הקול עבר בחבילות משלו. לחצו על ״שוב״ כדי לצפות שוב.","50 packets a second each way":"50 חבילות בשנייה לכל כיוון",Through:"דרך","The provider’s server":"השרת של הספק","No (SIPS and SRTP add it)":"לא (SIPS ו-SRTP מוסיפים)","Sign In":"התחברות","The phone tells the server where it is":"הטלפון אומר לשרת איפה הוא","Alice’s phone, an app on her laptop, registers with her provider’s SIP server: alice@example.net can be reached here. The server answers 401 with a challenge, so the phone asks again with a hash made from the challenge and its password. 200 OK: registered for an hour.":"הטלפון של Alice, אפליקציה במחשב הנייד שלה, נרשם בשרת ה-SIP של הספק שלה: אפשר להשיג את alice@example.net כאן. השרת עונה 401 עם אתגר, אז הטלפון מבקש שוב עם גיבוב שנוצר מהאתגר ומהסיסמה. 200 OK: רשום לשעה.","Good for":"בתוקף ל","3600 s, then again":"3600 s, ואז שוב","is here":"נמצא כאן","with a challenge":"עם אתגר","again, with a hash":"שוב, עם גיבוב",registered:"נרשם","Call Bob":"להתקשר ל-Bob","An INVITE, passed on by the server":"INVITE שהשרת מעביר הלאה","Alice calls bob@example.net. Her INVITE carries SDP: G.711 audio, sent to her phone. The server answers 100 Trying, finds where Bob’s phone registered and passes the INVITE on, with its own Via and Record-Route and its own address in the SDP: the voice will go through it.":"Alice מתקשרת ל-bob@example.net. ה-INVITE שלה נושא SDP: שמע G.711, שיישלח לטלפון שלה. השרת עונה 100 Trying, מוצא איפה הטלפון של Bob נרשם ומעביר את ה-INVITE הלאה, עם Via ו-Record-Route משלו והכתובת שלו ב-SDP: הקול יעבור דרכו.","Offer (SDP)":"הצעה (SDP)","G.711, port 49170":"G.711, פורט 49170","Stops Alice resending":"Alice מפסיקה לשלוח שוב","call bob@example.net":"להתקשר ל-bob@example.net","SDP: G.711 audio":"SDP: שמע G.711","passed on to Bob":"הועבר ל-Bob","voice via the server":"קול דרך השרת",Ringing:"מצלצל","The answer retraces the route":"התשובה חוזרת באותה דרך","Bob’s phone starts ringing and says so: 180 Ringing. Responses follow the Via headers back the way the request came, so it goes to the server, which removes its own Via and passes it on to Alice. Her phone plays the ringing tone.":"הטלפון של Bob מתחיל לצלצל ואומר זאת: 180 Ringing. תשובות עוקבות אחרי כותרות ה-Via בחזרה בדרך שבה הגיעה הבקשה, לכן היא הולכת לשרת, שמסיר את ה-Via שלו ומעביר אותה ל-Alice. הטלפון שלה משמיע צליל חיוג.","Route back":"דרך חזרה","The Via headers, in reverse":"כותרות ה-Via, בסדר הפוך","Alice hears":"Alice שומעת","The ringing tone":"צליל החיוג","Bob’s phone rings":"הטלפון של Bob מצלצל","to Alice":"אל Alice",Answered:"נענתה","200 OK, then ACK":"200 OK, ואז ACK","Bob picks up. His 200 OK carries his SDP answer: G.711, sent to his phone. The server swaps in its own address again before passing it to Alice. Her phone confirms with an ACK, which the server passes to Bob. The call is set up.":"Bob עונה. ה-200 OK שלו נושא את תשובת ה-SDP שלו: G.711, שיישלח לטלפון שלו. השרת שוב מכניס את הכתובת שלו לפני שהוא מעביר אותה ל-Alice. הטלפון שלה מאשר ב-ACK, שהשרת מעביר ל-Bob. השיחה הוקמה.","Answer (SDP)":"תשובה (SDP)","G.711, port 49172":"G.711, פורט 49172","Confirmed by":"מאושר ב-","Voice goes to":"הקול הולך אל","The server, ports 40000, 40002":"השרת, פורטים 40000, 40002","Bob answers":"Bob עונה",answered:"נענתה",Talking:"מדברים","Voice flows as RTP":"הקול זורם כ-RTP","Now the voice: every 20 ms each phone sends an RTP packet with 160 bytes of G.711 sound, a sequence number and a timestamp, over UDP. They go to the server, which passes them on to the other phone. SIP stays quiet while they talk.":"עכשיו הקול: כל 20 ms כל טלפון שולח חבילת RTP עם 160 בתים של צליל G.711, מספר רצף וחותמת זמן, דרך UDP. הן הולכות לשרת, שמעביר אותן לטלפון השני. SIP שותק בזמן שהם מדברים.",Every:"כל","20 ms, 160 bytes of sound":"20 ms, 160 בתים של צליל","Carried by":"נישא ב-","RTP over UDP":"RTP מעל UDP","SIP meanwhile":"SIP בינתיים","Nothing to say":"אין מה לומר",VOICE:"קול","20 ms of Alice":"20 ms של Alice","20 ms of Bob":"20 ms של Bob","Hang Up":"ניתוק","BYE, and 200 OK":"BYE, ו-200 OK","Bob hangs up: his phone sends BYE, routed through the server as the Record-Route asked, and Alice’s phone answers 200 OK. Both stop sending voice. The call took four kinds of request; the voice itself was never part of SIP.":"Bob מנתק: הטלפון שלו שולח BYE, שמנותב דרך השרת כפי שביקש ה-Record-Route, והטלפון של Alice עונה 200 OK. שניהם מפסיקים לשלוח קול. השיחה דרשה ארבעה סוגי בקשות; הקול עצמו מעולם לא היה חלק מ-SIP.","No more RTP":"אין עוד RTP","Bob hangs up":"Bob מנתק","1, 0 (PCMU: G.711 μ-law, the classic phone codec)":"1, 0 (PCMU: ‏G.711 μ-law, קודק הטלפון הקלאסי)","Audio clock at 8,000 per second: +160 per 20 ms of sound.":"שעון שמע של 8000 בשנייה: ‎+160 לכל 20 ms של צליל.","160 bytes of G.711 audio (20 ms, one byte per sample)":"160 בתים של שמע G.711 (‏20 ms, בית אחד לדגימה)","IP Camera Streams":"שידורי מצלמות IP","Video (RTP)":"וידאו (RTP)","Real Time Streaming Protocol":"פרוטוקול הזרמה בזמן אמת","RTSP is how video players, recorders and security apps get live video from IP cameras. It works like a remote control: the player asks what the camera offers, sets up a stream, and says PLAY and later TEARDOWN, in text messages much like HTTP. The video itself doesn’t travel in RTSP: it flows separately as RTP, here over UDP.":"RTSP הוא הדרך שבה נגני וידאו, מקליטים ואפליקציות אבטחה מקבלים וידאו חי ממצלמות IP. הוא עובד כמו שלט רחוק: הנגן שואל מה המצלמה מציעה, מכין זרם, ואומר PLAY ומאוחר יותר TEARDOWN, בהודעות טקסט דומות מאוד ל-HTTP. הווידאו עצמו לא עובר ב-RTSP: הוא זורם בנפרד כ-RTP, כאן מעל UDP.",Controls:"פקודות",Watched:"נצפה","Described, set up, played, stopped":"תואר, הוכן, הופעל, נעצר","VLC asked the camera what it had, logged in with a hash of its password, set up one video track and pressed PLAY. The video came as RTP packets on ports of its own, a key frame in three pieces, until TEARDOWN ended the session. Press REPLAY to watch it again.":"VLC שאל את המצלמה מה יש לה, התחבר עם גיבוב של הסיסמה שלו, הכין רצועת וידאו אחת ולחץ PLAY. הווידאו הגיע כחבילות RTP בפורטים משלו, פריים מפתח בשלושה חלקים, עד ש-TEARDOWN סיים את ההפעלה. לחצו על ״שוב״ כדי לצפות שוב.","6 on one TCP connection":"6 בחיבור TCP אחד","Key frame":"פריים מפתח","Split into 3 packets":"מחולק ל-3 חבילות","1185d200, 60 s timeout":"1185d200, פג אחרי 60 s","What Can You Do?":"מה אתה יודע לעשות?","OPTIONS over a TCP connection":"OPTIONS בחיבור TCP","VLC opens rtsp://192.168.1.64/stream1. It connects to the camera on TCP port 554 and starts with OPTIONS: which commands do you support? The camera lists them. As in HTTP, every request and reply is text; a CSeq header numbers them.":"VLC פותח את rtsp://192.168.1.64/stream1. הוא מתחבר למצלמה בפורט TCP ‏554 ומתחיל ב-OPTIONS: אילו פקודות אתה תומך? המצלמה מונה אותן. כמו ב-HTTP, כל בקשה ותשובה הן טקסט; כותרת CSeq ממספרת אותן.","Numbered by":"ממוספר ב-","what can you do?":"מה אתה יודע לעשות?","Describe the Stream":"תיאור הזרם","SDP says what the video is":"SDP אומר מה הווידאו","DESCRIBE asks for the stream’s description. The camera wants a login first: 401, with a digest challenge. VLC asks again with a hash of the password, and the reply carries SDP: one H.264 video track, RTP payload type 96, with a 90 kHz clock.":"DESCRIBE מבקש את תיאור הזרם. המצלמה רוצה קודם התחברות: 401, עם אתגר digest. VLC מבקש שוב עם גיבוב של הסיסמה, והתשובה נושאת SDP: רצועת וידאו H.264 אחת, סוג מטען RTP ‏96, עם שעון של 90 kHz.","Digest: a hash":"Digest: גיבוב","H.264, payload type 96":"H.264, סוג מטען 96",Track:"רצועה","describe stream1":"תאר את stream1","log in first":"קודם התחבר","SDP: H.264 video":"SDP: וידאו H.264","track 1":"רצועה 1","Set Up":"הכנה","Agree on ports for the video":"הסכמה על פורטים לווידאו","SETUP for trackID=1 says how to deliver it: RTP over UDP, to the laptop’s ports 50000 (video) and 50001 (RTCP reports). The camera agrees, picks its own ports, 6970 and 6971, and opens a session, 1185d200, that every later request names.":"SETUP עבור trackID=1 אומר איך למסור אותה: RTP מעל UDP, לפורטים 50000 (וידאו) ו-50001 (דוחות RTCP) של המחשב הנייד. המצלמה מסכימה, בוחרת פורטים משלה, 6970 ו-6971, ופותחת הפעלה, 1185d200, שכל בקשה בהמשך מציינת.","Laptop ports":"פורטים של הנייד","track 1, RTP over UDP":"רצועה 1, RTP מעל UDP","to ports 50000-50001":"לפורטים 50000-50001","session 1185d200":"הפעלה 1185d200","from ports 6970-6971":"מפורטים 6970-6971",Play:"ניגון","The remote control’s PLAY button":"כפתור ה-PLAY של השלט","PLAY starts the stream from now (npt=0.000-). The reply tells VLC which RTP sequence number and timestamp come first, so it can line the video up. From here on, the video doesn’t travel in RTSP at all.":"PLAY מתחיל את הזרם מעכשיו (npt=0.000-). התשובה אומרת ל-VLC איזה מספר רצף וחותמת זמן של RTP מגיעים ראשונים, כדי שיוכל לסדר את הווידאו. מכאן והלאה הווידאו לא עובר ב-RTSP בכלל.",Range:"טווח","From now":"מעכשיו","First packet":"חבילה ראשונה","Video arrives":"הווידאו מגיע","On the UDP ports":"בפורטי ה-UDP","play from now":"נגן מעכשיו",playing:"מתנגן","Video Arrives":"הווידאו מגיע","A key frame in RTP packets":"פריים מפתח בחבילות RTP","The camera sends a key frame, a whole picture, in three RTP packets: H.264 fragments marked first, middle and last, with the marker bit on the last. All three carry the same 90 kHz timestamp. Smaller frames holding only the changes follow, 25 a second.":"המצלמה שולחת פריים מפתח, תמונה שלמה, בשלוש חבילות RTP: מקטעי H.264 שמסומנים כראשון, אמצעי ואחרון, עם ביט הסימון באחרון. שלושתם נושאים אותה חותמת זמן של 90 kHz. אחריהם באים פריימים קטנים יותר עם השינויים בלבד, 25 בשנייה.",Packets:"חבילות","3 for one key frame":"3 לפריים מפתח אחד","Same for the whole frame":"זהה לכל הפריים",Frames:"פריימים","25 a second":"25 בשנייה","a key frame in 3 packets":"פריים מפתח ב-3 חבילות",Stop:"עצירה","TEARDOWN ends the session":"TEARDOWN מסיים את ההפעלה","When the viewer closes the stream, VLC sends TEARDOWN with the session ID. The camera stops sending video and confirms. Had VLC simply vanished, the camera would stop anyway once 60 seconds passed without a word from it.":"כשהצופה סוגר את הזרם, VLC שולח TEARDOWN עם מזהה ההפעלה. המצלמה מפסיקה לשלוח וידאו ומאשרת. אילו VLC פשוט נעלם, המצלמה הייתה נעצרת בכל מקרה אחרי 60 שניות בלי מילה ממנו.",Ended:"הסתיימה",Otherwise:"אחרת","Timeout after 60 s":"פג אחרי 60 s","stop session 1185d200":"עצור את הפעלה 1185d200",stopped:"נעצר","The camera. It is on the same network, so the frame goes straight to it, not through the router.":"המצלמה. היא באותה רשת, לכן המסגרת הולכת ישר אליה, לא דרך הנתב.","The camera’s network port.":"פורט הרשת של המצלמה.","RTP + video":"RTP + וידאו","0, 96 (H.264, as the camera’s description said)":"0, 96 (H.264, כפי שאמר התיאור של המצלמה)","Marker clear: more of this frame follows.":"סימון כבוי: עוד מהפריים הזה בדרך.","Video clock at 90,000 per second; every packet of one frame has the same value.":"שעון וידאו של 90,000 בשנייה; כל חבילות הפריים נושאות אותו ערך.","Identifies this video stream.":"מזהה את זרם הווידאו הזה.","FU indicator":"מחוון FU","0x7c (fragment of a frame)":"0x7c (מקטע של פריים)","Fragmentation unit: one piece of a frame too big for one packet.":"יחידת פיצול: חלק מפריים גדול מדי לחבילה אחת.","FU header":"כותרת FU","0x85 (first piece of a key frame)":"0x85 (החלק הראשון של פריים מפתח)","Type 5: a key frame (IDR), a whole picture the decoder can start from.":"סוג 5: פריים מפתח (IDR), תמונה שלמה שהמפענח יכול להתחיל ממנה.","1398 bytes of the key frame":"‏1398 בתים של פריים המפתח","0x05 (middle piece of a key frame)":"0x05 (החלק האמצעי של פריים מפתח)","1, 96 (H.264, as the camera’s description said)":"1, 96 (H.264, כפי שאמר התיאור של המצלמה)","Marker set: the last packet of a frame.":"סימון דלוק: החבילה האחרונה של פריים.","0x45 (last piece of a key frame)":"0x45 (החלק האחרון של פריים מפתח)","900 bytes of the key frame":"‏900 בתים של פריים המפתח","Multicast TV":"טלוויזיה בריבוי שידור","Joins and leaves":"הצטרפויות ועזיבות","Channel 1":"ערוץ 1","TV channels":"ערוצי טלוויזיה","Internet Group Management Protocol":"פרוטוקול ניהול קבוצות אינטרנט","Multicast sends one stream to a group address, and the network copies it only where it’s wanted: it’s how internet providers deliver live TV channels. IGMP is how a device tells its router which groups it wants. Switches listen in (IGMP snooping), so each stream reaches only the ports that asked for it.":"ריבוי שידור שולח זרם אחד לכתובת קבוצה, והרשת מעתיקה אותו רק לאן שרוצים אותו: כך ספקי אינטרנט מעבירים ערוצי טלוויזיה חיים. IGMP הוא הדרך שבה מכשיר אומר לנתב שלו אילו קבוצות הוא רוצה. מתגים מקשיבים (IGMP snooping), כך שכל זרם מגיע רק לפורטים שביקשו אותו.","IP protocol 2":"פרוטוקול IP ‏2",Groups:"קבוצות","Version here":"הגרסה כאן","Tuned In":"מכוונן","Joined, copied, checked, left":"הצטרף, הועתק, נבדק, עזב","The TV box and then the laptop joined channel 1 with IGMP reports. The router joined once for the whole home, and the switch, listening in, copied the channel only to the ports that wanted it. Queries kept it flowing, and when the laptop left, the TV box’s answer kept it on. Press REPLAY to watch it again.":"הממיר ואחריו המחשב הנייד הצטרפו לערוץ 1 בדוחות IGMP. הנתב הצטרף פעם אחת בשביל כל הבית, והמתג, שהקשיב, העתיק את הערוץ רק לפורטים שרצו אותו. התשאולים שמרו עליו זורם, וכשהנייד עזב, התשובה של הממיר השאירה אותו דולק. לחצו על ״שוב״ כדי לצפות שוב.",Upstream:"כלפי הספק","One stream for the home":"זרם אחד לכל הבית","Copies to ports that joined":"עותקים לפורטים שהצטרפו","Every 125 s":"כל 125 s","Pick a Channel":"בחירת ערוץ","The TV box joins a group":"הממיר מצטרף לקבוצה","The viewer picks channel 1. Each channel is a multicast group, here 233.252.0.1, and the TV box sends an IGMP Membership Report to that address: I want this group. The switch listens in (IGMP snooping), notes port 2, and passes the report to the router alone.":"הצופה בוחר בערוץ 1. כל ערוץ הוא קבוצת ריבוי שידור, כאן 233.252.0.1, והממיר שולח IGMP Membership Report לכתובת הזאת: אני רוצה את הקבוצה הזאת. המתג מקשיב (IGMP snooping), רושם את פורט 2 ומעביר את הדוח רק לנתב.","Switch notes":"המתג רושם","Port 2 wants it":"פורט 2 רוצה אותו","233.252.0.1, please":"233.252.0.1, בבקשה","to the router port only":"רק לפורט של הנתב","Ask the Provider":"לבקש מהספק","The router joins for the home":"הנתב מצטרף בשביל הבית","The router is an IGMP proxy: it joins the group on its internet side with a report of its own, from its public address, and the provider’s network starts sending channel 1 down the line. However many screens at home tune in, the router joins only once.":"הנתב הוא פרוקסי IGMP: הוא מצטרף לקבוצה בצד האינטרנט שלו עם דוח משלו, מהכתובת הציבורית שלו, ורשת הספק מתחילה לשלוח את ערוץ 1 בקו. לא משנה כמה מסכים בבית צופים, הנתב מצטרף רק פעם אחת.","Router role":"תפקיד הנתב","IGMP proxy":"פרוקסי IGMP",Joins:"מצטרף","Once for the whole home":"פעם אחת לכל הבית","for the whole home":"בשביל כל הבית","The Channel Flows":"הערוץ זורם","Sent only where it was asked for":"נשלח רק לאן שביקשו","The provider’s TV server sends channel 1 to 233.252.0.1: UDP datagrams holding seven 188-byte MPEG-TS packets of video and audio each. The router passes them in, and the switch sends them out of port 2 alone: only the TV box joined, so the laptop gets none.":"שרת הטלוויזיה של הספק שולח את ערוץ 1 ל-233.252.0.1: דאטגרמות UDP שכל אחת נושאת שבע חבילות MPEG-TS של 188 בתים של וידאו ושמע. הנתב מכניס אותן, והמתג מוציא אותן רק מפורט 2: רק הממיר הצטרף, לכן הנייד לא מקבל אף אחת.",Datagram:"דאטגרמה","UDP, 1,316 bytes of TV":"UDP, ‏1,316 בתים של טלוויזיה",Holds:"מכילה","7 MPEG-TS packets":"7 חבילות MPEG-TS","CHANNEL 1":"ערוץ 1","MPEG-TS over UDP":"MPEG-TS מעל UDP","passed into the home":"הוכנס לבית","port 2 only":"רק פורט 2","A Second Screen":"מסך שני","The laptop tunes in too":"גם המחשב הנייד מצטרף","The laptop opens channel 1 in VLC and sends its own report. The switch adds port 1 and now makes two copies of every datagram. The router already gets the channel, so it asks the provider for nothing: one stream still comes down the line.":"המחשב הנייד פותח את ערוץ 1 ב-VLC ושולח דוח משלו. המתג מוסיף את פורט 1 ומעכשיו מכין שני עותקים של כל דאטגרמה. הנתב כבר מקבל את הערוץ, לכן הוא לא מבקש דבר מהספק: בקו עדיין מגיע זרם אחד.","Switch sends to":"המתג שולח אל","Ports 1 and 2":"פורטים 1 ו-2","Still one stream":"עדיין זרם אחד","Router asks":"הנתב מבקש","Nothing new":"שום דבר חדש","the same one stream":"אותו זרם אחד","copied to ports 1 and 2":"הועתק לפורטים 1 ו-2","Still Watching?":"עדיין צופים?","The router checks regularly":"הנתב בודק באופן קבוע","Every 125 seconds the router sends a General Query to 224.0.0.1, every device: which groups do you still want? The switch passes it to every port. Each member answers at a random moment within 10 seconds, so the router and the switch keep the channel coming.":"כל 125 שניות הנתב שולח General Query ל-224.0.0.1, כל המכשירים: אילו קבוצות אתם עדיין רוצים? המתג מעביר אותה לכל הפורטים. כל חבר עונה ברגע אקראי בתוך 10 שניות, כך שהנתב והמתג ממשיכים להזרים את הערוץ.","125 seconds":"125 שניות","224.0.0.1, all devices":"224.0.0.1, כל המכשירים","Answer within":"תשובה בתוך","10 seconds":"10 שניות",QUERY:"תשאול","any groups wanted?":"אילו קבוצות רצויות?","to every port":"לכל פורט",REPORT:"דוח","still watching":"עדיין צופה",Leave:"עזיבה","The laptop stops watching":"הנייד מפסיק לצפות","Closing VLC sends a Leave Group to 224.0.0.2, all routers. Others may still watch, so the router asks about that group alone and waits 1 second. The TV box answers, so the channel stays; the switch just stops sending it to port 1.":"סגירת VLC שולחת Leave Group ל-224.0.0.2, כל הנתבים. ייתכן שאחרים עדיין צופים, אז הנתב שואל רק על הקבוצה הזאת ומחכה שנייה אחת (1 s). הממיר עונה, אז הערוץ נשאר; המתג רק מפסיק לשלוח אותו לפורט 1.","Leave sent to":"העזיבה נשלחת אל","224.0.0.2, all routers":"224.0.0.2, כל הנתבים","About that group alone":"רק על הקבוצה הזאת","Stays: the TV box answered":"נשאר: הממיר ענה",LEAVE:"עזיבה","done with 233.252.0.1":"סיימתי עם 233.252.0.1","anyone for 233.252.0.1?":"מישהו רוצה את 233.252.0.1?","to the ports that joined":"לפורטים שהצטרפו","Multicast: 01:00:5e, then the last 23 bits of the group address. Network cards listen for the groups their system has joined.":"ריבוי שידור: ‏01:00:5e, ואחריו 23 הביטים האחרונים של כתובת הקבוצה. כרטיסי רשת מאזינים לקבוצות שהמערכת שלהם הצטרפה אליהן.","The TV box’s network port.":"פורט הרשת של הממיר.","4, 24 bytes":"4, 24 בתים","IPv4, with one 4-byte option.":"IPv4, עם אפשרות אחת של 4 בתים.","48 (network control), 0":"48 (בקרת רשת), 0","Marked as network control, so it is sent ahead of ordinary traffic.":"מסומן כבקרת רשת, ולכן נשלח לפני תעבורה רגילה.","Always 1: IGMP never goes past the first router.":"תמיד 1: IGMP אף פעם לא עובר את הנתב הראשון.","A multicast group address.":"כתובת קבוצת ריבוי שידור.","Router Alert option":"אפשרות Router Alert","Asks every router on the way to look inside, though the packet isn’t addressed to it.":"מבקש מכל נתב בדרך להציץ פנימה, אף שהחבילה לא ממוענת אליו.","This device wants the group’s traffic.":"המכשיר הזה רוצה את התעבורה של הקבוצה.","Max response time":"זמן תגובה מרבי","Only queries use it.":"רק תשאולים משתמשים בו.","Covers the IGMP message.":"מכסה את הודעת ה-IGMP.","Group address":"כתובת הקבוצה","The multicast group: one TV channel.":"קבוצת ריבוי השידור: ערוץ טלוויזיה אחד.","Seen arriving on the router’s internet side":"נצפתה מגיעה לצד האינטרנט של הנתב","MPEG-TS · 7 packets":"MPEG-TS · ‏7 חבילות","The provider’s router, passing the channel on.":"הנתב של הספק, שמעביר את הערוץ הלאה.","Sync byte":"בית סנכרון","Every transport stream packet starts with 0x47, so the receiver can find where packets begin.":"כל חבילת transport stream מתחילה ב-0x47, כדי שהמקבל ימצא איפה חבילות מתחילות.","Flags, PID":"דגלים, PID","0x0100 (PID 256: video)":"0x0100 (‏PID 256: וידאו)","Which stream the packet belongs to: the channel’s video, its audio, or the tables that list them.":"לאיזה זרם החבילה שייכת: הווידאו של הערוץ, השמע שלו או הטבלאות שמפרטות אותם.","Payload, counter":"מטען, מונה","0x14 (payload only, counter 4)":"0x14 (מטען בלבד, מונה 4)","Counts 0 to 15 for each PID, so a lost packet shows up as a gap.":"סופר מ-0 עד 15 לכל PID, כך שחבילה שאבדה נראית כפער.","184 bytes of the channel’s video":"‏184 בתים מהווידאו של הערוץ","More packets":"עוד חבילות","6 × 188 bytes: video and audio":"6 × 188 בתים: וידאו ושמע","Six more transport stream packets, each with its own 4-byte header.":"עוד שש חבילות transport stream, לכל אחת כותרת משלה של 4 בתים.","Seen going into the switch, port 8":"נצפתה נכנסת למתג, פורט 8","The router, passing the channel into the home.":"הנתב, שמעביר את הערוץ לתוך הבית.","0x19 (payload only, counter 9)":"0x19 (מטען בלבד, מונה 9)","The router asks: which groups does anyone here still want?":"הנתב שואל: אילו קבוצות מישהו כאן עדיין רוצה?","Members answer at a random moment within this time, so their answers don’t all arrive at once.":"חברים עונים ברגע אקראי בתוך הזמן הזה, כדי שהתשובות לא יגיעו כולן בבת אחת.","Zero in a general query: every group.":"אפס בתשאול כללי: כל הקבוצות.","This device no longer wants the group.":"המכשיר הזה כבר לא רוצה את הקבוצה.","The router asks: does anyone still want this group?":"הנתב שואל: מישהו עדיין רוצה את הקבוצה הזאת?","Live Streaming Upload":"העלאת שידור חי","RTMP handshake":"לחיצת יד של RTMP","Video and audio":"וידאו ושמע","Ingest Server":"שרת קליטה","Real-Time Messaging Protocol":"פרוטוקול הודעות בזמן אמת","RTMP is how most streamers send live video to a platform: OBS and other apps push it to an ingest server, which turns it into streams for viewers. Made for Flash, it outlived Flash as the way to upload. Everything shares one TCP connection: commands, audio and video, cut into chunks.":"RTMP הוא הדרך שבה רוב המשדרים שולחים וידאו חי לפלטפורמה: OBS ואפליקציות אחרות דוחפים אותו לשרת קליטה, שהופך אותו לשידורים לצופים. הוא נבנה בשביל Flash ושרד אותו כדרך להעלאה. הכול חולק חיבור TCP אחד: פקודות, שמע ווידאו, חתוכים לנתחים.","H.264 video, AAC audio":"וידאו H.264, שמע AAC","Encoded in AMF0":"מקודד ב-AMF0","Secure version":"גרסה מאובטחת","RTMPS, over TLS":"RTMPS, מעל TLS","Adobe specification (2012)":"מפרט של Adobe ‏(2012)",Live:"בשידור","Connected, published, streamed":"התחבר, פרסם, שידר","OBS shook hands with the ingest server, connected to its live app, got stream 1 and published to it with the stream key. The video and audio then flowed in chunks over the same TCP connection until the streamer stopped. Press REPLAY to watch it again.":"OBS ביצע לחיצת יד עם שרת הקליטה, התחבר לאפליקציית live שלו, קיבל את stream 1 ופרסם אליו עם מפתח השידור. אחר כך הווידאו והשמע זרמו בנתחים באותו חיבור TCP עד שהמשדר עצר. לחצו על ״שוב״ כדי לצפות שוב.","One TCP, port 1935":"חיבור TCP אחד, פורט 1935",Stream:"זרם",Chunks:"נתחים","Up to 4,096 bytes":"עד 4,096 בתים","None: RTMPS adds TLS":"אין: RTMPS מוסיף TLS","TCP, then RTMP’s own":"TCP, ואז של RTMP","The streamer clicks Start Streaming. OBS connects to the ingest server on TCP port 1935, then RTMP has its own handshake: version 3 and 1,536 random bytes each way, which each side sends back. It shows both ends speak RTMP; it encrypts nothing.":"המשדר לוחץ על התחלת שידור. OBS מתחבר לשרת הקליטה בפורט TCP ‏1935, ואז ל-RTMP יש לחיצת יד משלו: גרסה 3 ו-1,536 בתים אקראיים בכל כיוון, שכל צד מחזיר. היא מראה ששני הצדדים מדברים RTMP; היא לא מצפינה כלום.","Each side":"כל צד","Sends 3,073 bytes":"שולח 3,073 בתים","version 3":"גרסה 3","1,536 random bytes":"‏1,536 בתים אקראיים","version 3, its own bytes":"גרסה 3, הבתים שלו","and C1 sent back":"ו-C1 מוחזר","S1 sent back":"S1 מוחזר",Connect:"התחברות","To the server’s live app":"לאפליקציית live בשרת","OBS raises its chunk size to 4,096 bytes and sends connect for the app called live, in AMF0, a compact binary format from Flash. The server sets its own window, bandwidth and chunk size, and answers _result: NetConnection.Connect.Success.":"OBS מגדיל את גודל הנתח ל-4,096 בתים ושולח connect לאפליקציה בשם live, ב-AMF0, פורמט בינארי קומפקטי מ-Flash. השרת קובע חלון, רוחב פס וגודל נתח משלו, ועונה _result: ‏NetConnection.Connect.Success.",App:"אפליקציה",Encoding:"קידוד","chunk size 4,096":"גודל נתח 4,096","window, bandwidth, chunks":"חלון, רוחב פס, נתחים","Make a Stream":"יצירת זרם","createStream returns stream 1":"createStream מחזיר את stream 1","Every message names a message stream; 0 is the connection itself. OBS releases and announces its stream key, then asks createStream for a stream to send on, all three commands in one packet. The server answers with stream ID 1.":"כל הודעה מציינת זרם הודעות; 0 הוא החיבור עצמו. OBS משחרר ומכריז על מפתח השידור שלו, ואז מבקש ב-createStream זרם לשלוח עליו, שלוש הפקודות בחבילה אחת. השרת עונה עם stream ID 1.","3 in one packet":"3 בחבילה אחת",Gets:"מקבל","Stream ID 1":"Stream ID 1","stream ID 1":"stream ID 1",Publish:"פרסום","The stream key goes live":"מפתח השידור עולה לאוויר","publish names the stream key, the secret that says whose channel this is. RTMP has no encryption, so the key crosses in plain text; platforms prefer RTMPS, the same over TLS. The server checks the key and answers NetStream.Publish.Start.":"publish מציין את מפתח השידור, הסוד שאומר של מי הערוץ. ב-RTMP אין הצפנה, לכן המפתח עובר כטקסט גלוי; פלטפורמות מעדיפות RTMPS, אותו דבר מעל TLS. השרת בודק את המפתח ועונה NetStream.Publish.Start.","The stream key":"את מפתח השידור","None (RTMPS adds TLS)":"אין (RTMPS מוסיף TLS)","on stream 1":"על stream 1","stream key, live":"מפתח שידור, live","Video and Sound":"תמונה וקול","Metadata, settings, then frames":"מטא-נתונים, הגדרות ואז פריימים","OBS describes the stream: 1920×1080 at 30 frames a second, H.264 video, AAC audio. It sends the decoders’ settings, then a key frame, about 30 KB cut into 4,096-byte chunks. Frames follow non-stop, on the same TCP connection.":"OBS מתאר את השידור: 1920×1080 ב-30 פריימים בשנייה, וידאו H.264, שמע AAC. הוא שולח את הגדרות המפענחים, ואז פריים מפתח של כ-30 KB חתוך לנתחים של 4,096 בתים. הפריימים ממשיכים בלי הפסקה, על אותו חיבור TCP.","AAC, 48 kHz stereo":"AAC, ‏48 kHz סטריאו","30 KB in 8 chunks":"‏30 KB ב-8 נתחים",METADATA:"מטא-נתונים","H.264 + AAC settings":"הגדרות H.264 ו-AAC","KEY FRAME":"פריים מפתח","8 chunks":"‏8 נתחים","Stop Streaming":"הפסקת השידור","FCUnpublish and deleteStream":"FCUnpublish ו-deleteStream","When the streamer clicks Stop Streaming, OBS sends FCUnpublish and deleteStream for stream 1. The server answers NetStream.Unpublish.Success and ends the broadcast for viewers. Then OBS closes the TCP connection.":"כשהמשדר לוחץ על הפסקת שידור, OBS שולח FCUnpublish ו-deleteStream עבור stream 1. השרת עונה NetStream.Unpublish.Success ומסיים את השידור לצופים. ואז OBS סוגר את חיבור ה-TCP.","C0: version":"C0: גרסה","RTMP version 3, the only one in use.":"גרסה 3 של RTMP, היחידה שבשימוש.",Time:"זמן","A timestamp; zero is allowed.":"חותמת זמן; אפס מותר.",Zero:"אפס","Random data":"נתונים אקראיים","Random bytes the server must send back.":"בתים אקראיים שהשרת חייב להחזיר.","S0: version":"S0: גרסה","Random bytes the client must send back.":"בתים אקראיים שהלקוח חייב להחזיר.","1,536 bytes: C1 back":"‏1,536 בתים: C1 מוחזר","The timestamp from the block it echoes.":"חותמת הזמן מהבלוק שהוא מחזיר.","Time read":"זמן קריאה","C1’s random bytes, sent back unchanged.":"הבתים האקראיים של C1, מוחזרים בלי שינוי.","1,536 bytes: S1 back":"‏1,536 בתים: S1 מוחזר","S1’s random bytes, sent back unchanged.":"הבתים האקראיים של S1, מוחזרים בלי שינוי.","RTMP · 2 messages":"RTMP · ‏2 הודעות","First message":"הודעה ראשונה","Chunk header":"כותרת נתח","type 0, chunk stream 2":"סוג 0, זרם נתחים 2","A full header follows: this chunk starts a message.":"כותרת מלאה בהמשך: הנתח הזה מתחיל הודעה.","Message stream":"זרם הודעות","Stream 0: the connection itself. (This number alone is little-endian.)":"זרם 0: החיבור עצמו. (רק המספר הזה הוא little-endian.)","Chunk size":"גודל נתח","From now on this side cuts messages into chunks of up to this size (128 until it says otherwise).":"מעכשיו הצד הזה חותך הודעות לנתחים עד הגודל הזה (128 עד שיאמר אחרת).","Second message":"הודעה שנייה","type 0, chunk stream 3":"סוג 0, זרם נתחים 3","Matches a reply to its request.":"מתאים תשובה לבקשה שלה.","Command object":"אובייקט הפקודה","object, 5 properties":"אובייקט, 5 מאפיינים","Which app on the server, and the address OBS was given.":"איזו אפליקציה בשרת, והכתובת ש-OBS קיבל.","End of object":"סוף האובייקט","RTMP · 4 messages":"RTMP · ‏4 הודעות","The other side should hear back after every this many bytes it sends.":"הצד השני אמור לקבל תגובה אחרי כל כמות כזאת של בתים שהוא שולח.","Bandwidth, limit":"רוחב פס, מגבלה","5,000,000 bytes, dynamic":"‏5,000,000 בתים, דינמי","How much the sender may have unacknowledged at once.":"כמה השולח יכול להחזיק בלי אישור בבת אחת.","Third message":"הודעה שלישית","Fourth message":"הודעה רביעית",Properties:"מאפיינים","object, 2 properties":"אובייקט, 2 מאפיינים",Information:"מידע","object, 4 properties":"אובייקט, 4 מאפיינים","RTMP · 3 messages":"RTMP · ‏3 הודעות","Nothing: AMF0 null.":"כלום: null של AMF0.","Stream key":"מפתח שידור","Which channel this is. It works like a password, and here it travels unencrypted.":"איזה ערוץ זה. הוא פועל כמו סיסמה, וכאן הוא עובר בלי הצפנה.","Stream ID":"Stream ID","The new stream: video and audio will go on it.":"הזרם החדש: הווידאו והשמע יעברו עליו.","type 0, chunk stream 4":"סוג 0, זרם נתחים 4","Stream 1, the one createStream made.":"זרם 1, זה ש-createStream יצר.","Publishing type":"סוג פרסום","Live: not recorded by this request.":"Live: הבקשה הזאת לא מקליטה.","type 0, chunk stream 5":"סוג 0, זרם נתחים 5","object, 3 properties":"אובייקט, 3 מאפיינים",Handler:"מטפל",Event:"אירוע",Metadata:"מטא-נתונים","array of 14":"מערך של 14","Codec IDs as in Flash video files: 7 is H.264, 10 is AAC.":"מזהי קודק כמו בקובצי וידאו של Flash: ‏7 הוא H.264, ‏10 הוא AAC.","type 0, chunk stream 6":"סוג 0, זרם נתחים 6","Frame, codec":"פריים, קודק","0x17 (key frame, H.264)":"0x17 (פריים מפתח, H.264)","AVC packet type":"סוג חבילת AVC","0 (decoder settings)":"0 (הגדרות המפענח)","The sequence header: the settings a decoder needs before the first frame.":"כותרת הרצף: ההגדרות שמפענח צריך לפני הפריים הראשון.","Composition time":"זמן הרכבה","The H.264 profile, level and parameter sets.":"הפרופיל, הרמה וערכות הפרמטרים של H.264.","AAC; the other bits are fixed for AAC.":"AAC; שאר הביטים קבועים ב-AAC.","AAC packet type":"סוג חבילת AAC","Sample rate and channels, for the decoder.":"קצב הדגימה והערוצים, בשביל המפענח.","1 (video)":"1 (וידאו)","Compressed picture data.":"נתוני תמונה דחוסים.","The key frame: a whole picture. Every 4,096 bytes a 1-byte chunk header continues it.":"פריים המפתח: תמונה שלמה. כל 4,096 בתים, כותרת נתח של בית אחד (1) ממשיכה אותו."},r=s=>s==="1"?"רשומה אחת":`${s} רשומות`,l={strings:{...d,...h,...i},patterns:[[/^([\d,]+) bytes$/,"$1 בתים"],[/^(Ethernet II|IPv4|IPv6|UDP|TCP|802\.11|LLC\/SNAP|EAPOL) · (\d+) bytes$/,"$1 · $2 בתים"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,(s,e,t)=>`${e}, ${t==="1"?"בית אחד":`${t} בתים`}`],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 בתים: report.pdf, בתים $2"],[/^(.+) h later$/,"כעבור $1 שעות"],[/^(.+) min later$/,"כעבור $1 דקות"],[/^(.+) s later$/,"כעבור $1 שניות"],[/^(\S+) \(relative\)$/,"$1 (יחסי)"],[/^(\d+) \(ephemeral\)$/,"$1 (זמני)"],[/^(\d+) TCP segments$/,"$1 מקטעי TCP"],[/^(\d+) segments$/,"$1 מקטעים"],[/^(.*), (\d+) segments$/,"$1, $2 מקטעים"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(s,e,t,o)=>`TLS 1.3 · ${r(e)} · בתים ${t} מתוך ${o}`],[/^TLS 1\.3 · (\d+) records?$/,(s,e)=>`TLS 1.3 · ${r(e)}`],[/^Ethernet padding · (\d+) bytes$/,"ריפוד Ethernet · $1 בתים"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 בתים של אפסים, עד המינימום של 300 בתים"],[/^(\d+) zero bytes$/,"$1 בתים של אפסים"],[/^(\d+) random bytes$/,"$1 בתים אקראיים"],[/^Seen as it leaves (.+)$/,"כפי שנראתה ביציאה מ־$1"],[/^Option (\d+)$/,"אפשרות $1"],[/^value (\d+), echo (\d+)$/,"ערך $1, הד $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 בתים, ועוד $1 של אפשרויות."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows מתחיל ב־$1. כאן הוגדר ל־$2 בכוונה."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(s,e,t)=>t==="1"?`התחיל ב־${e}; הנתב היחיד בדרך הוריד 1.`:`התחיל ב־${e}; כל אחד מ־${t} הנתבים בדרך הוריד 1.`],[/^all (\d+) bytes of it$/,"כל $1 הבתים שלה"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"החבילה שגרמה לכך, כפי שהמכשיר המדווח קיבל אותה (TTL $1), כדי שהשולח יוכל לזהות באיזו חבילה מדובר."],[/^Port (\d+), TLS from the start$/,"פורט $1, TLS מההתחלה"],[/^(\d+), TLS from the start$/,"$1, TLS מההתחלה"],[/^type 79, (\d+) bytes$/,"סוג 79, $1 בתים"],[/^(\d+) of (\d+) bytes$/,"$1 מתוך $2 בתים"],[/^(\d+) more bytes$/,"עוד $1 בתים"],[/^offset (\d+), (\d+) bytes$/,"היסט $1, $2 בתים"],[/^offset 0, (\d+) bytes \(all of it\)$/,"היסט 0, $1 בתים (כולו)"],[/^record, (\d+) bytes$/,"רשומה, $1 בתים"],[/^EAPOL-Key · message (\d) of 4$/,"EAPOL-Key · הודעה $1 מתוך 4"],[/^((?:SMB2|IKEv2) · )?([A-Z_]+) (request|response)$/,(s,e,t,o)=>{const a=o==="request"?"בקשת":"תשובת";return e?`${e}${a} ${t}`:`${a[0].toUpperCase()}${a.slice(1)} ${t}`}],[/^(\d+) registers$/,"$1 רגיסטרים"],[/^id 1: −(\d+) dBov, voice$/,"id 1: −$1 dBov, דיבור"],[/^"(.*)" \(([\d,]+) bytes\)$/,'"$1" ($2 בתים)'],[/^(masked|not masked), (\d+) bytes?$/,(s,e,t)=>`${e==="masked"?"ממוסך":"לא ממוסך"}, ${t} בתים`],[/^(\d+) \(disguised\)$/,"$1 (מוסווה)"],[/^(\d+) \((KE|Nonce|Notify|IDi|IDr)\), (\d+) bytes$/,"$1 ($2), $3 בתים"],[/^0 \(none\), (\d+) bytes$/,"0 (אין), $1 בתים"],[/^Microsoft \(311\), type (\d+)$/,"Microsoft (311), סוג $1"],[/^(\d+) \(register (\d+)\)$/,"$1 (רגיסטר $2)"],[/^yes, AS (\d+)$/,"כן, AS $1"],[/^id 2, (\d+) bytes$/,"id 2, $1 בתים"],[/^(\d), (\d+) \((Opus|VP8), as agreed in the SDP\)$/,"$1, $2 ($3, כפי שסוכם ב־SDP)"]],post:n};export{l as default};
